/** Derives a compact HUD snapshot from RTCPeerConnection.getStats() deltas. */
export interface HudStats {
  fps: number;
  rttMs: number | null;
  jitterMs: number;
  bitrateMbps: number;
  decodeMs: number | null;
  lossPct: number;
  jitterBufferMs: number | null;
  width: number;
  height: number;
  codec: string;
  framesDropped: number;
  candidate: string; // host / srflx / relay
  inputRttMs: number | null;
}

export const EMPTY_STATS: HudStats = {
  fps: 0,
  rttMs: null,
  jitterMs: 0,
  bitrateMbps: 0,
  decodeMs: null,
  lossPct: 0,
  jitterBufferMs: null,
  width: 0,
  height: 0,
  codec: '—',
  framesDropped: 0,
  candidate: '—',
  inputRttMs: null,
};

interface Prev {
  t: number;
  bytes: number;
  frames: number;
  decodeTime: number;
  decoded: number;
  lost: number;
  received: number;
  jbDelay: number;
  jbEmitted: number;
}

type AnyStat = Record<string, unknown> & { type: string; id: string };
const num = (v: unknown, d = 0): number => (typeof v === 'number' && Number.isFinite(v) ? v : d);

export class StatsSampler {
  private prev: Prev | null = null;

  async sample(pc: RTCPeerConnection, inputRttMs: number | null): Promise<HudStats> {
    const report = await pc.getStats();
    let inbound: AnyStat | undefined;
    let transport: AnyStat | undefined;
    const byId = new Map<string, AnyStat>();
    report.forEach((s: AnyStat) => {
      byId.set(s.id, s);
      if (s.type === 'inbound-rtp' && (s.kind === 'video' || s.mediaType === 'video')) {
        // Pick the busiest video stream (simulcast-safe).
        if (!inbound || num(s.bytesReceived) > num(inbound.bytesReceived)) inbound = s;
      }
      if (s.type === 'transport') transport = s;
    });

    let pair: AnyStat | undefined;
    if (transport?.selectedCandidatePairId) pair = byId.get(String(transport.selectedCandidatePairId));
    if (!pair) report.forEach((s: AnyStat) => {
      if (s.type === 'candidate-pair' && (s.nominated || s.selected) && s.state === 'succeeded') pair = s;
    });

    const out: HudStats = { ...EMPTY_STATS, inputRttMs };
    if (pair) {
      if (typeof pair.currentRoundTripTime === 'number') out.rttMs = pair.currentRoundTripTime * 1000;
      const local = byId.get(String(pair.localCandidateId));
      const remote = byId.get(String(pair.remoteCandidateId));
      const lt = String(local?.candidateType ?? '?');
      const rt = String(remote?.candidateType ?? '?');
      out.candidate = lt === 'relay' || rt === 'relay' ? 'relay (TURN)' : lt === 'host' && rt === 'host' ? 'direct LAN' : `${lt}↔${rt}`;
    }
    if (!inbound) {
      this.prev = null;
      return out;
    }

    const now = num(inbound.timestamp, performance.now());
    const cur: Prev = {
      t: now,
      bytes: num(inbound.bytesReceived),
      frames: num(inbound.framesDecoded),
      decodeTime: num(inbound.totalDecodeTime),
      decoded: num(inbound.framesDecoded),
      lost: num(inbound.packetsLost),
      received: num(inbound.packetsReceived),
      jbDelay: num(inbound.jitterBufferDelay),
      jbEmitted: num(inbound.jitterBufferEmittedCount),
    };
    out.jitterMs = num(inbound.jitter) * 1000;
    out.width = num(inbound.frameWidth);
    out.height = num(inbound.frameHeight);
    out.framesDropped = num(inbound.framesDropped);
    const codec = inbound.codecId ? byId.get(String(inbound.codecId)) : undefined;
    out.codec = codec ? String(codec.mimeType ?? '').replace('video/', '') : '—';

    const p = this.prev;
    if (p && cur.t > p.t) {
      const dt = (cur.t - p.t) / 1000;
      out.bitrateMbps = ((cur.bytes - p.bytes) * 8) / dt / 1e6;
      out.fps = typeof inbound.framesPerSecond === 'number' ? inbound.framesPerSecond : (cur.frames - p.frames) / dt;
      const dDec = cur.decoded - p.decoded;
      if (dDec > 0) out.decodeMs = ((cur.decodeTime - p.decodeTime) / dDec) * 1000;
      const dLost = Math.max(0, cur.lost - p.lost);
      const dRecv = Math.max(0, cur.received - p.received);
      out.lossPct = dLost + dRecv > 0 ? (dLost / (dLost + dRecv)) * 100 : 0;
      const dEm = cur.jbEmitted - p.jbEmitted;
      if (dEm > 0) out.jitterBufferMs = ((cur.jbDelay - p.jbDelay) / dEm) * 1000;
    } else {
      out.fps = num(inbound.framesPerSecond);
    }
    this.prev = cur;
    return out;
  }

  reset(): void {
    this.prev = null;
  }
}
