// Vendored from leestream-touch (2026-11-26 package, src/audio/unlock.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// AudioContext unlock & auto-resume for iOS/iPadOS Safari, Brave, Chrome Android and macOS PWAs.
//
// Browsers only let an AudioContext run after a user gesture, and mobile Safari suspends or
// "interrupts" it on calls, Siri, lock screen, route changes and backgrounding. This keeps one
// context alive across all of that:
//  * creates the context lazily inside the first gesture (iOS requires creation+resume in a gesture),
//  * plays a 1-sample silent buffer in that gesture (WebKit unlock),
//  * asks for the 'playback' audio session so the iPhone ringer switch does not mute it (Safari 16.4+),
//  * re-arms gesture listeners whenever the state leaves 'running', and retries on
//    visibilitychange/pageshow/focus; when retrying cannot work without a tap, it reports
//    `needsGesture` so the UI can show a "Tap to enable sound" pill.

export type UnlockState = 'locked' | 'running' | 'suspended' | 'interrupted' | 'closed';

export interface AudioCtxLike {
  state: string;
  sampleRate: number;
  currentTime: number;
  resume(): Promise<void>;
  suspend(): Promise<void>;
  close(): Promise<void>;
  createBuffer(ch: number, len: number, rate: number): unknown;
  createBufferSource(): { buffer: unknown; connect(d: unknown): void; start(t?: number): void };
  destination: unknown;
  onstatechange: (() => void) | null;
}

export interface UnlockEnv {
  doc: Pick<Document, 'addEventListener' | 'removeEventListener' | 'visibilityState'>;
  win: Pick<Window, 'addEventListener' | 'removeEventListener'>;
  createContext: () => AudioCtxLike;
  nav?: { audioSession?: { type: string } };
}

const GESTURES = ['pointerup', 'touchend', 'click', 'keydown'] as const;

export class AudioUnlocker {
  ctx: AudioCtxLike | null = null;
  private armed = false;
  private wanted = false;                       // user wants sound on
  private listeners = new Set<(s: UnlockState, needsGesture: boolean) => void>();
  private onGesture = () => { void this.unlockNow(); };
  private onVisible = () => { if (this.env.doc.visibilityState === 'visible') void this.tryResume(); };

  constructor(private env: UnlockEnv) {
    env.doc.addEventListener('visibilitychange', this.onVisible);
    env.win.addEventListener('pageshow', this.onVisible);
    env.win.addEventListener('focus', this.onVisible);
  }

  static browser(): AudioUnlocker {
    const AC = (window as unknown as { AudioContext?: new (o?: object) => AudioCtxLike; webkitAudioContext?: new (o?: object) => AudioCtxLike });
    const Ctor = AC.AudioContext ?? AC.webkitAudioContext;
    return new AudioUnlocker({
      doc: document,
      win: window,
      nav: navigator as unknown as { audioSession?: { type: string } },
      createContext: () => {
        if (!Ctor) throw new Error('Web Audio not supported');
        try { return new Ctor({ latencyHint: 'interactive', sampleRate: 48000 }); }
        catch { return new Ctor({ latencyHint: 'interactive' }); }   // old Safari rejects sampleRate
      },
    });
  }

  get state(): UnlockState {
    if (!this.ctx) return 'locked';
    const s = this.ctx.state;
    return s === 'running' ? 'running' : s === 'closed' ? 'closed' : s === 'interrupted' ? 'interrupted' : 'suspended';
  }

  /** True when sound is wanted but only a tap can start it. */
  get needsGesture(): boolean { return this.wanted && this.state !== 'running'; }

  onChange(fn: (s: UnlockState, needsGesture: boolean) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }
  private notify(): void { for (const fn of this.listeners) fn(this.state, this.needsGesture); }

  /** Turn sound on. Call from a gesture handler if you can; otherwise the next tap unlocks. */
  enable(): Promise<boolean> {
    this.wanted = true;
    this.arm();
    return this.unlockNow();
  }

  /** Turn sound off (keeps the context for a fast re-enable). */
  async disable(): Promise<void> {
    this.wanted = false;
    this.disarm();
    try { await this.ctx?.suspend(); } catch { /* ignore */ }
    this.notify();
  }

  /** Must run synchronously inside a user gesture on iOS: create, resume and prime in one go. */
  unlockNow(): Promise<boolean> {
    if (!this.wanted) return Promise.resolve(false);
    try {
      if (this.env.nav?.audioSession) this.env.nav.audioSession.type = 'playback';
    } catch { /* older Safari: read-only */ }
    if (!this.ctx || this.ctx.state === 'closed') {
      try { this.ctx = this.env.createContext(); }
      catch { this.notify(); return Promise.resolve(false); }
      this.ctx.onstatechange = () => {
        if (this.state !== 'running' && this.wanted) this.arm();
        else if (this.state === 'running') this.disarm();
        this.notify();
      };
    }
    const ctx = this.ctx;
    try {   // WebKit: playing a buffer inside the gesture is what actually unlocks output
      const b = ctx.createBuffer(1, 1, ctx.sampleRate);
      const s = ctx.createBufferSource();
      s.buffer = b; s.connect(ctx.destination); s.start(0);
    } catch { /* ignore */ }
    const p = ctx.resume().then(
      () => { const ok = ctx.state === 'running'; if (ok) this.disarm(); this.notify(); return ok; },
      () => { this.notify(); return false; },
    );
    return p;
  }

  private async tryResume(): Promise<void> {
    if (!this.wanted || !this.ctx || this.ctx.state === 'running' || this.ctx.state === 'closed') return;
    try { await this.ctx.resume(); } catch { /* needs a gesture */ }
    if (this.ctx.state !== 'running') this.arm();
    this.notify();
  }

  private arm(): void {
    if (this.armed) return;
    this.armed = true;
    for (const g of GESTURES) this.env.doc.addEventListener(g, this.onGesture, { capture: true, passive: true } as AddEventListenerOptions);
  }
  private disarm(): void {
    if (!this.armed) return;
    this.armed = false;
    for (const g of GESTURES) this.env.doc.removeEventListener(g, this.onGesture, { capture: true } as EventListenerOptions);
  }

  async close(): Promise<void> {
    this.wanted = false;
    this.disarm();
    this.env.doc.removeEventListener('visibilitychange', this.onVisible);
    this.env.win.removeEventListener('pageshow', this.onVisible);
    this.env.win.removeEventListener('focus', this.onVisible);
    try { await this.ctx?.close(); } catch { /* ignore */ }
    this.ctx = null;
  }
}
