import { MouseButton } from './protocol';
import type { InputController } from './input';

export type TouchMode = 'trackpad' | 'direct';

export interface TouchOptions {
  /** Return false to ignore touches on the surface entirely (e.g. car virtual-gamepad mode). */
  enabled?: () => boolean;
  /** 2-finger scroll keeps gliding after lift-off (car giant trackpad). */
  inertia?: () => boolean;
  /** Tap-and-a-half drag stays held after lifting; the next tap drops it (car giant trackpad). */
  dragLock?: () => boolean;
  onDragLock?: (held: boolean) => void;
}

interface TouchPt {
  x: number;
  y: number;
  sx: number;
  sy: number;
  t0: number;
}

const TAP_MS = 220;
const TAP_SLOP = 10; // px
const DOUBLE_TAP_MS = 300;
const LONG_PRESS_MS = 550;

/**
 * Turns touch pointers into mouse input.
 *
 * Trackpad (default on iPad / Android tablets — like a laptop touchpad):
 *   1-finger drag      → move cursor (relative, with gentle acceleration)
 *   1-finger tap       → left click
 *   tap, then drag     → left-button drag (tap-and-a-half)
 *   2-finger tap       → right click
 *   2-finger drag      → scroll (vertical + horizontal)
 *   3-finger tap       → toggle on-screen keyboard
 *
 * Direct (touchscreen):
 *   touch              → move + left down at finger, lift → left up
 *   long-press         → right click
 *   2-finger drag/tap  → scroll / right click
 */
export class TouchGestures {
  private pts = new Map<number, TouchPt>();
  private maxPts = 0;
  private gestureStart = 0;
  private lastTapEnd = 0;
  private lastTapPos = { x: 0, y: 0 };
  private dragging = false;
  private scrolled = false;
  private moved = false;
  private longPressTimer = 0;
  private directDown = false;
  private disposers: Array<() => void> = [];
  private dragHeld = false;
  private vel = { x: 0, y: 0, t: 0 };
  private glideRaf = 0;
  private opts: TouchOptions;

  private surface: HTMLElement;
  private input: InputController;
  private mode: () => TouchMode;
  private sensitivity: () => number;
  private onThreeFingerTap: () => void;

  constructor(
    surface: HTMLElement,
    input: InputController,
    mode: () => TouchMode,
    sensitivity: () => number,
    onThreeFingerTap: () => void,
    opts: TouchOptions = {},
  ) {
    this.opts = opts;
    this.surface = surface;
    this.input = input;
    this.mode = mode;
    this.sensitivity = sensitivity;
    this.onThreeFingerTap = onThreeFingerTap;
  }

  attach(): void {
    const add = <K extends keyof HTMLElementEventMap>(ev: K, fn: (e: HTMLElementEventMap[K]) => void) => {
      this.surface.addEventListener(ev, fn as EventListener, { passive: false });
      this.disposers.push(() => this.surface.removeEventListener(ev, fn as EventListener));
    };
    add('pointerdown', (e) => this.down(e));
    add('pointermove', (e) => this.move(e));
    add('pointerup', (e) => this.up(e));
    add('pointercancel', (e) => this.up(e, true));
    // iOS Safari: block pinch-zoom / double-tap-zoom on the stream surface.
    add('touchstart', (e) => e.preventDefault());
    add('gesturestart' as keyof HTMLElementEventMap, (e) => e.preventDefault());
  }

  detach(): void {
    this.disposers.forEach((d) => d());
    this.disposers = [];
    clearTimeout(this.longPressTimer);
    cancelAnimationFrame(this.glideRaf);
    if (this.dragHeld) this.setDragHeld(false, true);
  }

  private setDragHeld(on: boolean, release = false): void {
    this.dragHeld = on;
    if (release) this.input.sendButton(MouseButton.Left, false);
    this.opts.onDragLock?.(on);
  }

  /** Inertial scroll: keep emitting wheel deltas with friction after a 2-finger fling. */
  private glide(): void {
    cancelAnimationFrame(this.glideRaf);
    let { x, y } = this.vel;
    const step = () => {
      x *= 0.93;
      y *= 0.93;
      if (Math.hypot(x, y) < 0.6) return;
      this.input.sendWheel(-x * 3, y * 3);
      this.glideRaf = requestAnimationFrame(step);
    };
    if (Math.hypot(x, y) > 2) this.glideRaf = requestAnimationFrame(step);
  }

  private down(e: PointerEvent): void {
    if (e.pointerType !== 'touch') return;
    if (this.opts.enabled && !this.opts.enabled()) return;
    e.preventDefault();
    cancelAnimationFrame(this.glideRaf);
    capture(this.surface, e.pointerId);
    const now = performance.now();
    if (this.pts.size === 0) {
      this.gestureStart = now;
      this.maxPts = 0;
      this.moved = false;
      this.scrolled = false;
      this.vel = { x: 0, y: 0, t: 0 };
    }
    this.pts.set(e.pointerId, { x: e.clientX, y: e.clientY, sx: e.clientX, sy: e.clientY, t0: now });
    this.maxPts = Math.max(this.maxPts, this.pts.size);

    if (this.mode() === 'trackpad') {
      // tap-and-a-half: second touch shortly after a tap, near the same place → start a drag.
      if (
        this.pts.size === 1 &&
        !this.dragHeld &&
        now - this.lastTapEnd < DOUBLE_TAP_MS &&
        Math.hypot(e.clientX - this.lastTapPos.x, e.clientY - this.lastTapPos.y) < 40
      ) {
        this.dragging = true;
        this.input.sendButton(MouseButton.Left, true);
      }
    } else if (this.pts.size === 1) {
      this.input.sendAbsFromClient(e.clientX, e.clientY);
      clearTimeout(this.longPressTimer);
      this.longPressTimer = window.setTimeout(() => {
        if (!this.moved && this.pts.size === 1 && !this.directDown) {
          this.input.sendButton(MouseButton.Right, true);
          this.input.sendButton(MouseButton.Right, false);
          this.moved = true; // suppress the left click on lift
        }
      }, LONG_PRESS_MS);
    } else {
      clearTimeout(this.longPressTimer);
      if (this.directDown) {
        this.input.sendButton(MouseButton.Left, false);
        this.directDown = false;
      }
    }
  }

  private move(e: PointerEvent): void {
    if (e.pointerType !== 'touch') return;
    const p = this.pts.get(e.pointerId);
    if (!p) return;
    e.preventDefault();
    const dx = e.clientX - p.x;
    const dy = e.clientY - p.y;
    p.x = e.clientX;
    p.y = e.clientY;
    if (Math.hypot(p.x - p.sx, p.y - p.sy) > TAP_SLOP) this.moved = true;

    if (this.pts.size >= 2) {
      // Scroll with the centroid motion; only one pointer reports to avoid double counting.
      const first = this.pts.keys().next().value;
      if (e.pointerId !== first) return;
      if (this.moved) {
        this.scrolled = true;
        this.input.sendWheel(-dx * 3, dy * 3);
        // per-event velocity (px per move event, smoothed) for inertia
        this.vel = { x: this.vel.x * 0.5 + dx * 0.5, y: this.vel.y * 0.5 + dy * 0.5, t: performance.now() };
      }
      return;
    }

    if (this.mode() === 'trackpad') {
      const speed = Math.hypot(dx, dy);
      const accel = 1 + Math.min(2.5, speed / 12); // slow = precise, fast = travel
      const k = 1.4 * accel * this.sensitivity();
      this.input.sendRelative(dx * k, dy * k);
    } else {
      if (!this.directDown && this.moved) {
        clearTimeout(this.longPressTimer);
        this.directDown = true;
        this.input.sendButton(MouseButton.Left, true);
      }
      this.input.sendAbsFromClient(e.clientX, e.clientY);
    }
  }

  private up(e: PointerEvent, cancelled = false): void {
    if (e.pointerType !== 'touch') return;
    const p = this.pts.get(e.pointerId);
    if (!p) return;
    e.preventDefault();
    this.pts.delete(e.pointerId);
    if (this.pts.size > 0) return; // wait for the whole gesture to end

    clearTimeout(this.longPressTimer);
    const now = performance.now();
    const wasTap = !cancelled && !this.moved && !this.scrolled && now - this.gestureStart < TAP_MS * (this.maxPts > 1 ? 1.6 : 1);

    if (this.mode() === 'trackpad') {
      if (this.dragging) {
        this.dragging = false;
        this.lastTapEnd = 0;
        if (this.opts.dragLock?.() && this.moved) {
          this.setDragHeld(true); // keep the button held; next tap releases
          return;
        }
        this.input.sendButton(MouseButton.Left, false);
        return;
      }
      if (this.scrolled && this.opts.inertia?.() && now - this.vel.t < 80) this.glide();
      if (this.dragHeld) {
        if (wasTap) {
          this.setDragHeld(false, true);
          return;
        }
        return; // moving while drag-locked: button stays down
      }
      if (wasTap) {
        if (this.maxPts === 1) {
          this.input.sendButton(MouseButton.Left, true);
          this.input.sendButton(MouseButton.Left, false);
          this.lastTapEnd = now;
          this.lastTapPos = { x: p.x, y: p.y };
        } else if (this.maxPts === 2) {
          this.input.sendButton(MouseButton.Right, true);
          this.input.sendButton(MouseButton.Right, false);
        } else if (this.maxPts >= 3) {
          this.onThreeFingerTap();
        }
      }
    } else {
      if (this.directDown) {
        this.input.sendButton(MouseButton.Left, false);
        this.directDown = false;
      } else if (wasTap) {
        if (this.maxPts === 1) {
          this.input.sendButton(MouseButton.Left, true);
          this.input.sendButton(MouseButton.Left, false);
        } else if (this.maxPts === 2) {
          this.input.sendButton(MouseButton.Right, true);
          this.input.sendButton(MouseButton.Right, false);
        } else {
          this.onThreeFingerTap();
        }
      }
    }
  }
}

/** setPointerCapture throws for pointers the UA no longer considers active; never let that break input. */
function capture(el: HTMLElement, id: number): void {
  try {
    el.setPointerCapture?.(id);
  } catch {
    /* ignore */
  }
}
