// Bridges the touch package's batched InputEvent tuples ([kind, flags, a, b, c], the older
// lsinput.js layout) onto the v1.1.1 `input` channel, which carries one tagged event per message
// (src/lib/protocol.ts). No host / Rust protocol change.
import {
  encodeKey,
  encodeMouseAbs,
  encodeMouseButton,
  encodeMouseRel,
  encodeReleaseAll,
  encodeWheel,
  type MouseButtonId,
} from '../protocol';
import { ABS_MAX, type InputEvent, type InputSink } from './protocol';

export interface RawInputSink {
  sendInput(bytes: Uint8Array, droppable?: boolean): boolean;
}

const s16 = (v: number) => ((v & 0xffff) << 16) >> 16;

/** Translate one package event into v1.1.1 wire bytes (null for unknown kinds). */
export function toWire(e: InputEvent | readonly number[]): { bytes: Uint8Array; droppable: boolean } | null {
  const [kind, flags, a, b] = e;
  switch (kind) {
    case 1: return { bytes: encodeMouseAbs(a / ABS_MAX, b / ABS_MAX), droppable: true };
    case 2: return { bytes: encodeMouseRel(s16(a), s16(b)), droppable: true };
    case 3: return { bytes: encodeMouseButton(a as MouseButtonId, (flags & 1) !== 0), droppable: false };
    // package: wheel(dy, dx), dy > 0 = up; v1.1.1 encodeWheel(dx, dy), +120 = up / right
    case 4: return { bytes: encodeWheel(s16(b), s16(a)), droppable: false };
    case 5: return { bytes: encodeKey(a, (flags & 1) !== 0, (flags & 2) !== 0), droppable: false };
    case 6: return { bytes: encodeReleaseAll(), droppable: false };
    default: return null;
  }
}

export class WireSink implements InputSink {
  constructor(private out: RawInputSink) {}
  push(e: InputEvent | number[]): void {
    const w = toWire(e);
    if (w) this.out.sendInput(w.bytes, w.droppable);
  }
}
