/**
 * "My Devices": hosts this browser has paired with, for one-tap reconnects (UU Remote / ToDesk style).
 *
 * Each entry keeps the permanent 9-digit Device ID, a nickname, the signaling URL and the per-device pairing
 * secret the host issued after a password / 6-digit-code pairing. The secret lets this browser reconnect without
 * the password; anyone with access to this browser profile can do the same, so "Forget" removes it.
 * The access password itself is never stored.
 */
export interface SavedDevice {
  id: string; // 9 digits
  name: string;
  secret: string; // 64 hex
  wss: string;
  savedAt: number;
  lastUsed: number;
}

export const DEVICES_KEY = 'leestream.devices.v1';
export const CLOUD_WSS = 'wss://ls.23-95-112-86.sslip.io/ws';

type Store = Pick<Storage, 'getItem' | 'setItem'>;
const store = (): Store | null => {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
};

/** `123 456-789` → `123456789`; null unless exactly 9 digits not starting with 0. */
export function normaliseDeviceId(s: string): string | null {
  const d = s.replace(/[\s-]/g, '');
  return /^[1-9]\d{8}$/.test(d) ? d : null;
}

export function formatDeviceId(id: string): string {
  return id.length === 9 ? `${id.slice(0, 3)} ${id.slice(3, 6)} ${id.slice(6)}` : id;
}

function valid(d: unknown): d is SavedDevice {
  const x = d as SavedDevice;
  return !!x && typeof x.id === 'string' && normaliseDeviceId(x.id) === x.id && /^[0-9a-f]{64}$/i.test(x.secret ?? '') && typeof x.wss === 'string';
}

export function loadDevices(s: Store | null = store()): SavedDevice[] {
  try {
    const raw = s?.getItem(DEVICES_KEY);
    const list = raw ? (JSON.parse(raw) as unknown[]) : [];
    return list.filter(valid).sort((a, b) => b.lastUsed - a.lastUsed);
  } catch {
    return [];
  }
}

function persist(list: SavedDevice[], s: Store | null): SavedDevice[] {
  try {
    s?.setItem(DEVICES_KEY, JSON.stringify(list));
  } catch {
    /* private mode / quota: the list just isn't remembered */
  }
  return loadDevices(s);
}

/** Add or refresh a device (keeps a nickname the user already chose). */
export function upsertDevice(d: { id: string; secret: string; wss: string; name?: string }, s: Store | null = store(), now = Date.now()): SavedDevice[] {
  const id = normaliseDeviceId(d.id);
  if (!id || !/^[0-9a-f]{64}$/i.test(d.secret)) return loadDevices(s);
  const list = loadDevices(s);
  const old = list.find((x) => x.id === id);
  const next: SavedDevice = { id, secret: d.secret.toLowerCase(), wss: d.wss, name: old?.name || d.name || `PC ${formatDeviceId(id)}`, savedAt: old?.savedAt ?? now, lastUsed: now };
  return persist([next, ...list.filter((x) => x.id !== id)].slice(0, 32), s);
}

export function renameDevice(id: string, name: string, s: Store | null = store()): SavedDevice[] {
  const n = name.trim().slice(0, 40);
  return persist(loadDevices(s).map((x) => (x.id === id && n ? { ...x, name: n } : x)), s);
}

export function forgetDevice(id: string, s: Store | null = store()): SavedDevice[] {
  return persist(loadDevices(s).filter((x) => x.id !== id), s);
}
