/** `ls_proto::audio` frame unwrapping (kept free of DOM/TS-only syntax so node strip-types can test it). */
export interface AudioFrame {
  seq?: number;
  opus: boolean;
  dtx: boolean;
  payload: Uint8Array;
  redundancy?: Uint8Array;
}

/** Unwraps an `ls_proto::audio` frame ("LA" v1); anything else is treated as a bare Opus packet. */
export function parseAudioFrame(packet: ArrayBuffer): AudioFrame | null {
  const b = new Uint8Array(packet);
  if (b.length >= 12 && b[0] === 0x4c && b[1] === 0x41 && b[2] === 1) {
    const dv = new DataView(packet);
    const flags = b[9];
    const len = dv.getUint16(10, true);
    if (12 + len > b.length) return null;
    const f: AudioFrame = { seq: dv.getUint16(3, true), opus: (flags & 1) !== 0, dtx: (flags & 4) !== 0, payload: b.subarray(12, 12 + len) };
    if (flags & 8 && b.length >= 14 + len) {
      const rl = dv.getUint16(12 + len, true);
      if (rl > 0 && 14 + len + rl <= b.length) f.redundancy = b.subarray(14 + len, 14 + len + rl);
    }
    return f;
  }
  return b.length ? { opus: true, dtx: false, payload: b } : null;
}
