import { useEffect, useState } from 'react';

/** Live viewport size; follows rotation (BYD rotating screen), visualViewport and resize. */
export function useViewport(): { w: number; h: number } {
  const read = () => ({ w: window.innerWidth, h: window.innerHeight });
  const [vp, setVp] = useState(read);
  useEffect(() => {
    const on = () => setVp((p) => {
      const n = read();
      return n.w === p.w && n.h === p.h ? p : n;
    });
    window.addEventListener('resize', on);
    window.addEventListener('orientationchange', on);
    window.visualViewport?.addEventListener('resize', on);
    screen.orientation?.addEventListener?.('change', on);
    return () => {
      window.removeEventListener('resize', on);
      window.removeEventListener('orientationchange', on);
      window.visualViewport?.removeEventListener('resize', on);
      screen.orientation?.removeEventListener?.('change', on);
    };
  }, []);
  return vp;
}
