/**
 * Browser signaling: JSON over WebSocket.
 *
 *   client -> bridge   { type:"want",  code?:"123456", secret?:"...", offerer:"host"|"client", client:{...} }
 *   bridge -> client   { type:"paired", host:"DESKTOP-1", iceServers?:[...], trickle?:true }
 *   host   -> client   { type:"offer",  sdp:"v=0..." }          (offerer = "host", default)
 *   client -> host     { type:"answer", sdp:"v=0..." }
 *   client -> host     { type:"offer",  sdp }                  (offerer = "client")
 *   host   -> client   { type:"answer", sdp }
 *   either             { type:"ice", candidate:"candidate:..."|null, sdpMid, sdpMLineIndex }
 *   bridge -> client   { type:"error", code:"bad_code"|"host_offline"|"timeout"|..., message }
 *   either             { type:"bye", reason? }
 *
 * The bridge (bridge/ws-sig-bridge.rs) translates these 1:1 to ls_proto::sig
 * datagrams. `candidate:null` means end-of-candidates.
 */

export type Offerer = 'host' | 'client';

export type SigMsg =
  | {
      type: 'want';
      code?: string;
      secret?: string;
      /** v1.2 cloud rendezvous: permanent 9-digit Device ID (+ fixed access password, used once by the server for SPAKE2). */
      device?: string;
      password?: string;
      offerer: Offerer;
      /** Client can receive trickled `ice` after the offer (v1.1.1+). */
      trickle?: boolean;
      client: { name: string; ua: string; codecs: string[]; version: string };
    }
  | { type: 'paired'; host: string; iceServers?: RTCIceServer[]; trickle?: boolean; /** device secret after 6-digit pairing, for auto-reconnect (memory only) */ resume?: string }
  | { type: 'offer'; sdp: string }
  | { type: 'answer'; sdp: string }
  | { type: 'ice'; candidate: string | null; sdpMid?: string | null; sdpMLineIndex?: number | null; usernameFragment?: string | null }
  | { type: 'error'; code: string; message: string }
  | { type: 'bye'; reason?: string };

/** Anything that can carry signaling: the real WebSocket, or the in-page loopback host. */
export interface SignalTransport {
  send(msg: SigMsg): void;
  close(): void;
  onmessage: ((msg: SigMsg) => void) | null;
  onclose: ((reason: string) => void) | null;
  /** Resolves when the transport is ready to send. */
  ready: Promise<void>;
}

export class WebSocketSignal implements SignalTransport {
  private ws: WebSocket;
  onmessage: ((msg: SigMsg) => void) | null = null;
  onclose: ((reason: string) => void) | null = null;
  ready: Promise<void>;
  private closed = false;

  constructor(url: string, timeoutMs = 8000) {
    this.ws = new WebSocket(url, ['leestream-sig.v1']);
    this.ready = new Promise<void>((resolve, reject) => {
      const t = setTimeout(() => {
        reject(new Error(`Signaling server did not answer within ${timeoutMs / 1000}s`));
        this.ws.close();
      }, timeoutMs);
      this.ws.onopen = () => {
        clearTimeout(t);
        resolve();
      };
      this.ws.onerror = () => {
        clearTimeout(t);
        reject(new Error(`Could not reach signaling server at ${url}`));
      };
    });
    this.ws.onmessage = (ev) => {
      if (typeof ev.data !== 'string') return;
      try {
        const msg = JSON.parse(ev.data) as SigMsg;
        if (msg && typeof msg.type === 'string') this.onmessage?.(msg);
      } catch {
        /* ignore malformed frames */
      }
    };
    this.ws.onclose = (ev) => {
      if (this.closed) return;
      this.closed = true;
      this.onclose?.(ev.reason || `socket closed (${ev.code})`);
    };
  }

  send(msg: SigMsg): void {
    if (this.ws.readyState === WebSocket.OPEN) this.ws.send(JSON.stringify(msg));
  }

  close(): void {
    this.closed = true;
    try {
      this.send({ type: 'bye' });
      this.ws.close(1000, 'bye');
    } catch {
      /* noop */
    }
  }
}

/** Accepts "host:port", "ws://..", "wss://..", "https://..", or a pasted share link (`#car=1&wss=..`), and normalises to a ws(s) URL without fragments. */
export function normaliseSignalUrl(input: string): string {
  let s = input.trim();
  if (!s) return s;
  // Unwrap accidentally pasted share links such as https://.../web/#car=1&wss=... or ?sig=...
  const hashIdx = s.indexOf('#');
  if (hashIdx >= 0) {
    const hp = new URLSearchParams(s.slice(hashIdx + 1));
    const inner = hp.get('wss') ?? hp.get('sig');
    if (inner && /^(?:wss?|https?):\/\//i.test(inner)) {
      s = inner.trim();
    } else {
      s = s.slice(0, hashIdx);
    }
  }
  const qIdx = s.indexOf('?');
  if (qIdx >= 0) {
    const qp = new URLSearchParams(s.slice(qIdx + 1));
    const inner = qp.get('wss') ?? qp.get('sig');
    if (inner && /^(?:wss?|https?):\/\//i.test(inner)) {
      s = inner.trim();
    }
  }
  if (s.startsWith('https://')) s = 'wss://' + s.slice(8);
  else if (s.startsWith('http://')) s = 'ws://' + s.slice(7);
  else if (!/^wss?:\/\//.test(s)) {
    // Default to wss on secure pages (mixed-content rules), ws on http/LAN dev.
    const secure = typeof location !== 'undefined' && location.protocol === 'https:';
    s = (secure ? 'wss://' : 'ws://') + s;
  }
  const u = new URL(s);
  u.hash = '';
  if (u.pathname === '/' || u.pathname === '') u.pathname = '/ws';
  return u.toString();
}
