/**
 * SDP codec diagnostics for the host-offerer path.
 *
 * When the browser cannot receive any of the video codecs the host offers (e.g. Linux / Tesla Chromium has no
 * H.264 High profile decoder, so `profile-level-id=640033` alone is unusable), createAnswer() rejects the video
 * m-section (`m=video 0`). Chrome then fails setLocalDescription with the cryptic
 * "Failed to setup RTCP mux". These helpers detect that case up front and name the mismatch.
 */

export interface SdpCodec {
  pt: number;
  mime: string; // e.g. "H264"
  fmtp: string; // raw fmtp parameters, '' if none
}

const H264_PROFILES: Record<string, string> = {
  '42': 'Baseline',
  '4d': 'Main',
  '58': 'Extended',
  '64': 'High',
  '6e': 'High 10',
  '7a': 'High 4:2:2',
  f4: 'High 4:4:4',
};

/** Split an SDP into media sections; each starts with its m= line. */
function sections(sdp: string): string[][] {
  const out: string[][] = [];
  for (const raw of sdp.split(/\r?\n/)) {
    const l = raw.trim();
    if (!l) continue;
    if (l.startsWith('m=')) out.push([l]);
    else if (out.length) out[out.length - 1].push(l);
  }
  return out;
}

function videoSection(sdp: string): string[] | undefined {
  return sections(sdp).find((s) => s[0].startsWith('m=video'));
}

/** Video codecs of the m=video section, in payload order (rtx/red/fec excluded). */
export function videoCodecs(sdp: string): SdpCodec[] {
  const sec = videoSection(sdp);
  if (!sec) return [];
  const pts = sec[0].split(' ').slice(3).map(Number).filter((n) => Number.isFinite(n));
  const mime = new Map<number, string>();
  const fmtp = new Map<number, string>();
  for (const l of sec) {
    let m = /^a=rtpmap:(\d+)\s+([^/\s]+)/.exec(l);
    if (m) mime.set(Number(m[1]), m[2]);
    m = /^a=fmtp:(\d+)\s+(.*)$/.exec(l);
    if (m) fmtp.set(Number(m[1]), m[2]);
  }
  return pts
    .filter((pt) => mime.has(pt) && !/^(rtx|red|ulpfec|flexfec)$/i.test(mime.get(pt)!))
    .map((pt) => ({ pt, mime: mime.get(pt)!, fmtp: fmtp.get(pt) ?? '' }));
}

/** True when the SDP has a video m-section whose port is 0 (rejected). */
export function isVideoRejected(sdp: string): boolean {
  const sec = videoSection(sdp);
  return !!sec && /^m=video\s+0\s/.test(sec[0]);
}

/** Human label for one codec, e.g. "H264 High (640033)". */
export function codecLabel(c: { mime: string; fmtp: string }): string {
  const m = c.mime.replace(/^video\//i, '');
  if (/^h264$/i.test(m)) {
    const id = /profile-level-id=([0-9a-f]{6})/i.exec(c.fmtp)?.[1]?.toLowerCase();
    if (id) {
      const name = id === '42e01f' || id.startsWith('42e') || id.startsWith('42c') ? 'Constrained Baseline' : (H264_PROFILES[id.slice(0, 2)] ?? 'profile 0x' + id.slice(0, 2));
      return `H264 ${name} (${id})`;
    }
  }
  return m.toUpperCase();
}

function uniq(xs: string[]): string[] {
  return Array.from(new Set(xs));
}

/**
 * Message for the case where the browser rejected every offered video codec.
 * `receivable` is RTCRtpReceiver.getCapabilities('video').codecs (or a compatible list).
 */
export function codecMismatchMessage(offerSdp: string, receivable: { mimeType: string; sdpFmtpLine?: string }[]): string {
  const offered = uniq(videoCodecs(offerSdp).map(codecLabel));
  const can = uniq(
    receivable
      .filter((c) => !/rtx|red|ulpfec|flexfec/i.test(c.mimeType))
      .map((c) => codecLabel({ mime: c.mimeType, fmtp: c.sdpFmtpLine ?? '' })),
  );
  return (
    `No common video codec: the host offered ${offered.join(', ') || 'no video codec'}, ` +
    `but this browser can only receive ${can.join(', ') || 'nothing'}. ` +
    `Update LeeStream Host (1.1.1+ also offers H.264 Main/Constrained Baseline) or pick another codec.`
  );
}
