import { useEffect, useRef, useState, type FormEvent } from 'react';
import type { InputController, InputSink } from '../lib/input';
import { charToKey } from '../lib/textinput';
import { encodeUnicode } from '../lib/protocol';

const SENTINEL = '  ';

type Mod = 'ControlLeft' | 'AltLeft' | 'ShiftLeft' | 'MetaLeft';
const MODS: Array<[Mod, string]> = [
  ['ControlLeft', 'Ctrl'],
  ['AltLeft', 'Alt'],
  ['ShiftLeft', 'Shift'],
  ['MetaLeft', 'Win'],
];
const KEYS: Array<[string, string]> = [
  ['Escape', 'Esc'],
  ['Tab', 'Tab'],
  ['ArrowLeft', '←'],
  ['ArrowUp', '↑'],
  ['ArrowDown', '↓'],
  ['ArrowRight', '→'],
  ['Home', 'Home'],
  ['End', 'End'],
  ['PageUp', 'PgUp'],
  ['PageDown', 'PgDn'],
  ['Delete', 'Del'],
  ['Backspace', '⌫'],
  ['Enter', '⏎'],
  ['PrintScreen', 'PrtSc'],
];
const FKEYS = Array.from({ length: 12 }, (_, i) => `F${i + 1}`);

/**
 * On-screen keyboard: a hidden textarea summons the OS soft keyboard (iPad/Android),
 * typed characters are converted to scan-code taps (US layout) or INPUT_UNICODE; a
 * row of special keys with sticky modifiers covers what soft keyboards lack.
 */
export function VirtualKeyboard({ input, sink, onClose }: { input: InputController; sink: InputSink; onClose: () => void }) {
  const ta = useRef<HTMLTextAreaElement>(null);
  const [mods, setMods] = useState<Set<Mod>>(new Set());
  const [showF, setShowF] = useState(false);
  const modsRef = useRef(mods);
  modsRef.current = mods;

  useEffect(() => {
    ta.current?.focus({ preventScroll: true });
    return () => {
      // release sticky modifiers on close
      modsRef.current.forEach((m) => input.sendKeyCode(m, false));
    };
  }, [input]);

  const withMods = (fn: () => void) => {
    const held = [...modsRef.current];
    held.forEach((m) => input.sendKeyCode(m, true));
    fn();
    held.reverse().forEach((m) => input.sendKeyCode(m, false));
    if (held.length) setMods(new Set());
  };

  const tap = (code: string) => withMods(() => input.tapCombo([code]));

  const typeChar = (ch: string) => {
    const k = charToKey(ch);
    if (k) {
      const [code, shift] = k;
      withMods(() => input.tapCombo(shift && !modsRef.current.has('ShiftLeft') ? ['ShiftLeft', code] : [code]));
    } else {
      const cp = ch.codePointAt(0);
      if (cp !== undefined) {
        sink.sendInput(encodeUnicode(cp, true));
        sink.sendInput(encodeUnicode(cp, false));
      }
    }
  };

  const onInput = (e: FormEvent<HTMLTextAreaElement>) => {
    const ne = e.nativeEvent as InputEvent;
    const el = e.currentTarget;
    switch (ne.inputType) {
      case 'deleteContentBackward':
        tap('Backspace');
        break;
      case 'deleteContentForward':
        tap('Delete');
        break;
      case 'insertLineBreak':
      case 'insertParagraph':
        tap('Enter');
        break;
      default: {
        const text = ne.data ?? el.value.replace(SENTINEL, '');
        for (const ch of text) typeChar(ch);
      }
    }
    el.value = SENTINEL;
    el.setSelectionRange(SENTINEL.length, SENTINEL.length);
  };

  return (
    <div className="pointer-events-auto glass rounded-2xl p-2 max-w-[min(100vw-16px,900px)]" onPointerDown={(e) => e.stopPropagation()}>
      <textarea
        ref={ta}
        data-ls-capture="true"
        defaultValue={SENTINEL}
        onInput={onInput}
        autoCapitalize="off"
        autoCorrect="off"
        autoComplete="off"
        spellCheck={false}
        aria-label="Type to send keystrokes"
        className="absolute opacity-0 w-px h-px -z-10"
        style={{ fontSize: 16 /* stops iOS zooming on focus */ }}
      />
      <div className="flex flex-wrap items-center gap-1">
        {MODS.map(([code, label]) => (
          <Key
            key={code}
            label={label}
            active={mods.has(code)}
            onPress={() =>
              setMods((m) => {
                const n = new Set(m);
                if (n.has(code)) n.delete(code);
                else n.add(code);
                return n;
              })
            }
          />
        ))}
        <span className="mx-1 h-5 w-px bg-white/10" />
        {KEYS.map(([code, label]) => (
          <Key key={code} label={label} onPress={() => tap(code)} />
        ))}
        <Key label="Fn" active={showF} onPress={() => setShowF((s) => !s)} />
        <Key label="Ctrl+Alt+Del" onPress={() => input.tapCombo(['ControlLeft', 'AltLeft', 'Delete'])} />
        <Key label="⌨︎ Type" onPress={() => ta.current?.focus({ preventScroll: true })} />
        <Key label="✕" onPress={onClose} />
      </div>
      {showF && (
        <div className="mt-1 flex flex-wrap gap-1">
          {FKEYS.map((f) => (
            <Key key={f} label={f} onPress={() => tap(f)} />
          ))}
        </div>
      )}
    </div>
  );
}

function Key({ label, onPress, active }: { label: string; onPress: () => void; active?: boolean }) {
  return (
    <button
      // pointerdown + preventDefault keeps focus (and the soft keyboard) on the textarea
      onPointerDown={(e) => {
        e.preventDefault();
        e.stopPropagation();
        onPress();
      }}
      className={`h-9 min-w-9 rounded-lg px-2 text-xs font-medium transition ${active ? 'bg-accent text-black' : 'bg-white/8 text-slate-100 hover:bg-white/15 active:bg-white/25'}`}
    >
      {label}
    </button>
  );
}
