import { useState, type ReactNode } from 'react';
import type { MonitorInfo } from '../lib/protocol';
import type { MouseMode } from '../lib/input';
import type { TouchMode } from '../lib/touch';

export interface ToolbarProps {
  isFullscreen: boolean;
  onFullscreen: () => void;
  monitors: MonitorInfo[];
  currentMonitor: number;
  onMonitor: (i: number) => void;
  privacy: boolean;
  onPrivacy: () => void;
  onPaste: () => void;
  keyboardOpen: boolean;
  onKeyboard: () => void;
  mouseMode: MouseMode;
  onMouseMode: () => void;
  touch: boolean;
  touchMode: TouchMode;
  onTouchMode: () => void;
  hud: boolean;
  onHud: () => void;
  onCtrlAltDel: () => void;
  onDisconnect: () => void;
  gamepads: number;
}

export function Toolbar(p: ToolbarProps) {
  const [open, setOpen] = useState(true);
  const [monMenu, setMonMenu] = useState(false);

  if (!open) {
    return (
      <button onClick={() => setOpen(true)} className="glass pointer-events-auto rounded-b-xl px-4 py-1 text-xs text-slate-300" aria-label="Show toolbar">
        ▾ LeeStream
      </button>
    );
  }

  return (
    <div className="relative pointer-events-auto">
      <div className="glass flex items-center gap-0.5 rounded-2xl px-1.5 py-1 shadow-xl">
        <Btn label={p.isFullscreen ? 'Exit fullscreen' : 'Fullscreen'} onClick={p.onFullscreen}>
          {p.isFullscreen ? <Icon d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5" /> : <Icon d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5" />}
        </Btn>
        <Btn label="Switch monitor" onClick={() => (p.monitors.length > 1 ? setMonMenu((m) => !m) : p.onMonitor(p.currentMonitor + 1))} active={monMenu}>
          <Icon d="M3 5h18v11H3zM8 20h8M12 16v4" />
          <span className="ml-0.5 text-[10px] tabular-nums">{p.currentMonitor + 1}</span>
        </Btn>
        <Btn label={p.privacy ? 'Privacy screen ON' : 'Privacy screen'} onClick={p.onPrivacy} active={p.privacy}>
          <Icon d="M3 12s3.5-6 9-6 9 6 9 6-3.5 6-9 6-9-6-9-6zM4 4l16 16" />
        </Btn>
        <Btn label="Paste clipboard to host" onClick={p.onPaste}>
          <Icon d="M9 4h6v3H9zM7 5H5v15h14V5h-2" />
        </Btn>
        <Btn label="Keyboard" onClick={p.onKeyboard} active={p.keyboardOpen}>
          <Icon d="M3 7h18v10H3zM7 11h.01M11 11h.01M15 11h.01M7 14h10" />
        </Btn>
        <Sep />
        <Btn label={p.mouseMode === 'relative' ? 'Mouse: relative (FPS) — click for absolute' : 'Mouse: absolute — click for relative'} onClick={p.onMouseMode}>
          <span className="text-[10px] font-semibold w-7">{p.mouseMode === 'relative' ? 'REL' : 'ABS'}</span>
        </Btn>
        {p.touch && (
          <Btn label={p.touchMode === 'trackpad' ? 'Touch: trackpad — tap for direct touch' : 'Touch: direct — tap for trackpad'} onClick={p.onTouchMode}>
            <span className="text-[10px] font-semibold w-9">{p.touchMode === 'trackpad' ? 'PAD' : 'TOUCH'}</span>
          </Btn>
        )}
        <Btn label="Stats HUD" onClick={p.onHud} active={p.hud}>
          <Icon d="M4 19V9M10 19V5M16 19v-7M22 19H2" />
        </Btn>
        <Btn label="Send Ctrl+Alt+Del" onClick={p.onCtrlAltDel}>
          <span className="text-[9px] font-semibold">CAD</span>
        </Btn>
        {p.gamepads > 0 && (
          <span className="px-1.5 text-[10px] text-emerald-300" title={`${p.gamepads} controller(s) forwarding`}>
            🎮{p.gamepads}
          </span>
        )}
        <Sep />
        <Btn label="Disconnect" onClick={p.onDisconnect} danger>
          <Icon d="M18 6 6 18M6 6l12 12" />
        </Btn>
        <Btn label="Hide toolbar" onClick={() => setOpen(false)}>
          <Icon d="M6 15l6-6 6 6" />
        </Btn>
      </div>
      {monMenu && (
        <div className="glass absolute left-1/2 -translate-x-1/2 mt-2 min-w-64 rounded-xl p-1 text-sm">
          {p.monitors.map((m) => (
            <button
              key={m.index}
              onClick={() => {
                p.onMonitor(m.index);
                setMonMenu(false);
              }}
              className={`flex w-full items-center justify-between rounded-lg px-3 py-2 text-left hover:bg-white/10 ${m.index === p.currentMonitor ? 'text-accent' : 'text-slate-200'}`}
            >
              <span>
                {m.index + 1}. {m.name}
              </span>
              {m.primary && <span className="text-[10px] text-slate-500">primary</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function Btn({ label, onClick, children, active, danger }: { label: string; onClick: () => void; children: ReactNode; active?: boolean; danger?: boolean }) {
  return (
    <button
      title={label}
      aria-label={label}
      onClick={onClick}
      onPointerDown={(e) => e.stopPropagation()}
      className={`flex h-9 min-w-9 items-center justify-center rounded-xl px-1.5 transition ${
        danger ? 'text-red-300 hover:bg-red-500/20' : active ? 'bg-accent/20 text-accent' : 'text-slate-200 hover:bg-white/10'
      }`}
    >
      {children}
    </button>
  );
}

function Sep() {
  return <span className="mx-1 h-5 w-px bg-white/10" />;
}

function Icon({ d }: { d: string }) {
  return (
    <svg viewBox="0 0 24 24" className="h-[18px] w-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
      <path d={d} />
    </svg>
  );
}
