// Vendored from leestream-touch (2026-11-26 package, src/keyboard.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// Virtual desktop keyboard model: sticky modifiers, shortcuts, text typing. No DOM.
import { type InputSink, keyEv, scanOf } from './protocol';

export type Mod = 'ctrl' | 'alt' | 'shift' | 'win';
/** off → latched (one-shot: next key or click) → locked (until tapped again) → off */
export type ModState = 'off' | 'latched' | 'locked';

export const MOD_CODE: Record<Mod, string> = { ctrl: 'ControlLeft', alt: 'AltLeft', shift: 'ShiftLeft', win: 'MetaLeft' };
const MODS: Mod[] = ['ctrl', 'shift', 'alt', 'win'];

export interface Shortcut { id: string; label: string; keys: string[]; hint?: string }

