export interface KeyDef { code: string; label: string; shift?: string; w?: number; mod?: Mod }

const k = (code: string, label: string, shift?: string, w?: number): KeyDef => ({ code, label, shift, w });
const m = (mod: Mod, label: string, w = 1.5): KeyDef => ({ code: MOD_CODE[mod], label, w, mod });

/** Full desktop layout (US), page 'main' and page 'fn'. Widths in key units. */
export const LAYOUT: Record<'main' | 'fn', KeyDef[][]> = {
  main: [
    [k('Escape', 'Esc'), k('Backquote', '`', '~'), k('Digit1', '1', '!'), k('Digit2', '2', '@'), k('Digit3', '3', '#'), k('Digit4', '4', '$'),
      k('Digit5', '5', '%'), k('Digit6', '6', '^'), k('Digit7', '7', '&'), k('Digit8', '8', '*'), k('Digit9', '9', '('), k('Digit0', '0', ')'),
      k('Minus', '-', '_'), k('Equal', '=', '+'), k('Backspace', '⌫', undefined, 1.5)],
    [k('Tab', 'Tab', undefined, 1.5), ...'QWERTYUIOP'.split('').map((c) => k('Key' + c, c.toLowerCase(), c)),
      k('BracketLeft', '[', '{'), k('BracketRight', ']', '}'), k('Backslash', '\\', '|')],
    [k('CapsLock', 'Caps', undefined, 1.75), ...'ASDFGHJKL'.split('').map((c) => k('Key' + c, c.toLowerCase(), c)),
      k('Semicolon', ';', ':'), k('Quote', "'", '"'), k('Enter', '⏎', undefined, 1.75)],
    [m('shift', 'Shift', 2.25), ...'ZXCVBNM'.split('').map((c) => k('Key' + c, c.toLowerCase(), c)),
      k('Comma', ',', '<'), k('Period', '.', '>'), k('Slash', '/', '?'), k('ArrowUp', '↑'), k('Delete', 'Del')],
    [m('ctrl', 'Ctrl'), m('win', '⊞'), m('alt', 'Alt'), k('Space', '', undefined, 5), k('ArrowLeft', '←'), k('ArrowDown', '↓'), k('ArrowRight', '→')],
  ],
  fn: [
    ['F1', 'F2', 'F3', 'F4', 'F5', 'F6'].map((f) => k(f, f)),
    ['F7', 'F8', 'F9', 'F10', 'F11', 'F12'].map((f) => k(f, f)),
    [k('Insert', 'Ins'), k('Home', 'Home'), k('PageUp', 'PgUp'), k('PrintScreen', 'PrtSc'), k('ScrollLock', 'ScrLk'), k('ContextMenu', 'Menu')],
    [k('Delete', 'Del'), k('End', 'End'), k('PageDown', 'PgDn'), k('AudioVolumeDown', 'Vol−'), k('AudioVolumeUp', 'Vol+'), k('AudioVolumeMute', 'Mute')],
    [m('ctrl', 'Ctrl'), m('win', '⊞'), m('alt', 'Alt'), m('shift', 'Shift'), k('Escape', 'Esc'), k('Tab', 'Tab')],
  ],
};

// ASCII → [code, needsShift] (US layout), for typing text from the native soft keyboard / paste.
const SHIFTED: Record<string, string> = { '!': 'Digit1', '@': 'Digit2', '#': 'Digit3', '$': 'Digit4', '%': 'Digit5', '^': 'Digit6', '&': 'Digit7', '*': 'Digit8', '(': 'Digit9', ')': 'Digit0', _: 'Minus', '+': 'Equal', '{': 'BracketLeft', '}': 'BracketRight', '|': 'Backslash', ':': 'Semicolon', '"': 'Quote', '~': 'Backquote', '<': 'Comma', '>': 'Period', '?': 'Slash' };
const PLAIN: Record<string, string> = { '-': 'Minus', '=': 'Equal', '[': 'BracketLeft', ']': 'BracketRight', '\\': 'Backslash', ';': 'Semicolon', "'": 'Quote', '`': 'Backquote', ',': 'Comma', '.': 'Period', '/': 'Slash', ' ': 'Space', '\n': 'Enter', '\t': 'Tab' };

export function charToKey(ch: string): [code: string, shift: boolean] | null {
  if (/^[a-z]$/.test(ch)) return ['Key' + ch.toUpperCase(), false];
  if (/^[A-Z]$/.test(ch)) return ['Key' + ch, true];
  if (/^[0-9]$/.test(ch)) return ['Digit' + ch, false];
  if (ch in PLAIN) return [PLAIN[ch], false];
  if (ch in SHIFTED) return [SHIFTED[ch], true];
  // Smart punctuation from iOS/Android keyboards
  const smart: Record<string, string> = { '‘': "'", '’': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '.', '\u00a0': ' ' };
  if (ch in smart) return charToKey(smart[ch]);
  return null;
}

export class KeyboardModel {
  private mods: Record<Mod, ModState> = { ctrl: 'off', alt: 'off', shift: 'off', win: 'off' };
  private lastTap: Partial<Record<Mod, number>> = {};
  private listeners = new Set<(s: Readonly<Record<Mod, ModState>>) => void>();
  /** Double-tap window that turns a latched modifier into a locked one. */
  lockMs = 350;
  /** Number of characters that could not be typed (non-ASCII) in the last typeText call. */
  skipped = 0;

  constructor(private sink: InputSink, private now: () => number = () => Date.now()) {}

  get state(): Readonly<Record<Mod, ModState>> { return this.mods; }
  onChange(fn: (s: Readonly<Record<Mod, ModState>>) => void): () => void { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  private changed(): void { for (const fn of this.listeners) fn(this.mods); }

  /**
   * Tap a sticky modifier. The modifier key goes down on the host immediately so that it also
   * applies to touch clicks (Ctrl+click, Shift+click).
   */
  tapModifier(mod: Mod): void {
    const t = this.now();
    const s = this.mods[mod];
    if (s === 'off') {
      this.sink.push(keyEv(MOD_CODE[mod], true));
      this.mods[mod] = 'latched';
    } else if (s === 'latched') {
      if (t - (this.lastTap[mod] ?? -1e9) <= this.lockMs) this.mods[mod] = 'locked';
      else { this.sink.push(keyEv(MOD_CODE[mod], false)); this.mods[mod] = 'off'; }
    } else {
      this.sink.push(keyEv(MOD_CODE[mod], false));
      this.mods[mod] = 'off';
    }
    this.lastTap[mod] = t;
    this.changed();
  }

  /** Release latched (one-shot) modifiers; locked ones stay. */
  private consumeLatched(): void {
    let any = false;
    for (const mod of [...MODS].reverse()) {
      if (this.mods[mod] === 'latched') { this.sink.push(keyEv(MOD_CODE[mod], false)); this.mods[mod] = 'off'; any = true; }
    }
    if (any) this.changed();
  }

  /** Call after a pointer click so a latched Ctrl/Shift applies to exactly one click. */
  afterPointerAction(): void { this.consumeLatched(); }

  /** Tap one key (down+up) with whatever modifiers are active. Modifier keys route to tapModifier. */
  press(code: string): void {
    const mod = (Object.keys(MOD_CODE) as Mod[]).find((x) => MOD_CODE[x] === code);
    if (mod) { this.tapModifier(mod); return; }
    this.sink.push(keyEv(code, true));
    this.sink.push(keyEv(code, false));
    this.consumeLatched();
  }

  /** Hold a key (for auto-repeat on the host: Backspace, arrows). Pair with keyUp. */
  keyDown(code: string): void { this.sink.push(keyEv(code, true)); }
  keyUp(code: string): void { this.sink.push(keyEv(code, false)); this.consumeLatched(); }

  /** Press a chord: keys down in order, up in reverse. Sticky modifiers already down are not repeated. */
  combo(keys: string[]): void {
    const held = new Set((Object.keys(this.mods) as Mod[]).filter((x) => this.mods[x] !== 'off').map((x) => MOD_CODE[x]));
    const ks = keys.filter((c) => !held.has(c));
    ks.forEach((c) => this.sink.push(keyEv(c, true)));
    [...ks].reverse().forEach((c) => this.sink.push(keyEv(c, false)));
    this.consumeLatched();
  }

  shortcut(id: string): void {
    const s = SHORTCUTS.find((x) => x.id === id);
    if (!s) throw new Error(`unknown shortcut ${id}`);
    this.combo(s.keys);
  }

  /** Type text as US-layout key strokes. Characters with no key are skipped and counted. */
  typeText(text: string): number {
    this.skipped = 0;
    let typed = 0;
    const shiftHeld = this.mods.shift !== 'off';
    for (const ch of text) {
      const kc = charToKey(ch);
      if (!kc || !scanOf(kc[0])) { this.skipped++; continue; }
      const [code, shift] = kc;
      const needShift = shift && !shiftHeld;
      if (needShift) this.sink.push(keyEv('ShiftLeft', true));
      this.sink.push(keyEv(code, true));
      this.sink.push(keyEv(code, false));
      if (needShift) this.sink.push(keyEv('ShiftLeft', false));
      typed++;
    }
    if (typed) this.consumeLatched();
    return typed;
  }

  /** Release every modifier we hold (on disconnect / blur). */
  releaseAll(): void {
    let any = false;
    for (const mod of MODS) {
      if (this.mods[mod] !== 'off') { this.sink.push(keyEv(MOD_CODE[mod], false)); this.mods[mod] = 'off'; any = true; }
    }
    if (any) this.changed();
  }
}
