/**
 * Plays audio arriving on the `audio` DataChannel (48 kHz, 1 packet/message) using WebCodecs
 * AudioDecoder + a tiny jitter buffer on an AudioContext.
 *
 * ls-host wraps every 10 ms frame in the `ls_proto::audio` header (crates/proto/src/audio.rs):
 *   "LA" | ver=1 | seq u16 | ts u32 | flags (bit0 Opus, bit2 DTX, bit3 redundancy) | len u16 | payload | [len u16 | prev payload]
 * The payload alone is the Opus packet (or s16le PCM when the host has no Opus). Feeding the whole frame to the
 * decoder produced garbage samples (peaks ≫ 1.0, i.e. loud clipping). Bare Opus packets (in-page loopback) still work.
 *
 * If the host instead sends audio as a normal RTP track, the browser plays it through
 * the <video> element and this class stays idle.
 */
import { parseAudioFrame } from './audioframe';
import { AudioUnlocker, type UnlockState } from './lstouch/unlock';

type AudioDecoderLike = {
  configure(c: { codec: string; sampleRate: number; numberOfChannels: number }): void;
  decode(chunk: unknown): void;
  close(): void;
  state: string;
};

const TARGET_LATENCY_S = 0.04; // 40 ms playout buffer
const MAX_LATENCY_S = 0.15; // beyond this we skip ahead instead of drifting

export class DataChannelAudio {
  private ctx: AudioContext | null = null;
  private dec: AudioDecoderLike | null = null;
  private playhead = 0;
  private ts = 0;
  private gain: GainNode | null = null;
  /** Owns the AudioContext: primes it inside a gesture (iOS), sets audioSession 'playback' (silent switch),
   *  and re-arms on suspend / interruption / visibility so sound comes back without a reload. */
  private unlocker: AudioUnlocker | null = null;
  readonly supported = typeof (globalThis as { AudioDecoder?: unknown }).AudioDecoder === 'function';

  constructor(private channels = 2) {}

  /** Must be called from a user gesture on iOS/Safari. */
  async resume(): Promise<void> {
    if (!this.supported) return;
    if (!this.ctx) this.init();
    await this.unlocker?.enable();
    if (this.unlocker?.ctx && this.unlocker.ctx !== (this.ctx as unknown)) this.adopt();
  }

  /** Sound on/off (floating toolbar). Off keeps the context for a fast re-enable. */
  async setEnabled(on: boolean): Promise<void> {
    if (!this.supported) return;
    if (on) return this.resume();
    await this.unlocker?.disable();
  }

  get state(): UnlockState {
    return this.unlocker?.state ?? 'locked';
  }

  onUnlockChange(fn: (s: UnlockState, needsGesture: boolean) => void): () => void {
    if (!this.unlocker && this.supported) this.init();
    return this.unlocker?.onChange(fn) ?? (() => undefined);
  }

  private init(): void {
    const g = globalThis as unknown as {
      AudioDecoder: new (i: { output: (d: AudioDataLike) => void; error: (e: Error) => void }) => AudioDecoderLike;
    };
    this.unlocker = AudioUnlocker.browser();
    void this.unlocker.enable(); // outside a gesture this just arms: the next tap/key resumes
    if (!this.unlocker.ctx) return;
    this.adopt();
    this.dec = new g.AudioDecoder({ output: (d) => this.play(d), error: () => this.reset() });
    this.dec.configure({ codec: 'opus', sampleRate: 48000, numberOfChannels: this.channels });
  }

  private adopt(): void {
    this.ctx = this.unlocker!.ctx as unknown as AudioContext;
    this.gain = this.ctx.createGain();
    this.gain.connect(this.ctx.destination);
    this.playhead = 0;
  }

  setVolume(v: number): void {
    if (this.gain) this.gain.gain.value = v;
  }

  private lastSeq = -1;

  push(packet: ArrayBuffer): void {
    if (!this.supported) return;
    if (!this.ctx) this.init();
    const f = parseAudioFrame(packet);
    if (!f) return;
    if (f.seq !== undefined) {
      const gap = this.lastSeq < 0 ? 1 : (f.seq - this.lastSeq + 0x10000) & 0xffff;
      if (gap === 0 || gap > 0x8000) return; // duplicate / late
      // exactly one frame lost and this one carries it as redundancy: play it first
      if (gap === 2 && f.redundancy) this.decodeFrame(f.redundancy, f.opus);
      this.lastSeq = f.seq;
    }
    if (f.dtx) return;
    this.decodeFrame(f.payload, f.opus);
  }

  private decodeFrame(payload: Uint8Array, opus: boolean): void {
    if (!opus) return this.playPcm(payload);
    if (!this.dec || this.dec.state !== 'configured') return;
    const EAC = (globalThis as unknown as { EncodedAudioChunk: new (i: { type: string; timestamp: number; data: Uint8Array }) => unknown })
      .EncodedAudioChunk;
    this.dec.decode(new EAC({ type: 'key', timestamp: this.ts, data: payload }));
    this.ts += 10000; // µs, nominal 10 ms frame (only used as an id)
  }

  /** PCM fallback: interleaved s16le stereo at 48 kHz. */
  private playPcm(p: Uint8Array): void {
    const ctx = this.ctx;
    if (!ctx || p.byteLength < 4) return;
    const ch = this.channels;
    const frames = Math.floor(p.byteLength / (2 * ch));
    const dv = new DataView(p.buffer, p.byteOffset, p.byteLength);
    const buf = ctx.createBuffer(ch, frames, 48000);
    for (let c = 0; c < ch; c++) {
      const plane = new Float32Array(frames);
      for (let i = 0; i < frames; i++) plane[i] = dv.getInt16((i * ch + c) * 2, true) / 32768;
      buf.copyToChannel(plane, c);
    }
    this.schedule(buf);
  }

  private play(d: AudioDataLike): void {
    const ctx = this.ctx!;
    const frames = d.numberOfFrames;
    const buf = ctx.createBuffer(d.numberOfChannels, frames, d.sampleRate);
    for (let c = 0; c < d.numberOfChannels; c++) {
      const plane = new Float32Array(frames);
      d.copyTo(plane, { planeIndex: c, format: 'f32-planar' });
      buf.copyToChannel(plane, c);
    }
    d.close();
    this.schedule(buf);
  }

  private schedule(buf: AudioBuffer): void {
    const ctx = this.ctx!;
    const now = ctx.currentTime;
    if (this.playhead < now || this.playhead - now > MAX_LATENCY_S) this.playhead = now + TARGET_LATENCY_S;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.connect(this.gain!);
    src.start(this.playhead);
    this.playhead += buf.duration;
  }

  private reset(): void {
    try {
      this.dec?.close();
    } catch {
      /* noop */
    }
    this.dec = null;
    if (this.ctx) {
      const g = globalThis as unknown as {
        AudioDecoder: new (i: { output: (d: AudioDataLike) => void; error: (e: Error) => void }) => AudioDecoderLike;
      };
      this.dec = new g.AudioDecoder({ output: (d) => this.play(d), error: () => undefined });
      this.dec.configure({ codec: 'opus', sampleRate: 48000, numberOfChannels: this.channels });
    }
  }

  close(): void {
    try {
      this.dec?.close();
    } catch {
      /* noop */
    }
    void this.unlocker?.close();
    this.unlocker = null;
    this.ctx = null;
    this.dec = null;
  }
}

interface AudioDataLike {
  numberOfFrames: number;
  numberOfChannels: number;
  sampleRate: number;
  copyTo(dest: Float32Array, opts: { planeIndex: number; format: string }): void;
  close(): void;
}
