import { codeToScan, type ScanCode } from './scancodes';
import {
  domButtonToWire,
  encodeKey,
  encodeMouseAbs,
  encodeMouseButton,
  encodeMouseRel,
  encodeReleaseAll,
  encodeWheel,
  type MouseButtonId,
} from './protocol';

export interface InputSink {
  sendInput(bytes: Uint8Array, droppable?: boolean): boolean;
}

export type MouseMode = 'relative' | 'absolute';
export type Hotkey = 'toggleMouseMode' | 'toggleHud' | 'toggleFullscreen' | 'release' | 'disconnect';

export interface InputOptions {
  mode: () => MouseMode;
  sensitivity: () => number;
  macCmdAsCtrl: () => boolean;
  onHotkey: (h: Hotkey) => void;
  onPointerLockChange: (locked: boolean) => void;
  onLocalEcho?: (e: { kind: 'key'; code: string; sc: ScanCode; down: boolean } | { kind: 'mouse' }) => void;
}

const IS_MAC = typeof navigator !== 'undefined' && /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent);

/** Ctrl+Alt+Shift + <key> are local shortcuts and are never forwarded. */
const HOTKEYS: Record<string, Hotkey> = {
  KeyM: 'toggleMouseMode',
  KeyH: 'toggleHud',
  KeyF: 'toggleFullscreen',
  KeyZ: 'release',
  KeyQ: 'disconnect',
};

const MODIFIER_CODES = new Set(['ShiftLeft', 'ShiftRight', 'ControlLeft', 'ControlRight', 'AltLeft', 'AltRight', 'MetaLeft', 'MetaRight', 'OSLeft', 'OSRight']);

/** Content rectangle of a `object-fit: contain` video inside its element box. */
export function videoContentRect(video: HTMLVideoElement): DOMRect {
  const r = video.getBoundingClientRect();
  const vw = video.videoWidth || r.width;
  const vh = video.videoHeight || r.height;
  const scale = Math.min(r.width / vw, r.height / vh);
  const w = vw * scale;
  const h = vh * scale;
  return new DOMRect(r.left + (r.width - w) / 2, r.top + (r.height - h) / 2, w, h);
}

export class InputController {
  private surface: HTMLElement;
  private video: HTMLVideoElement;
  private sink: InputSink;
  private opts: InputOptions;
  private pressed = new Map<string, ScanCode>();
  private buttons = new Set<MouseButtonId>();
  private accX = 0;
  private accY = 0;
  private wheelAccX = 0;
  private wheelAccY = 0;
  private attached = false;
  private disposers: Array<() => void> = [];

  constructor(surface: HTMLElement, video: HTMLVideoElement, sink: InputSink, opts: InputOptions) {
    this.surface = surface;
    this.video = video;
    this.sink = sink;
    this.opts = opts;
  }

  get pointerLocked(): boolean {
    return document.pointerLockElement === this.surface;
  }

  attach(): void {
    if (this.attached) return;
    this.attached = true;
    const on = <K extends keyof WindowEventMap>(t: Window, ev: K, fn: (e: WindowEventMap[K]) => void, o?: AddEventListenerOptions) => {
      t.addEventListener(ev, fn as EventListener, o);
      this.disposers.push(() => t.removeEventListener(ev, fn as EventListener, o));
    };
    const onEl = <K extends keyof HTMLElementEventMap>(ev: K, fn: (e: HTMLElementEventMap[K]) => void, o?: AddEventListenerOptions) => {
      this.surface.addEventListener(ev, fn as EventListener, o);
      this.disposers.push(() => this.surface.removeEventListener(ev, fn as EventListener, o));
    };
    const onDoc = <K extends keyof DocumentEventMap>(ev: K, fn: (e: DocumentEventMap[K]) => void) => {
      document.addEventListener(ev, fn as EventListener);
      this.disposers.push(() => document.removeEventListener(ev, fn as EventListener));
    };

    on(window, 'keydown', (e) => this.onKey(e, true), { capture: true });
    on(window, 'keyup', (e) => this.onKey(e, false), { capture: true });
    on(window, 'blur', () => this.releaseAll());
    onDoc('visibilitychange', () => {
      if (document.hidden) this.releaseAll();
    });

    // pointerrawupdate = un-throttled, un-coalesced moves (Chrome, secure contexts) -> lowest latency.
    const moveEvent = 'onpointerrawupdate' in this.surface ? 'pointerrawupdate' : 'pointermove';
    onEl(moveEvent as 'pointermove', (e) => this.onPointerMove(e));
    onEl('pointerdown', (e) => this.onPointerButton(e, true));
    onEl('pointerup', (e) => this.onPointerButton(e, false));
    onEl('wheel', (e) => this.onWheel(e), { passive: false });
    onEl('contextmenu', (e) => e.preventDefault());
    onEl('auxclick', (e) => e.preventDefault());
    onDoc('pointerlockchange', () => {
      const locked = this.pointerLocked;
      if (!locked) this.releaseButtons();
      this.opts.onPointerLockChange(locked);
    });
  }

  detach(): void {
    this.releaseAll();
    this.disposers.forEach((d) => d());
    this.disposers = [];
    this.attached = false;
    if (this.pointerLocked) document.exitPointerLock();
  }

  async requestPointerLock(): Promise<void> {
    if (this.pointerLocked) return;
    const el = this.surface as HTMLElement & {
      requestPointerLock(o?: { unadjustedMovement?: boolean }): Promise<void> | void;
    };
    try {
      // unadjustedMovement: raw sensor counts, no OS acceleration — what FPS players want.
      await el.requestPointerLock({ unadjustedMovement: true });
    } catch {
      try {
        await el.requestPointerLock();
      } catch {
        /* user gesture required or unsupported (iOS) */
      }
    }
  }

  // ── keyboard ─────────────────────────────────────────────────────────────
  private isTypingTarget(e: Event): boolean {
    const t = e.target as HTMLElement | null;
    if (!t) return false;
    if (t.dataset?.lsCapture === 'true') return false; // virtual keyboard proxy handles its own
    return t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable;
  }

  private onKey(e: KeyboardEvent, down: boolean): void {
    if (this.isTypingTarget(e)) return;
    if (e.isComposing) return;

    if (down && e.ctrlKey && e.altKey && e.shiftKey && HOTKEYS[e.code]) {
      e.preventDefault();
      e.stopPropagation();
      this.releaseAll();
      this.opts.onHotkey(HOTKEYS[e.code]);
      return;
    }

    let code = e.code;
    if (this.opts.macCmdAsCtrl()) {
      if (code === 'MetaLeft' || code === 'OSLeft') code = 'ControlLeft';
      else if (code === 'MetaRight' || code === 'OSRight') code = 'ControlRight';
    }
    const sc = codeToScan(code);
    if (!sc) return;

    // Swallow everything we forward so the browser doesn't act on it (F5, Ctrl+W where allowed, Tab focus, …).
    e.preventDefault();
    e.stopPropagation();

    // macOS reports CapsLock as a toggle (down on enable, up on disable). Translate into a full tap.
    if (IS_MAC && code === 'CapsLock') {
      this.sink.sendInput(encodeKey(sc.scan, true, sc.extended));
      this.sink.sendInput(encodeKey(sc.scan, false, sc.extended));
      return;
    }

    if (down) {
      this.pressed.set(code, sc);
    } else {
      if (!this.pressed.has(code) && !MODIFIER_CODES.has(code)) return; // stray up
      this.pressed.delete(code);
      // macOS swallows keyup of other keys while ⌘ is held: release them when ⌘ goes up.
      if (IS_MAC && (e.code === 'MetaLeft' || e.code === 'MetaRight')) {
        for (const [c, s] of this.pressed) {
          if (MODIFIER_CODES.has(c)) continue;
          this.sink.sendInput(encodeKey(s.scan, false, s.extended));
          this.pressed.delete(c);
        }
      }
    }
    this.sink.sendInput(encodeKey(sc.scan, down, sc.extended));
    this.opts.onLocalEcho?.({ kind: 'key', code, sc, down });
  }

  /** Used by the virtual keyboard / toolbar. */
  sendKeyCode(code: string, down: boolean): void {
    const sc = codeToScan(code);
    if (!sc) return;
    if (down) this.pressed.set(code, sc);
    else this.pressed.delete(code);
    this.sink.sendInput(encodeKey(sc.scan, down, sc.extended));
  }

  tapCombo(codes: string[]): void {
    codes.forEach((c) => this.sendKeyCode(c, true));
    [...codes].reverse().forEach((c) => this.sendKeyCode(c, false));
  }

  // ── mouse ────────────────────────────────────────────────────────────────
  private onPointerMove(e: PointerEvent): void {
    if (e.pointerType !== 'mouse' && e.pointerType !== 'pen') return;
    if (this.opts.mode() === 'relative') {
      if (!this.pointerLocked) return;
      const s = this.opts.sensitivity();
      this.accX += e.movementX * s;
      this.accY += e.movementY * s;
      const dx = Math.trunc(this.accX);
      const dy = Math.trunc(this.accY);
      if (dx === 0 && dy === 0) return;
      this.accX -= dx;
      this.accY -= dy;
      if (!this.sink.sendInput(encodeMouseRel(dx, dy), true)) {
        // dropped under backpressure: keep the motion for the next event instead of losing it
        this.accX += dx;
        this.accY += dy;
      }
    } else {
      this.sendAbsFromClient(e.clientX, e.clientY);
    }
  }

  sendAbsFromClient(clientX: number, clientY: number): void {
    const r = videoContentRect(this.video);
    if (r.width <= 0 || r.height <= 0) return;
    const nx = (clientX - r.left) / r.width;
    const ny = (clientY - r.top) / r.height;
    if (nx < -0.02 || ny < -0.02 || nx > 1.02 || ny > 1.02) return;
    this.sink.sendInput(encodeMouseAbs(Math.min(1, Math.max(0, nx)), Math.min(1, Math.max(0, ny))), true);
  }

  private onPointerButton(e: PointerEvent, down: boolean): void {
    if (e.pointerType !== 'mouse' && e.pointerType !== 'pen') return;
    e.preventDefault();
    if (this.opts.mode() === 'relative' && !this.pointerLocked) {
      if (down) void this.requestPointerLock(); // first click only captures
      return;
    }
    if (this.opts.mode() === 'absolute') {
      this.sendAbsFromClient(e.clientX, e.clientY);
      if (down) capture(this.surface, e.pointerId);
    }
    const b = domButtonToWire(e.button);
    if (b === undefined) return;
    this.sendButton(b, down);
  }

  sendButton(b: MouseButtonId, down: boolean): void {
    if (down) this.buttons.add(b);
    else if (!this.buttons.delete(b)) return;
    this.sink.sendInput(encodeMouseButton(b, down));
    this.opts.onLocalEcho?.({ kind: 'mouse' });
  }

  sendRelative(dx: number, dy: number): void {
    this.accX += dx;
    this.accY += dy;
    const ix = Math.trunc(this.accX);
    const iy = Math.trunc(this.accY);
    if (!ix && !iy) return;
    this.accX -= ix;
    this.accY -= iy;
    this.sink.sendInput(encodeMouseRel(ix, iy), true);
  }

  private onWheel(e: WheelEvent): void {
    e.preventDefault();
    // Normalise to WHEEL_DELTA (120 per notch). DOM: +deltaY = scroll down; Windows: +delta = scroll up.
    const unit = e.deltaMode === WheelEvent.DOM_DELTA_LINE ? 40 : e.deltaMode === WheelEvent.DOM_DELTA_PAGE ? 120 * 3 : 1.2;
    this.sendWheel(e.deltaX * unit, -e.deltaY * unit);
  }

  /** dx/dy already in WHEEL_DELTA units (fractions accumulate for smooth trackpads). */
  sendWheel(dx: number, dy: number): void {
    this.wheelAccX += dx;
    this.wheelAccY += dy;
    const ix = Math.trunc(this.wheelAccX);
    const iy = Math.trunc(this.wheelAccY);
    if (!ix && !iy) return;
    this.wheelAccX -= ix;
    this.wheelAccY -= iy;
    this.sink.sendInput(encodeWheel(ix, iy));
  }

  // ── safety ───────────────────────────────────────────────────────────────
  private releaseButtons(): void {
    for (const b of this.buttons) this.sink.sendInput(encodeMouseButton(b, false));
    this.buttons.clear();
  }

  /** Never leave a key or button stuck on the host. */
  releaseAll(): void {
    for (const sc of this.pressed.values()) this.sink.sendInput(encodeKey(sc.scan, false, sc.extended));
    this.pressed.clear();
    this.releaseButtons();
    this.sink.sendInput(encodeReleaseAll());
  }
}

/** setPointerCapture throws for pointers the UA no longer considers active; never let that break input. */
function capture(el: HTMLElement, id: number): void {
  try {
    el.setPointerCapture?.(id);
  } catch {
    /* ignore */
  }
}
