// Vendored from leestream-touch (2026-11-26 package, src/protocol.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// LeeStream input wire format (mirrors crates/web/assets/lsinput.js and ls_proto::input).
// Batch: first_seq u32 | count u8 | count × (kind u8 | flags u8 | a u16 | b u16 | c u16), little-endian.

export type InputEvent = readonly [kind: number, flags: number, a: number, b: number, c: number];

/** Protocol button numbers (0 left, 1 right, 2 middle, 3 X1, 4 X2). */
export const Button = { Left: 0, Right: 1, Middle: 2, X1: 3, X2: 4 } as const;
export type ButtonId = (typeof Button)[keyof typeof Button];

/** One wheel "notch" in protocol units (WHEEL_DELTA). */
export const WHEEL_NOTCH = 120;
/** Absolute coordinates are normalised to 0..ABS_MAX over the captured display. */
export const ABS_MAX = 65535;

const clamp16 = (v: number) => Math.max(-32768, Math.min(32767, Math.round(v)));

export const ev = {
  abs: (x: number, y: number): InputEvent => [1, 0, Math.max(0, Math.min(ABS_MAX, Math.round(x))), Math.max(0, Math.min(ABS_MAX, Math.round(y))), 0],
  rel: (dx: number, dy: number): InputEvent => [2, 0, clamp16(dx) & 0xffff, clamp16(dy) & 0xffff, 0],
  btn: (b: number, down: boolean): InputEvent => [3, down ? 1 : 0, b, 0, 0],
  /** dy > 0 scrolls up (content moves down), matching Windows WHEEL_DELTA sign. */
  wheel: (dy: number, dx: number): InputEvent => [4, 0, clamp16(dy) & 0xffff, clamp16(dx) & 0xffff, 0],
  key: (scan: number, down: boolean, ext: boolean): InputEvent => [5, (down ? 1 : 0) | (ext ? 2 : 0), scan, 0, 0],
  releaseAll: (): InputEvent => [6, 0, 0, 0, 0],
};

/** Anything with push(event) — the existing InputSender from lsinput.js satisfies this. */
export interface InputSink {
  push(e: InputEvent | number[]): void;
}

/** Standalone sender with the same batching/sequence semantics as lsinput.js InputSender. */
export class BatchSender implements InputSink {
  seq = 0;
  private q: (InputEvent | number[])[] = [];
  private scheduled = false;
  constructor(private send: (b: Uint8Array) => void) {}
  push(e: InputEvent | number[]): void {
    this.q.push(e);
    if (!this.scheduled) {
      this.scheduled = true;
      queueMicrotask(() => this.flush());
    }
  }
  flush(): void {
    this.scheduled = false;
    while (this.q.length) {
      const evs = this.q.splice(0, 64);
      this.send(encodeBatch(this.seq + 1, evs));
      this.seq = (this.seq + evs.length) >>> 0;
    }
  }
}

export function encodeBatch(firstSeq: number, evs: readonly (InputEvent | number[])[]): Uint8Array {
  const b = new Uint8Array(5 + 8 * evs.length);
  const dv = new DataView(b.buffer);
  dv.setUint32(0, firstSeq >>> 0, true);
  b[4] = evs.length;
  evs.forEach((e, i) => {
    const o = 5 + 8 * i;
    b[o] = e[0];
    b[o + 1] = e[1];
    dv.setUint16(o + 2, e[2] & 0xffff, true);
    dv.setUint16(o + 4, e[3] & 0xffff, true);
    dv.setUint16(o + 6, e[4] & 0xffff, true);
  });
  return b;
}

export function decodeBatch(b: Uint8Array): { firstSeq: number; events: InputEvent[] } {
  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
  const n = b[4];
  const events: InputEvent[] = [];
  for (let i = 0; i < n; i++) {
    const o = 5 + 8 * i;
    events.push([b[o], b[o + 1], dv.getUint16(o + 2, true), dv.getUint16(o + 4, true), dv.getUint16(o + 6, true)]);
  }
  return { firstSeq: dv.getUint32(0, true), events };
}

// KeyboardEvent.code → [scan code (set 1), E0-extended]. Same table as lsinput.js.
const S: Record<string, number> = {
  Escape: 0x01, Digit1: 0x02, Digit2: 0x03, Digit3: 0x04, Digit4: 0x05, Digit5: 0x06, Digit6: 0x07, Digit7: 0x08, Digit8: 0x09,
  Digit9: 0x0a, Digit0: 0x0b, Minus: 0x0c, Equal: 0x0d, Backspace: 0x0e, Tab: 0x0f,
  KeyQ: 0x10, KeyW: 0x11, KeyE: 0x12, KeyR: 0x13, KeyT: 0x14, KeyY: 0x15, KeyU: 0x16, KeyI: 0x17, KeyO: 0x18, KeyP: 0x19,
  BracketLeft: 0x1a, BracketRight: 0x1b, Enter: 0x1c, ControlLeft: 0x1d,
  KeyA: 0x1e, KeyS: 0x1f, KeyD: 0x20, KeyF: 0x21, KeyG: 0x22, KeyH: 0x23, KeyJ: 0x24, KeyK: 0x25, KeyL: 0x26,
  Semicolon: 0x27, Quote: 0x28, Backquote: 0x29, ShiftLeft: 0x2a, Backslash: 0x2b,
  KeyZ: 0x2c, KeyX: 0x2d, KeyC: 0x2e, KeyV: 0x2f, KeyB: 0x30, KeyN: 0x31, KeyM: 0x32,
  Comma: 0x33, Period: 0x34, Slash: 0x35, ShiftRight: 0x36, NumpadMultiply: 0x37, AltLeft: 0x38, Space: 0x39, CapsLock: 0x3a,
  F1: 0x3b, F2: 0x3c, F3: 0x3d, F4: 0x3e, F5: 0x3f, F6: 0x40, F7: 0x41, F8: 0x42, F9: 0x43, F10: 0x44,
  NumLock: 0x45, ScrollLock: 0x46, Numpad7: 0x47, Numpad8: 0x48, Numpad9: 0x49, NumpadSubtract: 0x4a,
  Numpad4: 0x4b, Numpad5: 0x4c, Numpad6: 0x4d, NumpadAdd: 0x4e, Numpad1: 0x4f, Numpad2: 0x50, Numpad3: 0x51,
  Numpad0: 0x52, NumpadDecimal: 0x53, IntlBackslash: 0x56, F11: 0x57, F12: 0x58,
};
const E: Record<string, number> = {
  NumpadEnter: 0x1c, ControlRight: 0x1d, NumpadDivide: 0x35, PrintScreen: 0x37, AltRight: 0x38,
  Home: 0x47, ArrowUp: 0x48, PageUp: 0x49, ArrowLeft: 0x4b, ArrowRight: 0x4d, End: 0x4f, ArrowDown: 0x50,
  PageDown: 0x51, Insert: 0x52, Delete: 0x53, MetaLeft: 0x5b, MetaRight: 0x5c, ContextMenu: 0x5d,
  AudioVolumeMute: 0x20, AudioVolumeDown: 0x2e, AudioVolumeUp: 0x30, MediaPlayPause: 0x22,
};

export function scanOf(code: string): [scan: number, ext: boolean] | null {
  if (code in S) return [S[code], false];
  if (code in E) return [E[code], true];
  return null;
}

/** Key event for a KeyboardEvent.code; throws on an unknown code (programming error). */
export function keyEv(code: string, down: boolean): InputEvent {
  const m = scanOf(code);
  if (!m) throw new Error(`unknown key code ${code}`);
  return ev.key(m[0], down, m[1]);
}
