let injected = false;
export function injectStyles(doc: Document = document): void {
  if (injected || doc.getElementById('lst-styles')) return;
  const s = doc.createElement('style');
  s.id = 'lst-styles';
  s.textContent = CSS;
  doc.head.appendChild(s);
  injected = true;
}
