import type { HudStats } from '../lib/stats';

const tone = (v: number | null, good: number, warn: number, higherIsBetter = false) => {
  if (v === null || Number.isNaN(v)) return 'text-slate-400';
  const ok = higherIsBetter ? v >= good : v <= good;
  const meh = higherIsBetter ? v >= warn : v <= warn;
  return ok ? 'text-emerald-300' : meh ? 'text-amber-300' : 'text-red-400';
};
const f = (v: number | null, d = 1, unit = '') => (v === null || Number.isNaN(v) ? '—' : `${v.toFixed(d)}${unit}`);

export function Hud({ s, presentedFps, expanded, onToggle }: { s: HudStats; presentedFps: number | null; expanded: boolean; onToggle: () => void }) {
  return (
    <button
      onClick={onToggle}
      className="glass pointer-events-auto rounded-xl px-3 py-2 text-left font-mono text-[11px] leading-[1.35] text-slate-200 select-none"
      title="Click to expand/collapse (Ctrl+Alt+Shift+H hides)"
    >
      <div className="flex gap-3">
        <Cell k="FPS" v={f(s.fps, 0)} c={tone(s.fps, 55, 28, true)} />
        <Cell k="RTT" v={f(s.rttMs, 0, 'ms')} c={tone(s.rttMs, 20, 60)} />
        <Cell k="JIT" v={f(s.jitterMs, 1, 'ms')} c={tone(s.jitterMs, 5, 15)} />
        <Cell k="BR" v={f(s.bitrateMbps, 1, 'M')} c="text-cyan-300" />
        <Cell k="DEC" v={f(s.decodeMs, 1, 'ms')} c={tone(s.decodeMs, 6, 14)} />
        <Cell k="LOSS" v={f(s.lossPct, 1, '%')} c={tone(s.lossPct, 0.5, 2)} />
      </div>
      {expanded && (
        <div className="mt-1.5 grid grid-cols-2 gap-x-4 border-t border-white/10 pt-1.5 text-slate-400">
          <span>codec <b className="text-slate-200">{s.codec}</b></span>
          <span>res <b className="text-slate-200">{s.width ? `${s.width}×${s.height}` : '—'}</b></span>
          <span>shown fps <b className="text-slate-200">{f(presentedFps, 0)}</b></span>
          <span>jit buf <b className="text-slate-200">{f(s.jitterBufferMs, 1, 'ms')}</b></span>
          <span>input rtt <b className="text-slate-200">{f(s.inputRttMs, 1, 'ms')}</b></span>
          <span>dropped <b className="text-slate-200">{s.framesDropped}</b></span>
          <span className="col-span-2">path <b className="text-slate-200">{s.candidate}</b></span>
        </div>
      )}
    </button>
  );
}

function Cell({ k, v, c }: { k: string; v: string; c: string }) {
  return (
    <span className="flex flex-col items-start">
      <span className="text-[9px] tracking-wider text-slate-500">{k}</span>
      <span className={`tabular-nums ${c}`}>{v}</span>
    </span>
  );
}
