// Vendored from leestream-touch (2026-11-26 package, src/toolbar.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// Floating ergonomic toolbar: one thumb-sized handle that can be dragged anywhere and snaps to
// the nearest screen edge; tapping it fans out the controls. Position persists per device.

export interface ToolItem {
  id: string;
  label: string;
  icon: string;               // short glyph/emoji shown in the round button
  onClick: () => void;
  active?: () => boolean;     // highlight state (re-evaluated on refresh())
}

export interface ToolbarOptions {
  storageKey?: string;
  idleFadeMs?: number;
}

export class FloatingToolbar {
  readonly el: HTMLDivElement;
  readonly handle: HTMLButtonElement;
  private panel: HTMLDivElement;
  private btns = new Map<string, HTMLButtonElement>();
  private pos = { side: 'right' as 'left' | 'right', y: 0.72 };   // y as fraction of height
  private fadeT: ReturnType<typeof setTimeout> | null = null;
  private L: (() => void)[] = [];

  constructor(private parent: HTMLElement, private items: ToolItem[], private o: ToolbarOptions = {}) {
    const el = (this.el = document.createElement('div'));
    el.className = 'lst-tb';
    const h = (this.handle = document.createElement('button'));
    h.type = 'button';
    h.className = 'lst-tb-handle';
    h.setAttribute('aria-label', 'LeeStream controls');
    h.setAttribute('aria-expanded', 'false');
    h.innerHTML = '<span>LS</span>';
    const p = (this.panel = document.createElement('div'));
    p.className = 'lst-tb-panel';
    p.setAttribute('role', 'toolbar');
    p.hidden = true;
    for (const it of items) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'lst-tb-btn';
      b.dataset.tool = it.id;
      b.title = it.label;
      b.setAttribute('aria-label', it.label);
      b.innerHTML = `<span class="lst-ic">${it.icon}</span><span class="lst-lb">${it.label}</span>`;
      b.addEventListener('click', (e) => { e.stopPropagation(); it.onClick(); this.refresh(); this.poke(); });
      this.btns.set(it.id, b);
      p.appendChild(b);
    }
    el.append(p, h);
    parent.appendChild(el);

    try {
      const s = JSON.parse(localStorage.getItem(o.storageKey ?? 'lst.toolbar') || 'null');
      if (s && (s.side === 'left' || s.side === 'right') && typeof s.y === 'number') this.pos = s;
    } catch { /* private mode */ }

    this.dragging(h);
    const onResize = () => this.place();
    window.addEventListener('resize', onResize);
    this.L.push(() => window.removeEventListener('resize', onResize));
    this.place();
    this.refresh();
    this.poke();
  }

  get expanded(): boolean { return !this.panel.hidden; }

  toggle(open = !this.expanded): void {
    this.panel.hidden = !open;
    this.handle.setAttribute('aria-expanded', String(open));
    this.el.dataset.open = open ? '1' : '0';
    this.refresh();
    this.poke();
  }

  refresh(): void {
    for (const it of this.items) {
      const b = this.btns.get(it.id)!;
      const on = it.active?.() ?? false;
      b.dataset.active = on ? '1' : '0';
      b.setAttribute('aria-pressed', String(on));
    }
  }

  setLabel(id: string, label: string, icon?: string): void {
    const b = this.btns.get(id);
    if (!b) return;
    b.querySelector('.lst-lb')!.textContent = label;
    if (icon) b.querySelector('.lst-ic')!.textContent = icon;
    b.title = label;
    b.setAttribute('aria-label', label);
  }

  /** Wake from idle fade. */
  poke(): void {
    this.el.classList.remove('lst-idle');
    if (this.fadeT) clearTimeout(this.fadeT);
    this.fadeT = setTimeout(() => { if (!this.expanded) this.el.classList.add('lst-idle'); }, this.o.idleFadeMs ?? 2500);
  }

  private place(): void {
    const r = this.parent.getBoundingClientRect();
    const hh = 56;
    const y = Math.max(8, Math.min(r.height - hh - 8, this.pos.y * r.height - hh / 2));
    this.el.dataset.side = this.pos.side;
    this.el.style.top = `${y}px`;
    this.el.style.left = this.pos.side === 'left' ? '0px' : '';
    this.el.style.right = this.pos.side === 'right' ? '0px' : '';
  }

  private dragging(h: HTMLElement): void {
    let id = -1, sx = 0, sy = 0, moved = false, ox = 0, oy = 0;
    const down = (e: PointerEvent) => {
      id = e.pointerId; sx = e.clientX; sy = e.clientY; moved = false;
      const r = this.el.getBoundingClientRect();
      ox = e.clientX - r.left; oy = e.clientY - r.top;
      try { h.setPointerCapture(id); } catch { /* synthetic */ }
      e.preventDefault();
      e.stopPropagation();
      this.poke();
    };
    const move = (e: PointerEvent) => {
      if (e.pointerId !== id) return;
      if (!moved && Math.hypot(e.clientX - sx, e.clientY - sy) < 8) return;
      moved = true;
      const pr = this.parent.getBoundingClientRect();
      this.el.style.left = `${e.clientX - pr.left - ox}px`;
      this.el.style.right = '';
      this.el.style.top = `${e.clientY - pr.top - oy}px`;
      this.el.dataset.side = 'drag';
      e.preventDefault();
      e.stopPropagation();
    };
    const up = (e: PointerEvent) => {
      if (e.pointerId !== id) return;
      id = -1;
      e.stopPropagation();
      if (!moved) { this.toggle(); return; }
      const pr = this.parent.getBoundingClientRect();
      this.pos = { side: e.clientX - pr.left < pr.width / 2 ? 'left' : 'right', y: Math.min(0.95, Math.max(0.05, (e.clientY - pr.top) / pr.height)) };
      try { localStorage.setItem(this.o.storageKey ?? 'lst.toolbar', JSON.stringify(this.pos)); } catch { /* ignore */ }
      this.place();
    };
    h.addEventListener('pointerdown', down);
    h.addEventListener('pointermove', move);
    h.addEventListener('pointerup', up);
    h.addEventListener('pointercancel', up);
    // keyboard access
    h.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.toggle(); } });
    // keep toolbar touches away from the gesture engine on the stage
    for (const n of ['pointerdown', 'pointermove', 'pointerup']) this.panel.addEventListener(n, (e) => e.stopPropagation());
  }

  destroy(): void {
    if (this.fadeT) clearTimeout(this.fadeT);
    this.L.forEach((f) => f());
    this.el.remove();
  }
}
