/**
 * Character -> (KeyboardEvent.code, shift) for a US-ANSI host layout.
 * Used by the on-screen keyboard (iPad / Android soft keyboards don't give us
 * reliable `code`s) and by "type clipboard as keystrokes". Characters outside
 * the table are sent as INPUT_UNICODE (KEYEVENTF_UNICODE on the host).
 */
const MAP: Record<string, [string, boolean]> = {};

const plain = '`1234567890-=qwertyuiop[]\\asdfghjkl;\'zxcvbnm,./ ';
const shifted = '~!@#$%^&*()_+QWERTYUIOP{}|ASDFGHJKL:"ZXCVBNM<>? ';
const codes = [
  'Backquote', 'Digit1', 'Digit2', 'Digit3', 'Digit4', 'Digit5', 'Digit6', 'Digit7', 'Digit8', 'Digit9', 'Digit0', 'Minus', 'Equal',
  'KeyQ', 'KeyW', 'KeyE', 'KeyR', 'KeyT', 'KeyY', 'KeyU', 'KeyI', 'KeyO', 'KeyP', 'BracketLeft', 'BracketRight', 'Backslash',
  'KeyA', 'KeyS', 'KeyD', 'KeyF', 'KeyG', 'KeyH', 'KeyJ', 'KeyK', 'KeyL', 'Semicolon', 'Quote',
  'KeyZ', 'KeyX', 'KeyC', 'KeyV', 'KeyB', 'KeyN', 'KeyM', 'Comma', 'Period', 'Slash', 'Space',
];
for (let i = 0; i < codes.length; i++) {
  MAP[plain[i]] = [codes[i], false];
  if (shifted[i] !== ' ') MAP[shifted[i]] = [codes[i], true];
}
MAP['\n'] = ['Enter', false];
MAP['\r'] = ['Enter', false];
MAP['\t'] = ['Tab', false];

export function charToKey(ch: string): [code: string, shift: boolean] | undefined {
  return MAP[ch];
}
