import type { CodecPref } from './session';
import type { MouseMode } from './input';
import type { TouchMode } from './touch';
import type { Offerer } from './signaling';
import { CLOUD_WSS, normaliseDeviceId } from './devices';
import { detectCar, parseCarHash, type CarBrand, type CarControl, type CarNet, type CarSeat } from './car';

export interface Settings {
  signalUrl: string;
  lastCode: string;
  authMode: 'code' | 'secret' | 'device';
  /** v1.2: last permanent Device ID typed (never the password). */
  deviceId: string;
  offerer: Offerer;
  codec: CodecPref;
  mouseMode: MouseMode;
  touchMode: TouchMode;
  sensitivity: number;
  macCmdAsCtrl: boolean;
  showHud: boolean;
  iceServers: string; // JSON array of RTCIceServer
  clientName: string;
  pasteSendsCtrlV: boolean;
  // ── car cockpit mode ──
  carMode: boolean;
  carBrand: CarBrand;
  carControl: CarControl;
  carNet: CarNet;
  carSeat: CarSeat;
  carDockSide: 'left' | 'right';
  carParkedAck: boolean;
  /** Set by a host QR link carrying `codec=` — the codec is then locked for the car session. */
  carCodecLock: boolean;
}

const KEY = 'leestream.web.settings.v1';
const isTouch = typeof matchMedia !== 'undefined' && matchMedia('(pointer: coarse)').matches;

export const DEFAULTS: Settings = {
  signalUrl: CLOUD_WSS,
  lastCode: '',
  authMode: 'device',
  deviceId: '',
  offerer: 'host',
  codec: 'auto',
  mouseMode: isTouch ? 'absolute' : 'relative',
  touchMode: 'trackpad',
  sensitivity: 1,
  macCmdAsCtrl: false,
  showHud: true,
  iceServers: JSON.stringify([
    { urls: 'stun:stun.miwifi.com:3478' },
    { urls: 'stun:stun.cloudflare.com:3478' },
    { urls: 'stun:stun.l.google.com:19302' },
  ]),
  clientName: 'Web client',
  pasteSendsCtrlV: true,
  carMode: false,
  carBrand: 'generic',
  carControl: 'direct',
  carNet: 'auto',
  carSeat: 'center',
  carDockSide: 'left',
  carParkedAck: false,
  carCodecLock: false,
};

export function loadSettings(): Settings {
  try {
    const raw = localStorage.getItem(KEY);
    const s = raw ? { ...DEFAULTS, ...(JSON.parse(raw) as Partial<Settings>) } : { ...DEFAULTS };
    // URL overrides: ?sig=wss://host:47901/ws&code=123456&offerer=client&codec=hevc
    const q = new URLSearchParams(location.search);
    const sig = q.get('sig');
    if (sig) s.signalUrl = sig;
    // ?device=123456789 (or #device=) opens straight on that PC
    const dev = normaliseDeviceId(q.get('device') ?? new URLSearchParams(location.hash.slice(1)).get('device') ?? '');
    if (dev) {
      s.deviceId = dev;
      s.authMode = 'device';
      if (!sig && !s.signalUrl) s.signalUrl = CLOUD_WSS;
    }
    const off = q.get('offerer');
    if (off === 'host' || off === 'client') s.offerer = off;
    const codec = q.get('codec');
    if (codec === 'auto' || codec === 'h264' || codec === 'hevc' || codec === 'av1') s.codec = codec;
    applyCarOverrides(s);
    return s;
  } catch {
    const s = { ...DEFAULTS };
    applyCarOverrides(s);
    return s;
  }
}

/** `#car=1&wss=…&code=…` deep links + car UA auto-detection (first run only). */
function applyCarOverrides(s: Settings): void {
  const link = parseCarHash();
  const q = new URLSearchParams(location.search);
  let firstRun = true;
  try {
    firstRun = localStorage.getItem(KEY) === null;
  } catch {
    /* ignore */
  }
  if (firstRun) {
    const det = detectCar();
    if (det.isCar) {
      s.carMode = true;
      if (det.brand) s.carBrand = det.brand;
    } else if (det.brand) s.carBrand = det.brand;
  }
  if (link.car || q.get('car') === '1') s.carMode = true;
  if (q.get('car') === '0' || /(^|[#&])car=0/.test(location.hash)) s.carMode = false;
  if (link.wss) s.signalUrl = link.wss;
  if (link.codec) {
    s.codec = link.codec;
    s.carCodecLock = true;
  }
  if (link.brand) s.carBrand = link.brand;
  if (link.control) s.carControl = link.control;
  if (link.net) s.carNet = link.net;
  if (link.seat) s.carSeat = link.seat;
  if (link.code) {
    s.lastCode = link.code;
    s.authMode = 'code';
  }
}

export function saveSettings(s: Settings): void {
  try {
    localStorage.setItem(KEY, JSON.stringify({ ...s, lastCode: '', carCodecLock: false }));
  } catch {
    /* private mode */
  }
}

export function parseIceServers(json: string): RTCIceServer[] {
  try {
    const v = JSON.parse(json) as unknown;
    return Array.isArray(v) ? (v as RTCIceServer[]) : [];
  } catch {
    return [];
  }
}
