import { useCallback, useEffect, useRef, useState } from 'react';
import { ConnectScreen, type ConnectRequest } from './components/ConnectScreen';
import { Player } from './components/Player';
import { LeeStreamSession } from './lib/session';
import { upsertDevice } from './lib/devices';
import { nextAttempt, reconnectDelay, resumeCredential, retryBlocked, RECONNECT_ATTEMPT_TIMEOUT_MS, RECONNECT_DELAYS_MS } from './lib/reconnect';

/** Sessions that already have a rebuild scheduled. */
const retried = new WeakSet<LeeStreamSession>();
import { WebSocketSignal, normaliseSignalUrl } from './lib/signaling';
import { LoopbackHost } from './lib/loopback';
import { loadSettings, parseIceServers, saveSettings, type Settings } from './lib/settings';
import { CarLauncher } from './components/CarLauncher';
import { CAR_MEDIA_PROFILE, CLIENT_TO_GATEWAY, carCodec, extractCarLink, netPolicy, parseCarHash, presetById } from './lib/car';

export default function App() {
  const [settings, setSettingsState] = useState<Settings>(() => loadSettings());
  const [session, setSession] = useState<LeeStreamSession | null>(null);
  const [demo, setDemo] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [gen, setGen] = useState(0);
  const retryTimer = useRef(0);
  const connectRef = useRef<(r: ConnectRequest, attempt?: number) => Promise<void>>(async () => undefined);

  const setSettings = useCallback((patch: Partial<Settings>) => {
    setSettingsState((s) => {
      const n = { ...s, ...patch };
      saveSettings(n);
      return n;
    });
  }, []);

  const connect = useCallback(
    async (req: ConnectRequest, attempt = 0) => {
      clearTimeout(retryTimer.current);
      setError(null);
      setBusy(true);
      // Rebuild a dropped stream with the pairing secret (typed Direct secret or the bridge's resume secret).
      const scheduleRetry = (detail: string, from: LeeStreamSession | null, n: number): boolean => {
        if (retryBlocked(from)) return false; // from?.preempted — another client took over: never fight back
        if (from && retried.has(from)) return true; // one rebuild per dead session
        const secret = resumeCredential(req.secret, from?.resumeSecret);
        const delay = secret ? reconnectDelay(n) : null;
        if (delay == null) return false;
        if (from) retried.add(from);
        from?.markReconnecting(`${detail} — reconnecting in ${Math.round(delay / 1000)} s (${n + 1}/${RECONNECT_DELAYS_MS.length})`);
        retryTimer.current = window.setTimeout(() => {
          void connectRef.current({ secret, device: req.device, wss: req.wss ?? settings.signalUrl }, n + 1); // swaps the Player to the new session synchronously
          from?.close(); // tells the bridge/host the old session is gone (host frees capture at once)
        }, delay);
        return true;
      };
      try {
        const preset = presetById(settings.carBrand);
        const car = settings.carMode;
        const pol = netPolicy(settings.carNet);
        const codec = car ? carCodec(preset, settings.carNet, settings.codec, settings.carCodecLock) : settings.codec;
        const carProfile = car
          ? {
              brand: CLIENT_TO_GATEWAY[preset.id],
              seat: settings.carSeat,
              video: { ...CAR_MEDIA_PROFILE.video, codec: codec === 'auto' ? 'auto' : codec },
              audio: { ...CAR_MEDIA_PROFILE.audio },
            }
          : undefined;
        const transport = req.demo ? new LoopbackHost(car ? { carLabel: `${preset.emoji} ${preset.name} ${preset.nameEn}` } : {}) : new WebSocketSignal(normaliseSignalUrl(req.wss ?? settings.signalUrl));
        const s = new LeeStreamSession({
          transport,
          code: req.code,
          secret: req.secret,
          device: req.device,
          password: req.password,
          offerer: settings.offerer,
          iceServers: req.demo ? [] : parseIceServers(settings.iceServers),
          codec,
          strictCodec: car && (settings.carCodecLock || !!preset.lockCodec || pol.forceH264),
          jitterTargetMs: car ? pol.jitterTargetMs : 0,
          startKbps: car ? pol.startKbps : undefined,
          clientName: car ? `${settings.clientName} · ${preset.nameEn}` : settings.clientName,
          clientExtra: carProfile ? { car: carProfile } : undefined,
          car: carProfile,
          autoReconnect: !req.demo,
        });
        const off = s.on('state', (st, detail) => {
          if (st === 'closed' && s.preempted) {
            // Taken over by a native/second client: back to the connect screen, no auto-reconnect ping-pong.
            clearTimeout(retryTimer.current);
            setError(`${detail ?? 'Connected from another device'} — tap Connect to take over.`);
            setSession(null);
            return;
          }
          // a reconnect attempt that died before media (signaling error or ICE never connected): keep trying
          if (st === 'failed' && attempt > 0 && s.upMs === 0 && scheduleRetry(detail ?? 'reconnect failed', s, attempt)) return;
          if (st === 'failed' && !s.pc.remoteDescription) {
            // failed before media: go back to the connect screen with the reason
            setError(detail ?? 'Connection failed');
            s.close();
            setSession(null);
          }
        });
        // v1.2 My Devices: once streaming, remember this PC with the per-device secret (never the password)
        if (req.device) {
          const offSave = s.on('state', (st) => {
            if (st !== 'connected') return;
            const secret = resumeCredential(req.secret, s.resumeSecret);
            if (secret) upsertDevice({ id: req.device!, secret, wss: req.wss ?? settings.signalUrl, name: s.hostName && s.hostName !== 'LeeStream host' ? s.hostName : undefined });
            offSave();
          });
        }
        s.on('lost', (detail) => {
          if (!scheduleRetry(detail, s, nextAttempt(attempt, s.upMs))) {
            s.fail(`Connection lost: ${detail}${s.resumeSecret || req.secret ? ' (reconnect attempts used up)' : ''}`);
          }
        });
        if (attempt > 0) {
          // ICE can sit in "checking" for ~30 s while the network is still down: cut the attempt short
          window.setTimeout(() => {
            if (s.upMs === 0 && s.state !== 'closed') scheduleRetry('reconnect timed out', s, attempt);
          }, RECONNECT_ATTEMPT_TIMEOUT_MS);
        }
        setDemo(!!req.demo);
        setGen((g) => g + 1);
        setSession(s);
        await s.start();
        void off;
      } catch (e) {
        if (attempt > 0 && scheduleRetry((e as Error).message, null, attempt)) return;
        setError((e as Error).message);
        setSession(null);
      } finally {
        setBusy(false);
      }
    },
    [settings],
  );
  connectRef.current = connect;

  const disconnect = useCallback(() => {
    clearTimeout(retryTimer.current);
    session?.close();
    setSession(null);
    if (document.fullscreenElement) void document.exitFullscreen().catch(() => undefined);
  }, [session]);

  // Deep link: ?demo=1  or  ?sig=...&code=123456  auto-connects.
  const autoStarted = useRef(false);
  useEffect(() => {
    if (autoStarted.current) return; // StrictMode runs effects twice in dev
    autoStarted.current = true;
    const q = new URLSearchParams(location.search);
    const link = parseCarHash();
    if (q.get('demo') === '1' || (link.car && link.demo)) void connect({ demo: true });
    else if (q.get('sig') && /^\d{6}$/.test(q.get('code') ?? '')) void connect({ code: q.get('code')! });
    else if (link.car && link.go && link.wss && link.code) void connect({ code: link.code });
  }, []);

  // Also apply pasted/updated hash deep links if the user opens another link in the same tab.
  useEffect(() => {
    const onHash = () => {
      const link = parseCarHash();
      if (!link.car && !link.wss && !link.code) return;
      setSettings({
        ...(link.car ? { carMode: true } : {}),
        ...(link.wss ? { signalUrl: link.wss } : {}),
        ...(link.code ? { lastCode: link.code, authMode: 'code' as const } : {}),
        ...(link.brand ? { carBrand: link.brand } : {}),
        ...(link.codec ? { codec: link.codec, carCodecLock: true } : {}),
      });
    };
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, [setSettings]);

  // Keep extracted/normalised URL if an earlier session stored an unwrapped share link in signalUrl.
  useEffect(() => {
    const pasted = extractCarLink(settings.signalUrl);
    if (pasted?.wss) {
      setSettings({
        signalUrl: pasted.wss,
        ...(pasted.code && !settings.lastCode ? { lastCode: pasted.code, authMode: 'code' as const } : {}),
      });
    }
  }, [settings.signalUrl, settings.lastCode, setSettings]);

  if (session) {
    return <Player key={`${demo}-${gen}`} session={session} settings={settings} setSettings={setSettings} demo={demo} onDisconnect={disconnect} />;
  }
  if (settings.carMode) {
    return <CarLauncher settings={settings} setSettings={setSettings} onConnect={connect} error={error} busy={busy} />;
  }
  return <ConnectScreen settings={settings} setSettings={setSettings} onConnect={connect} error={error} busy={busy} />;
}
