// Vendored from leestream-touch (2026-11-26 package, src/geometry.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// Screen ⇄ remote-desktop coordinate mapping, including the pinch-zoom viewport.
import { ABS_MAX } from './protocol';

export interface Rect { x: number; y: number; w: number; h: number }

/** Letterboxed content rect of a video shown with object-fit: contain inside `box`. */
export function containRect(box: Rect, videoW: number, videoH: number): Rect {
  if (!videoW || !videoH) return { ...box };
  const s = Math.min(box.w / videoW, box.h / videoH);
  const w = videoW * s, h = videoH * s;
  return { x: box.x + (box.w - w) / 2, y: box.y + (box.h - h) / 2, w, h };
}

/**
 * Pinch/pan viewport over the stage. Applied to the <video> as
 * `transform: translate(tx,ty) scale(s)` with transform-origin 0 0, so a stage point p shows
 * the unzoomed point (p - t) / s.
 */
export class Viewport {
  scale = 1;
  tx = 0;
  ty = 0;
  constructor(public minScale = 1, public maxScale = 5) {}

  /** Stage width/height the transform is clamped against. */
  w = 0;
  h = 0;
  setSize(w: number, h: number): void { this.w = w; this.h = h; this.clamp(); }

  /** Zoom by `factor` keeping stage point (cx, cy) fixed. */
  zoomAt(factor: number, cx: number, cy: number): void {
    const ns = Math.max(this.minScale, Math.min(this.maxScale, this.scale * factor));
    const k = ns / this.scale;
    this.tx = cx - (cx - this.tx) * k;
    this.ty = cy - (cy - this.ty) * k;
    this.scale = ns;
    this.clamp();
  }

  pan(dx: number, dy: number): void { this.tx += dx; this.ty += dy; this.clamp(); }

  reset(): void { this.scale = 1; this.tx = 0; this.ty = 0; }

  get zoomed(): boolean { return this.scale > 1.001; }

  /** Keep the zoomed content covering the stage (no empty margins once zoomed in). */
  clamp(): void {
    if (this.scale <= 1) { this.scale = Math.max(this.scale, this.minScale); this.tx = 0; this.ty = 0; return; }
    const minX = this.w - this.w * this.scale, minY = this.h - this.h * this.scale;
    this.tx = Math.min(0, Math.max(minX, this.tx));
    this.ty = Math.min(0, Math.max(minY, this.ty));
  }

  /** Stage point → unzoomed stage point. */
  unproject(x: number, y: number): [number, number] {
    return [(x - this.tx) / this.scale, (y - this.ty) / this.scale];
  }
  /** Unzoomed stage point → stage point. */
  project(x: number, y: number): [number, number] {
    return [x * this.scale + this.tx, y * this.scale + this.ty];
  }

  css(): string {
    return `translate(${this.tx.toFixed(2)}px, ${this.ty.toFixed(2)}px) scale(${this.scale.toFixed(4)})`;
  }

  /** Pan so that unzoomed point (x, y) is visible with `margin` px around it (cursor follow). */
  ensureVisible(x: number, y: number, margin = 40): void {
    if (!this.zoomed) return;
    const [sx, sy] = this.project(x, y);
    if (sx < margin) this.tx += margin - sx;
    else if (sx > this.w - margin) this.tx -= sx - (this.w - margin);
    if (sy < margin) this.ty += margin - sy;
    else if (sy > this.h - margin) this.ty -= sy - (this.h - margin);
    this.clamp();
  }
}

/**
 * Maps between stage-local coordinates (relative to the stage element's top-left) and the
 * remote 0..65535 absolute space, taking letterboxing and the zoom viewport into account.
 */
export class Mapper {
  constructor(public viewport: Viewport, private content: () => Rect) {}

  /** Stage-local point → normalised remote [0..1] (clamped). */
  toNorm(x: number, y: number): [number, number] {
    const [ux, uy] = this.viewport.unproject(x, y);
    const r = this.content();
    const fx = r.w > 0 ? (ux - r.x) / r.w : 0;
    const fy = r.h > 0 ? (uy - r.y) / r.h : 0;
    return [Math.min(1, Math.max(0, fx)), Math.min(1, Math.max(0, fy))];
  }
  toAbs(x: number, y: number): [number, number] {
    const [fx, fy] = this.toNorm(x, y);
    return [Math.round(fx * ABS_MAX), Math.round(fy * ABS_MAX)];
  }
  /** Normalised remote point → unzoomed stage-local point. */
  normToStage(fx: number, fy: number): [number, number] {
    const r = this.content();
    return [r.x + fx * r.w, r.y + fy * r.h];
  }
  /** How many normalised units one on-screen pixel spans at the current zoom (x, y). */
  pxToNorm(): [number, number] {
    const r = this.content();
    const s = this.viewport.scale;
    return [r.w > 0 ? 1 / (r.w * s) : 0, r.h > 0 ? 1 / (r.h * s) : 0];
  }
}
