// Vendored from leestream-touch (2026-11-26 package, src/gestures.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// Pure multi-touch gesture recogniser. No DOM: feed it pointer samples and timer ticks, it
// emits high-level actions. All coordinates are stage-local CSS pixels, times in ms.
//
//  Fingers | Gesture                         | direct (touch) mode          | trackpad mode
//  --------+---------------------------------+------------------------------+-----------------------------
//  1       | tap                             | left click at finger         | left click at cursor
//  1       | tap, tap                        | double click                 | double click
//  1       | long press (500 ms)             | right click at finger        | right click at cursor
//  1       | drag                            | left-drag (or hover, option) | move cursor (accelerated)
//  1       | tap then touch-and-drag         | —                            | left-drag from cursor
//  2       | tap                             | right click at centroid      | right click at cursor
//  2       | move together                   | scroll wheel (+ momentum)    | scroll wheel (+ momentum)
//  2       | pinch                           | zoom viewport at centroid    | zoom viewport at centroid
//  3       | move                            | pan zoomed viewport          | pan zoomed viewport
//  3       | tap                             | toggle virtual keyboard      | toggle virtual keyboard

export type Mode = 'direct' | 'trackpad';

export type Action =
  | { t: 'pointer'; x: number; y: number }               // direct: put the remote cursor under this stage point
  | { t: 'cursor'; dx: number; dy: number }              // trackpad: move the virtual cursor by stage px
  | { t: 'button'; button: number; down: boolean }       // at the current cursor
  | { t: 'click'; button: number }                       // down+up at the current cursor
  | { t: 'wheel'; dx: number; dy: number }               // stage px of finger travel; dy>0 = fingers moved down
  | { t: 'zoom'; factor: number; cx: number; cy: number }
  | { t: 'pan'; dx: number; dy: number }
  | { t: 'haptic'; ms: number }
  | { t: 'threeFingerTap' };

export interface GestureConfig {
  tapSlop: number;          // px a finger may wander and still count as a tap
  tapMaxMs: number;         // max finger-down time for multi-finger taps
  longPressMs: number;
  doubleTapMs: number;      // trackpad: tap → touch gap that arms tap-drag
  pinchThreshold: number;   // px change of finger distance that commits to pinch
  directDrag: 'drag' | 'hover';
  trackpadSpeed: number;    // base cursor gain
  trackpadAccel: number;    // extra gain per px/ms of finger speed
  momentum: boolean;
  momentumDecay: number;    // velocity multiplier per 16 ms
}

export const defaultConfig: GestureConfig = {
  tapSlop: 10,
  tapMaxMs: 300,
  longPressMs: 500,
  doubleTapMs: 280,
  pinchThreshold: 24,
  directDrag: 'drag',
  trackpadSpeed: 1.0,
  trackpadAccel: 0.9,
  momentum: true,
  momentumDecay: 0.92,
};

interface Finger { x: number; y: number; sx: number; sy: number; t0: number; lx: number; ly: number }

type Phase =
  | 'idle' | 'pending1' | 'move1' | 'drag1' | 'long'
  | 'pending2' | 'scroll' | 'pinch'
  | 'pending3' | 'pan3'
  | 'done';

const LEFT = 0, RIGHT = 1;

export class GestureEngine {
  cfg: GestureConfig;
  mode: Mode;
  private f = new Map<number, Finger>();
  private phase: Phase = 'idle';
  private t0 = 0;                     // gesture start
  private moved = false;              // any finger left the tap slop during this gesture
  private holding = false;            // left button held by us
  private lastTapEnd = -1e9;
  private lastTapX = 0;
  private lastTapY = 0;
  private tapDragArmed = false;
  private longAt: number | null = null;
  // two/three finger tracking
  private cx = 0; private cy = 0; private dist = 0; private dist0 = 0; private cx0 = 0; private cy0 = 0;
  // momentum
  private vx = 0; private vy = 0; private lastMoveT = 0; private momentumT: number | null = null;

  constructor(private emit: (a: Action) => void, mode: Mode = 'direct', cfg: Partial<GestureConfig> = {}) {
    this.mode = mode;
    this.cfg = { ...defaultConfig, ...cfg };
  }

  get fingers(): number { return this.f.size; }
  get state(): string { return this.phase; }

  setMode(m: Mode): void { this.cancel(); this.mode = m; }

  /** Earliest time tick() must be called (long press / momentum), or null. */
  nextDeadline(): number | null {
    if (this.longAt !== null) return this.longAt;
    if (this.momentumT !== null) return this.momentumT;
    return null;
  }

  tick(now: number): void {
    if (this.longAt !== null && now >= this.longAt) {
      this.longAt = null;
      if (this.phase === 'pending1' && this.f.size === 1) {
        const p = [...this.f.values()][0];
        if (this.mode === 'direct') this.emit({ t: 'pointer', x: p.sx, y: p.sy });
        this.emit({ t: 'haptic', ms: 12 });
        this.emit({ t: 'click', button: RIGHT });
        this.phase = 'long';
        this.tapDragArmed = false;
      }
    }
    if (this.momentumT !== null && now >= this.momentumT) {
      const k = this.cfg.momentumDecay;
      this.vx *= k; this.vy *= k;
      const dx = this.vx * 16, dy = this.vy * 16;
      if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) { this.momentumT = null; this.vx = this.vy = 0; return; }
      this.emit({ t: 'wheel', dx, dy });
      this.momentumT = now + 16;
    }
  }

  down(id: number, x: number, y: number, t: number): void {
    this.momentumT = null;
    if (this.f.has(id)) return;
    this.f.set(id, { x, y, sx: x, sy: y, t0: t, lx: x, ly: y });
    const n = this.f.size;
    if (n === 1) {
      this.t0 = t;
      this.moved = false;
      this.phase = 'pending1';
      this.longAt = t + this.cfg.longPressMs;
      this.tapDragArmed = this.mode === 'trackpad' && t - this.lastTapEnd <= this.cfg.doubleTapMs &&
        Math.hypot(x - this.lastTapX, y - this.lastTapY) < this.cfg.tapSlop * 4;
      return;
    }
    this.longAt = null;
    if (n === 2) {
      if (this.phase === 'pending1' || this.phase === 'move1') {
        this.phase = 'pending2';
        this.tapDragArmed = false;
        this.startMulti();
      } else if (this.phase === 'drag1' || this.phase === 'long') {
        // Second finger during a drag: finish the drag cleanly, ignore the rest of this gesture.
        this.releaseLeft();
        this.phase = 'done';
      }
      return;
    }
    if (n === 3 && (this.phase === 'pending2' || this.phase === 'scroll' || this.phase === 'pinch')) {
      this.phase = 'pending3';
      this.startMulti();
      return;
    }
    if (n > 3 && this.phase !== 'done') { this.releaseLeft(); this.phase = 'done'; }
  }

  move(id: number, x: number, y: number, t: number): void {
    const p = this.f.get(id);
    if (!p) return;
    const dxLast = x - p.x, dyLast = y - p.y;
    p.lx = p.x; p.ly = p.y; p.x = x; p.y = y;
    if (Math.hypot(x - p.sx, y - p.sy) > this.cfg.tapSlop) this.moved = true;

    switch (this.phase) {
      case 'pending1': {
        if (!this.moved) return;
        this.longAt = null;
        if (this.mode === 'direct') {
          this.emit({ t: 'pointer', x: p.sx, y: p.sy });
          if (this.cfg.directDrag === 'drag') { this.emit({ t: 'button', button: LEFT, down: true }); this.holding = true; this.phase = 'drag1'; }
          else this.phase = 'move1';
          this.emit({ t: 'pointer', x, y });
        } else {
          if (this.tapDragArmed) { this.emit({ t: 'button', button: LEFT, down: true }); this.holding = true; this.phase = 'drag1'; }
          else this.phase = 'move1';
          this.trackpad(x - p.sx, y - p.sy, t);
        }
        this.lastMoveT = t;
        return;
      }
      case 'move1':
      case 'drag1':
        if (this.mode === 'direct') this.emit({ t: 'pointer', x, y });
        else this.trackpad(dxLast, dyLast, t);
        this.lastMoveT = t;
        return;
      case 'pending2':
      case 'scroll':
      case 'pinch':
        if (this.f.size === 2) this.multiMove2(t);
        return;
      case 'pending3':
      case 'pan3':
        if (this.f.size === 3) this.multiMove3();
        return;
      default:
        return;
    }
  }

  up(id: number, x: number, y: number, t: number): void {
    const p = this.f.get(id);
    if (!p) return;
    if (x !== p.x || y !== p.y) this.move(id, x, y, t);
    this.f.delete(id);
    const n = this.f.size;
    switch (this.phase) {
      case 'pending1':
        if (n === 0) {
          this.longAt = null;
          if (this.mode === 'direct') this.emit({ t: 'pointer', x: p.sx, y: p.sy });
          this.emit({ t: 'click', button: LEFT });
          this.lastTapEnd = t; this.lastTapX = p.sx; this.lastTapY = p.sy;
          this.phase = 'idle';
        }
        return;
      case 'move1':
      case 'drag1':
      case 'long':
        if (n === 0) { this.releaseLeft(); this.phase = 'idle'; }
        return;
      case 'pending2':
        // first finger lifted of an unmoved two-finger touch → two-finger tap
        if (!this.moved && t - this.t0 <= this.cfg.tapMaxMs * 1.5) {
          if (this.mode === 'direct') this.emit({ t: 'pointer', x: this.cx, y: this.cy });
          this.emit({ t: 'click', button: RIGHT });
        }
        this.phase = n === 0 ? 'idle' : 'done';
        return;
      case 'scroll':
        if (this.cfg.momentum && t - this.lastMoveT < 50 && Math.hypot(this.vx, this.vy) > 0.3) this.momentumT = t + 16;
        this.phase = n === 0 ? 'idle' : 'done';
        return;
      case 'pinch':
        this.phase = n === 0 ? 'idle' : 'done';
        return;
      case 'pending3':
        if (!this.moved && t - this.t0 <= this.cfg.tapMaxMs * 2) this.emit({ t: 'threeFingerTap' });
        this.phase = n === 0 ? 'idle' : 'done';
        return;
      case 'pan3':
      case 'done':
      case 'idle':
        if (n === 0) this.phase = 'idle';
        return;
    }
  }

  /** Pointer cancelled by the browser (system gesture, call, etc.). */
  cancelPointer(id: number): void {
    if (!this.f.delete(id)) return;
    if (this.f.size === 0) this.cancel();
    else { this.releaseLeft(); this.phase = 'done'; }
  }

  /** Abort everything and release any held button. */
  cancel(): void {
    this.releaseLeft();
    this.f.clear();
    this.phase = 'idle';
    this.longAt = null;
    this.momentumT = null;
  }

  // ---------------------------------------------------------------------------------------

  private releaseLeft(): void {
    if (this.holding) { this.emit({ t: 'button', button: LEFT, down: false }); this.holding = false; }
  }

  private trackpad(dx: number, dy: number, t: number): void {
    const dt = Math.max(1, t - this.lastMoveT);
    const speed = Math.min(4, Math.hypot(dx, dy) / dt);
    const g = this.cfg.trackpadSpeed * (1 + this.cfg.trackpadAccel * speed);
    if (dx || dy) this.emit({ t: 'cursor', dx: dx * g, dy: dy * g });
  }

  private centroid(): [number, number] {
    let x = 0, y = 0;
    for (const p of this.f.values()) { x += p.x; y += p.y; }
    return [x / this.f.size, y / this.f.size];
  }

  private spread(): number {
    const ps = [...this.f.values()];
    return ps.length >= 2 ? Math.hypot(ps[0].x - ps[1].x, ps[0].y - ps[1].y) : 0;
  }

  private startMulti(): void {
    [this.cx, this.cy] = this.centroid();
    this.cx0 = this.cx; this.cy0 = this.cy;
    this.dist = this.dist0 = this.spread();
    this.vx = this.vy = 0;
    // re-base tap slop on the multi-finger start so the first finger's travel does not count
    for (const p of this.f.values()) { p.sx = p.x; p.sy = p.y; }
    this.moved = false;
  }

  private multiMove2(t: number): void {
    const [x, y] = this.centroid();
    const d = this.spread();
    const dx = x - this.cx, dy = y - this.cy;
    if (this.phase === 'pending2') {
      // Fingers report one at a time, so judge the pair: spread change → pinch, centroid travel → scroll.
      const spreadChange = Math.abs(d - this.dist0);
      const travel = Math.hypot(x - this.cx0, y - this.cy0);
      if (spreadChange > this.cfg.pinchThreshold && spreadChange > travel) this.phase = 'pinch';
      else if (travel > this.cfg.tapSlop && travel >= spreadChange) this.phase = 'scroll';
      else return;
    }
    if (this.phase === 'scroll') {
      if (dx || dy) {
        this.emit({ t: 'wheel', dx, dy });
        const dt = Math.max(1, t - this.lastMoveT);
        this.vx = 0.6 * this.vx + 0.4 * (dx / dt);
        this.vy = 0.6 * this.vy + 0.4 * (dy / dt);
        this.lastMoveT = t;
      }
    } else if (this.phase === 'pinch') {
      if (this.dist > 0 && d > 0 && d !== this.dist) this.emit({ t: 'zoom', factor: d / this.dist, cx: x, cy: y });
      if (dx || dy) this.emit({ t: 'pan', dx, dy });
    }
    this.cx = x; this.cy = y; this.dist = d;
  }

  private multiMove3(): void {
    const [x, y] = this.centroid();
    const dx = x - this.cx, dy = y - this.cy;
    if (this.phase === 'pending3') {
      if (!this.moved) return;
      this.phase = 'pan3';
    }
    if (dx || dy) this.emit({ t: 'pan', dx, dy });
    this.cx = x; this.cy = y;
  }
}
