/**
 * Local Demo / Loopback Test Mode.
 *
 * A complete fake LeeStream host that lives in the same page:
 *   - renders a synthetic 1280×720@60 scene on a <canvas> and streams it with
 *     canvas.captureStream() through a REAL second RTCPeerConnection (H.264 preferred),
 *   - offers the same four DataChannels the real host creates (input/cursor/ctrl/audio),
 *   - decodes every input message with the same codec the Rust host uses and draws
 *     what it received (cursor, buttons, held scan codes, wheel, gamepads, monitor,
 *     privacy, clipboard) back into the video — so you see the full round trip,
 *   - answers ctrl hello/ping/monitor/privacy/clipboard exactly like the host.
 *
 * It implements `SignalTransport`, so the client session code path is identical to
 * a live connection: want -> paired -> offer -> answer -> ice.
 */
import {
  decodeInput,
  encodeCursorShape,
  encodeCursorVisible,
  parseCtrl,
  XI,
  type CtrlIn,
  type GamepadReport,
  type MonitorInfo,
} from './protocol';
import { SCANCODES, scanLabel } from './scancodes';
import type { SigMsg, SignalTransport } from './signaling';

/**
 * Loopback only: libwebrtc's bandwidth estimator ramps from ~300 kbps, which makes the
 * first seconds look blurry. Pin a sane start/min bitrate (the native host controls its
 * encoder directly, so this is not needed in production).
 */
function boostBitrate(sdp: string): string {
  return sdp.replace(/^(a=fmtp:\d+ .*)$/gm, (line) =>
    /x-google-start-bitrate/.test(line) || /apt=/.test(line) ? line : `${line};x-google-start-bitrate=8000;x-google-min-bitrate=4000;x-google-max-bitrate=15000`,
  );
}

const W = 1280;
const H = 720;

const MONITORS: MonitorInfo[] = [
  { index: 0, name: 'DISPLAY1 — 2560×1440 @165', width: 2560, height: 1440, primary: true },
  { index: 1, name: 'DISPLAY2 — 1920×1080 @60', width: 1920, height: 1080 },
  { index: 2, name: 'DISPLAY3 — 3440×1440 @100', width: 3440, height: 1440 },
];
const MONITOR_HUES = [195, 275, 140];

const scanNames = (() => {
  const m = new Map<string, string>();
  for (const [code, sc] of Object.entries(SCANCODES)) {
    const key = `${sc.scan}:${sc.extended ? 1 : 0}`;
    if (!m.has(key)) m.set(key, code);
  }
  return m;
})();

interface HostState {
  cx: number;
  cy: number;
  buttons: Set<number>;
  keys: Map<string, string>;
  wheel: number;
  log: string[];
  pads: Map<number, GamepadReport>;
  monitor: number;
  privacy: boolean;
  clipboard: string;
  inputCount: number;
  lastInputAt: number;
}

export class LoopbackHost implements SignalTransport {
  onmessage: ((msg: SigMsg) => void) | null = null;
  onclose: ((reason: string) => void) | null = null;
  ready = Promise.resolve();

  private pc: RTCPeerConnection | null = null;
  private canvas = document.createElement('canvas');
  private ctx2d: CanvasRenderingContext2D;
  private raf = 0;
  private frame = 0;
  private t0 = performance.now();
  private channels = new Map<string, RTCDataChannel>();
  private st: HostState = {
    cx: W / 2,
    cy: H / 2,
    buttons: new Set(),
    keys: new Map(),
    wheel: 0,
    log: [],
    pads: new Map(),
    monitor: 0,
    privacy: false,
    clipboard: '',
    inputCount: 0,
    lastInputAt: 0,
  };
  private closed = false;

  private carLabel: string | null;
  private bitrateKbps = 0;

  constructor(opts: { carLabel?: string } = {}) {
    this.carLabel = opts.carLabel ?? null;
    this.canvas.width = W;
    this.canvas.height = H;
    this.ctx2d = this.canvas.getContext('2d', { alpha: false })!;
    // Test hook for automated E2E checks (demo mode only).
    (window as unknown as { __lsLoopback?: LoopbackHost }).__lsLoopback = this;
  }

  /** Snapshot of what the fake host has decoded (used by e2e tests). */
  debugState(): { padList: GamepadReport[]; bitrateKbps: number; keys: string[]; buttons: number[]; cx: number; cy: number; wheel: number; inputs: number; pads: number; pad0: GamepadReport | null; monitor: number; privacy: boolean; clipboard: string; log: string[] } {
    const s = this.st;
    return { padList: [...s.pads.values()], bitrateKbps: this.bitrateKbps, keys: [...s.keys.values()], buttons: [...s.buttons], cx: s.cx, cy: s.cy, wheel: s.wheel, inputs: s.inputCount, pads: s.pads.size, pad0: s.pads.get(0) ?? null, monitor: s.monitor, privacy: s.privacy, clipboard: s.clipboard, log: [...s.log] };
  }

  // ── SignalTransport ──────────────────────────────────────────────────────
  send(msg: SigMsg): void {
    // Deliver asynchronously, like a socket would.
    queueMicrotask(() => void this.handle(msg));
  }

  close(): void {
    this.closed = true;
    cancelAnimationFrame(this.raf);
    this.channels.forEach((c) => c.close());
    this.pc?.close();
    this.pc = null;
  }

  private reply(msg: SigMsg): void {
    if (this.closed) return;
    setTimeout(() => this.onmessage?.(msg), 0);
  }

  private async handle(msg: SigMsg): Promise<void> {
    if (this.closed) return;
    switch (msg.type) {
      case 'want':
        this.reply({ type: 'paired', host: 'LOOPBACK-DEMO' });
        if (msg.offerer === 'host') await this.startAsOfferer();
        else this.ensurePeer();
        break;
      case 'offer': {
        const pc = this.ensurePeer();
        await pc.setRemoteDescription({ type: 'offer', sdp: boostBitrate(msg.sdp) });
        // client-offer mode: the client created recvonly sections; attach our track to the video one.
        const track = this.ensureStream().getVideoTracks()[0];
        const vt = pc.getTransceivers().find((t) => t.receiver.track.kind === 'video');
        if (vt) {
          vt.direction = 'sendonly';
          await vt.sender.replaceTrack(track);
          this.tuneSender(vt.sender);
        }
        await pc.setLocalDescription(await pc.createAnswer());
        this.reply({ type: 'answer', sdp: pc.localDescription!.sdp });
        break;
      }
      case 'answer':
        await this.pc?.setRemoteDescription({ type: 'answer', sdp: boostBitrate(msg.sdp) });
        break;
      case 'ice':
        if (this.pc) await this.pc.addIceCandidate(msg.candidate ? { candidate: msg.candidate, sdpMid: msg.sdpMid ?? undefined, sdpMLineIndex: msg.sdpMLineIndex ?? undefined } : { candidate: '' }).catch(() => undefined);
        break;
      case 'bye':
        this.close();
        break;
      default:
        break;
    }
  }

  // ── fake host peer ───────────────────────────────────────────────────────
  private stream: MediaStream | null = null;

  private ensureStream(): MediaStream {
    if (!this.stream) {
      this.stream = this.canvas.captureStream(60);
      const vt = this.stream.getVideoTracks()[0] as MediaStreamTrack & { contentHint: string };
      vt.contentHint = 'motion';
      this.loop();
    }
    return this.stream;
  }

  private ensurePeer(): RTCPeerConnection {
    if (this.pc) return this.pc;
    const pc = new RTCPeerConnection({ iceServers: [] });
    this.pc = pc;
    pc.onicecandidate = (e) =>
      this.reply(
        e.candidate
          ? { type: 'ice', candidate: e.candidate.candidate, sdpMid: e.candidate.sdpMid, sdpMLineIndex: e.candidate.sdpMLineIndex }
          : { type: 'ice', candidate: null },
      );
    pc.ondatachannel = (e) => this.adopt(e.channel);
    return pc;
  }

  private async startAsOfferer(): Promise<void> {
    const pc = this.ensurePeer();
    // Same channel set + reliability as the native host.
    this.adopt(pc.createDataChannel('input', { ordered: true }));
    this.adopt(pc.createDataChannel('ctrl', { ordered: true }));
    this.adopt(pc.createDataChannel('cursor', { ordered: false, maxRetransmits: 2 }));
    this.adopt(pc.createDataChannel('audio', { ordered: false, maxRetransmits: 0 }));
    const stream = this.ensureStream();
    const tr = pc.addTransceiver(stream.getVideoTracks()[0], { direction: 'sendonly', streams: [stream] });
    const caps = RTCRtpSender.getCapabilities?.('video');
    if (caps) {
      const h264 = caps.codecs.filter((c) => /h264/i.test(c.mimeType));
      const rest = caps.codecs.filter((c) => !/h264/i.test(c.mimeType));
      try {
        tr.setCodecPreferences([...h264, ...rest]); // mirror the real host (H.264 first)
      } catch {
        /* ignore */
      }
    }
    this.tuneSender(tr.sender);
    await pc.setLocalDescription(await pc.createOffer());
    this.reply({ type: 'offer', sdp: pc.localDescription!.sdp });
  }

  private tuneSender(sender: RTCRtpSender): void {
    const apply = async () => {
      const p = sender.getParameters();
      if (!p.encodings?.length) return;
      p.encodings[0].maxBitrate = 12_000_000;
      p.encodings[0].maxFramerate = 60;
      (p as RTCRtpSendParameters & { degradationPreference?: string }).degradationPreference = 'maintain-framerate';
      await sender.setParameters(p).catch(() => undefined);
    };
    setTimeout(() => void apply(), 500);
  }

  private adopt(ch: RTCDataChannel): void {
    ch.binaryType = 'arraybuffer';
    this.channels.set(ch.label, ch);
    if (ch.label === 'input') ch.onmessage = (e) => this.onInput(e.data as ArrayBuffer);
    if (ch.label === 'ctrl') ch.onmessage = (e) => this.onCtrl(String(e.data));
    if (ch.label === 'cursor') ch.onopen = () => void this.sendCursorShape();
  }

  private sendCtrl(m: CtrlIn): void {
    const ch = this.channels.get('ctrl');
    if (ch?.readyState === 'open') ch.send(JSON.stringify(m));
  }

  private async sendCursorShape(): Promise<void> {
    const c = document.createElement('canvas');
    c.width = 24;
    c.height = 24;
    const g = c.getContext('2d')!;
    g.beginPath();
    g.moveTo(1, 1);
    g.lineTo(1, 19);
    g.lineTo(6, 14);
    g.lineTo(10, 22);
    g.lineTo(13, 21);
    g.lineTo(9, 13);
    g.lineTo(16, 13);
    g.closePath();
    g.fillStyle = '#fff';
    g.strokeStyle = '#000';
    g.lineWidth = 1.5;
    g.fill();
    g.stroke();
    const blob = await new Promise<Blob | null>((r) => c.toBlob(r, 'image/png'));
    if (!blob) return;
    const png = new Uint8Array(await blob.arrayBuffer());
    const ch = this.channels.get('cursor');
    if (ch?.readyState === 'open') {
      ch.send(encodeCursorShape(1, 1, png));
      ch.send(encodeCursorVisible(true));
    }
  }

  private onCtrl(raw: string): void {
    const m = parseCtrl(raw) as unknown as { t: string; [k: string]: unknown } | null;
    if (!m) return;
    switch (m.t) {
      case 'hello':
        if (m.car) {
          const c = m.car as { brand: string; video: { codec: string; width: number; height: number; fps: number }; audio: { kbps: number } };
          this.logLine(`car ${c.brand} ${c.video.codec} ${c.video.width}x${c.video.height}@${c.video.fps} opus ${c.audio.kbps}k`);
        }
        this.sendCtrl({ t: 'welcome', host: 'LOOPBACK-DEMO', version: '1.0.0-loopback', monitors: MONITORS, monitor: this.st.monitor });
        this.sendCtrl({ t: 'notice', level: 'info', text: 'Loopback host ready — everything you do is echoed into the video.' });
        break;
      case 'ping':
        this.sendCtrl({ t: 'pong', id: Number(m.id), ts: Number(m.ts) });
        break;
      case 'monitor':
        this.st.monitor = Math.max(0, Math.min(MONITORS.length - 1, Number(m.index)));
        this.sendCtrl({ t: 'monitors', list: MONITORS, current: this.st.monitor });
        this.logLine(`ctrl monitor → ${this.st.monitor}`);
        break;
      case 'privacy':
        this.st.privacy = !!m.on;
        this.sendCtrl({ t: 'privacy', on: this.st.privacy });
        this.logLine(`ctrl privacy → ${this.st.privacy ? 'ON' : 'off'}`);
        break;
      case 'clipboard':
        this.st.clipboard = String(m.text ?? '').slice(0, 120);
        this.logLine(`ctrl clipboard (${String(m.text ?? '').length} chars)`);
        break;
      case 'keyframe':
        this.logLine('ctrl keyframe request');
        break;
      case 'bitrate': {
        this.bitrateKbps = Number(m.kbps) || 0;
        this.logLine(`ctrl bitrate → ${this.bitrateKbps} kbps`);
        const sender = this.pc?.getSenders().find((x) => x.track?.kind === 'video');
        if (sender && this.bitrateKbps) {
          const p = sender.getParameters();
          if (p.encodings?.length) {
            p.encodings[0].maxBitrate = this.bitrateKbps * 1000;
            void sender.setParameters(p).catch(() => undefined);
          }
        }
        break;
      }
      default:
        break;
    }
  }

  private logLine(s: string): void {
    this.st.log.unshift(s);
    if (this.st.log.length > 8) this.st.log.length = 8;
  }

  private onInput(buf: ArrayBuffer): void {
    const ev = decodeInput(buf);
    if (!ev) return;
    const st = this.st;
    st.inputCount++;
    st.lastInputAt = performance.now();
    switch (ev.type) {
      case 'mouseRel':
        st.cx = Math.max(0, Math.min(W, st.cx + ev.dx * (W / MONITORS[st.monitor].width) * 1.5));
        st.cy = Math.max(0, Math.min(H, st.cy + ev.dy * (H / MONITORS[st.monitor].height) * 1.5));
        break;
      case 'mouseAbs':
        st.cx = (ev.x / 65535) * W;
        st.cy = (ev.y / 65535) * H;
        break;
      case 'mouseButton':
        if (ev.down) st.buttons.add(ev.button);
        else st.buttons.delete(ev.button);
        this.logLine(`btn ${['L', 'R', 'M', 'X1', 'X2'][ev.button] ?? ev.button} ${ev.down ? '↓' : '↑'}`);
        break;
      case 'wheel':
        st.wheel += ev.dy / 120;
        this.logLine(`wheel dx=${ev.dx} dy=${ev.dy}`);
        break;
      case 'key': {
        const id = `${ev.scan}:${ev.extended ? 1 : 0}`;
        const name = scanNames.get(id) ?? '?';
        if (ev.down) st.keys.set(id, name);
        else st.keys.delete(id);
        this.logLine(`Key { scan: 0x${ev.scan.toString(16).padStart(2, '0')}, down: ${ev.down}, extended: ${ev.extended} } ${name}`);
        break;
      }
      case 'unicode':
        if (ev.down) this.logLine(`Unicode U+${ev.codepoint.toString(16).toUpperCase()} '${String.fromCodePoint(ev.codepoint)}'`);
        break;
      case 'releaseAll':
        st.keys.clear();
        st.buttons.clear();
        this.logLine('release-all');
        break;
      case 'gamepad':
        if (ev.connected) st.pads.set(ev.index, ev);
        else st.pads.delete(ev.index);
        break;
    }
  }

  // ── renderer ─────────────────────────────────────────────────────────────
  private loop = (): void => {
    if (this.closed) return;
    this.draw();
    this.raf = requestAnimationFrame(this.loop);
  };

  private draw(): void {
    const g = this.ctx2d;
    const st = this.st;
    const t = (performance.now() - this.t0) / 1000;
    this.frame++;
    const hue = MONITOR_HUES[st.monitor];

    // Moving background (gives the encoder real work so bitrate/decode stats are meaningful).
    const grd = g.createLinearGradient(0, 0, W, H);
    grd.addColorStop(0, `hsl(${hue} 60% 10%)`);
    grd.addColorStop(1, `hsl(${(hue + 60) % 360} 55% 6%)`);
    g.fillStyle = grd;
    g.fillRect(0, 0, W, H);
    for (let i = 0; i < 14; i++) {
      const x = ((t * 140 + i * 110) % (W + 200)) - 100;
      g.fillStyle = `hsla(${(hue + i * 9) % 360} 80% 60% / 0.07)`;
      g.fillRect(x, 0, 46, H);
    }
    // Grid
    g.strokeStyle = 'rgba(255,255,255,0.05)';
    g.lineWidth = 1;
    for (let x = 0; x < W; x += 64) {
      g.beginPath();
      g.moveTo(x + 0.5, 0);
      g.lineTo(x + 0.5, H);
      g.stroke();
    }
    for (let y = 0; y < H; y += 64) {
      g.beginPath();
      g.moveTo(0, y + 0.5);
      g.lineTo(W, y + 0.5);
      g.stroke();
    }

    // Title + clocks
    g.fillStyle = '#e5f9ff';
    g.font = '600 30px ui-sans-serif, system-ui';
    g.fillText(this.carLabel ? `LeeStream 🚗 Car Cockpit Demo · ${this.carLabel}` : 'LeeStream Loopback Host', 40, 60);
    g.font = '15px ui-monospace, Menlo, monospace';
    g.fillStyle = 'rgba(229,249,255,0.7)';
    g.fillText(`${MONITORS[st.monitor].name}${this.bitrateKbps ? `   ${(this.bitrateKbps / 1000).toFixed(1)} Mbps` : ''}   frame ${this.frame}   t=${t.toFixed(2)}s   inputs ${st.inputCount}`, 40, 88);

    // Spinner (motion reference for judging smoothness)
    g.save();
    g.translate(W - 110, 90);
    g.rotate(t * Math.PI * 2 * 0.5);
    g.strokeStyle = `hsl(${hue} 90% 65%)`;
    g.lineWidth = 8;
    g.beginPath();
    g.arc(0, 0, 40, 0, Math.PI * 1.4);
    g.stroke();
    g.restore();

    // Held keys
    const panel = (x: number, y: number, w: number, h: number, title: string) => {
      g.fillStyle = 'rgba(5,6,10,0.55)';
      g.strokeStyle = 'rgba(255,255,255,0.08)';
      g.beginPath();
      g.roundRect(x, y, w, h, 14);
      g.fill();
      g.stroke();
      g.fillStyle = 'rgba(229,249,255,0.55)';
      g.font = '600 13px ui-sans-serif, system-ui';
      g.fillText(title.toUpperCase(), x + 16, y + 24);
    };
    panel(40, 120, 560, 120, 'Held keys (InputEvent::Key)');
    g.font = '600 18px ui-monospace, Menlo, monospace';
    let kx = 56;
    for (const [id, name] of st.keys) {
      const [scan, ext] = id.split(':').map(Number);
      const label = `${name} ${scanLabel({ scan, extended: ext === 1 })}`;
      const w = g.measureText(label).width + 20;
      if (kx + w > 590) break;
      g.fillStyle = `hsl(${hue} 85% 60%)`;
      g.beginPath();
      g.roundRect(kx, 150, w, 34, 8);
      g.fill();
      g.fillStyle = '#05060a';
      g.fillText(label, kx + 10, 174);
      kx += w + 8;
    }
    if (!st.keys.size) {
      g.fillStyle = 'rgba(229,249,255,0.35)';
      g.font = '16px ui-sans-serif, system-ui';
      g.fillText('Press keys — they appear here with their Set-1 scan code.', 56, 174);
    }
    // Mouse buttons + wheel
    g.font = '600 15px ui-monospace, Menlo, monospace';
    ['L', 'R', 'M', 'X1', 'X2'].forEach((b, i) => {
      g.fillStyle = st.buttons.has(i) ? '#22d3ee' : 'rgba(255,255,255,0.08)';
      g.beginPath();
      g.roundRect(56 + i * 52, 196, 44, 30, 6);
      g.fill();
      g.fillStyle = st.buttons.has(i) ? '#05060a' : 'rgba(229,249,255,0.6)';
      g.fillText(b, 68 + i * 52 - (b.length > 1 ? 5 : 0), 216);
    });
    g.fillStyle = 'rgba(229,249,255,0.7)';
    g.fillText(`wheel ${st.wheel.toFixed(2)} notches`, 330, 216);

    // Event log
    panel(40, 256, 560, 250, 'Host received (decoded)');
    g.font = '14px ui-monospace, Menlo, monospace';
    st.log.forEach((line, i) => {
      g.fillStyle = `rgba(229,249,255,${0.9 - i * 0.08})`;
      g.fillText(line.slice(0, 66), 56, 308 + i * 24);
    });

    // Gamepads
    panel(620, 120, 620, 250, 'Gamepads (20-byte reports)');
    if (!st.pads.size) {
      g.fillStyle = 'rgba(229,249,255,0.35)';
      g.font = '16px ui-sans-serif, system-ui';
      g.fillText('Connect a controller and press a button.', 640, 160);
    }
    let px = 640;
    for (const [idx, p] of st.pads) {
      this.drawPad(g, px, 140, idx, p);
      px += 300;
      if (px > 1000) break;
    }

    // Clipboard + privacy
    panel(620, 386, 620, 120, 'Host state');
    g.font = '15px ui-monospace, Menlo, monospace';
    g.fillStyle = 'rgba(229,249,255,0.85)';
    g.fillText(`Privacy screen: ${st.privacy ? 'ON (physical monitors blanked)' : 'off'}`, 640, 436);
    g.fillText(`Clipboard: ${st.clipboard ? JSON.stringify(st.clipboard).slice(0, 56) : '—'}`, 640, 462);
    const since = st.lastInputAt ? ((performance.now() - st.lastInputAt) / 1000).toFixed(1) + 's ago' : 'never';
    g.fillText(`Last input: ${since}`, 640, 488);

    // Footer hint
    g.fillStyle = 'rgba(229,249,255,0.4)';
    g.font = '14px ui-sans-serif, system-ui';
    g.fillText('Ctrl+Alt+Shift+M mouse mode · H HUD · F fullscreen · Z release · Q disconnect', 40, H - 28);

    // Remote cursor (what the host's desktop shows)
    g.save();
    g.translate(st.cx, st.cy);
    g.strokeStyle = st.buttons.size ? '#f472b6' : '#22d3ee';
    g.lineWidth = 2;
    g.beginPath();
    g.arc(0, 0, st.buttons.size ? 14 : 10, 0, Math.PI * 2);
    g.moveTo(-22, 0);
    g.lineTo(-6, 0);
    g.moveTo(6, 0);
    g.lineTo(22, 0);
    g.moveTo(0, -22);
    g.lineTo(0, -6);
    g.moveTo(0, 6);
    g.lineTo(0, 22);
    g.stroke();
    g.restore();
  }

  private drawPad(g: CanvasRenderingContext2D, x: number, y: number, idx: number, p: GamepadReport): void {
    g.fillStyle = 'rgba(229,249,255,0.8)';
    g.font = '600 14px ui-monospace, Menlo, monospace';
    g.fillText(`Pad ${idx}  seq ${p.seq}`, x, y + 24);
    const stickAt = (cx: number, cy: number, sx: number, sy: number) => {
      g.strokeStyle = 'rgba(255,255,255,0.25)';
      g.lineWidth = 2;
      g.beginPath();
      g.arc(cx, cy, 34, 0, Math.PI * 2);
      g.stroke();
      g.fillStyle = '#22d3ee';
      g.beginPath();
      g.arc(cx + (sx / 32767) * 28, cy - (sy / 32767) * 28, 9, 0, Math.PI * 2);
      g.fill();
    };
    stickAt(x + 50, y + 90, p.lx, p.ly);
    stickAt(x + 150, y + 90, p.rx, p.ry);
    const bar = (bx: number, v: number, label: string) => {
      g.fillStyle = 'rgba(255,255,255,0.1)';
      g.fillRect(bx, y + 150, 100, 12);
      g.fillStyle = '#a855f7';
      g.fillRect(bx, y + 150, (v / 255) * 100, 12);
      g.fillStyle = 'rgba(229,249,255,0.7)';
      g.font = '12px ui-monospace, Menlo, monospace';
      g.fillText(label, bx, y + 178);
    };
    bar(x, p.lt, `LT ${p.lt}`);
    bar(x + 110, p.rt, `RT ${p.rt}`);
    const names: Array<[number, string]> = [
      [XI.A, 'A'], [XI.B, 'B'], [XI.X, 'X'], [XI.Y, 'Y'], [XI.LEFT_SHOULDER, 'LB'], [XI.RIGHT_SHOULDER, 'RB'],
      [XI.BACK, 'BK'], [XI.START, 'ST'], [XI.DPAD_UP, '↑'], [XI.DPAD_DOWN, '↓'], [XI.DPAD_LEFT, '←'], [XI.DPAD_RIGHT, '→'],
      [XI.LEFT_THUMB, 'LS'], [XI.RIGHT_THUMB, 'RS'], [XI.GUIDE, 'G'],
    ];
    g.font = '600 11px ui-monospace, Menlo, monospace';
    names.forEach(([bit, n], i) => {
      const bx = x + (i % 8) * 32;
      const by = y + 192 + Math.floor(i / 8) * 26;
      const on = (p.buttons & bit) !== 0;
      g.fillStyle = on ? '#22d3ee' : 'rgba(255,255,255,0.08)';
      g.beginPath();
      g.roundRect(bx, by, 28, 20, 4);
      g.fill();
      g.fillStyle = on ? '#05060a' : 'rgba(229,249,255,0.6)';
      g.fillText(n, bx + 5, by + 14);
    });
  }
}
