import { useState, type ReactNode } from 'react';
import type { CarControl, CarPreset, DockLayout } from '../lib/car';
import type { MonitorInfo } from '../lib/protocol';
import type { PadInfo } from '../lib/gamepad';

export interface CarDockProps {
  layout: DockLayout;
  side: 'left' | 'right';
  preset: CarPreset;
  control: CarControl;
  onControl: (c: CarControl) => void;
  fullscreen: boolean;
  onFullscreen: () => void;
  teslaLink: string | null;
  monitors: MonitorInfo[];
  currentMonitor: number;
  onMonitor: (i: number) => void;
  privacy: boolean;
  onPrivacy: () => void;
  keyboard: boolean;
  onKeyboard: () => void;
  onPaste: () => void;
  hud: boolean;
  onHud: () => void;
  pads: PadInfo[];
  netLabel: string;
  kbps: number;
  touchLock: boolean;
  onTouchLock: () => void;
  showTouchLock: boolean;
  dragHeld: boolean;
  speedKmh: number | null;
  onDisconnect: () => void;
  hidden: boolean;
  onHidden: (h: boolean) => void;
}

/** Big-target cockpit dock: side rail on wide screens, top status + bottom dock on square/portrait screens (NIO, BYD vertical). */
export function CarDock(p: CarDockProps) {
  const hidden = p.hidden;
  const setHidden = p.onHidden;
  const [monMenu, setMonMenu] = useState(false);

  const buttons: ReactNode = (
    <>
      <DockBtn icon={p.fullscreen ? '🗗' : '⛶'} label={p.fullscreen ? '退出全屏' : '全屏'} aria="Fullscreen" onClick={p.onFullscreen} />
      {p.teslaLink && (
        <a className="car-dock-btn" href={p.teslaLink} aria-label="Tesla theater fullscreen">
          <span className="text-xl">🎦</span>
          <span className="lbl">剧场全屏</span>
        </a>
      )}
      <DockBtn icon="👆" label="直触" aria="Control direct" pressed={p.control === 'direct'} onClick={() => p.onControl('direct')} />
      <DockBtn icon="🖐️" label={p.dragHeld ? '拖拽锁定' : '触控板'} aria="Control trackpad" pressed={p.control === 'trackpad'} onClick={() => p.onControl('trackpad')} />
      <DockBtn icon="🎮" label="手柄" aria="Control gamepad" pressed={p.control === 'gamepad'} onClick={() => p.onControl('gamepad')} />
      <DockBtn icon="⌨️" label="键盘" aria="Keyboard" pressed={p.keyboard} onClick={p.onKeyboard} />
      <DockBtn
        icon="🖥️"
        label={`屏幕 ${p.currentMonitor + 1}`}
        aria="Switch monitor"
        pressed={monMenu}
        onClick={() => (p.monitors.length > 1 ? setMonMenu((m) => !m) : p.onMonitor(p.currentMonitor + 1))}
      />
      <DockBtn icon="🙈" label="隐私" aria="Privacy screen" pressed={p.privacy} onClick={p.onPrivacy} />
      <DockBtn icon="📋" label="粘贴" aria="Paste clipboard to host" onClick={p.onPaste} />
      <DockBtn icon="📊" label="HUD" aria="Stats HUD" pressed={p.hud} onClick={p.onHud} />
      {p.showTouchLock && <DockBtn icon={p.touchLock ? '🔒' : '🔓'} label="观影锁" aria="Passenger cinema touch lock" pressed={p.touchLock} onClick={p.onTouchLock} />}
      <DockBtn icon="⏏" label="断开" aria="Disconnect" danger onClick={p.onDisconnect} />
    </>
  );

  const status = (
    <div className="flex flex-wrap items-center gap-1.5 text-sm" data-testid="car-status">
      <Chip color={p.preset.accent}>
        {p.preset.emoji} {p.preset.nameEn}
      </Chip>
      <Chip>
        📶 {p.netLabel} · {(p.kbps / 1000).toFixed(1)}M
      </Chip>
      {p.pads.map((pad) => (
        <Chip key={pad.slot} color="#22c55e">
          🎮 P{pad.slot + 1} {shortPad(pad.id)}
        </Chip>
      ))}
      {p.speedKmh !== null && <Chip>🚗 {p.speedKmh.toFixed(0)} km/h</Chip>}
    </div>
  );

  const monitorMenu = monMenu && (
    <div className="car-glass absolute z-30 min-w-72 rounded-2xl p-2" style={p.layout === 'rail' ? { [p.side === 'left' ? 'left' : 'right']: '100%', top: 0, marginInline: 8 } : { bottom: '100%', left: '50%', transform: 'translateX(-50%)', marginBottom: 8 }}>
      {p.monitors.map((m) => (
        <button
          key={m.index}
          onClick={() => {
            p.onMonitor(m.index);
            setMonMenu(false);
          }}
          className={`car-btn flex w-full items-center rounded-xl px-4 text-left text-lg ${m.index === p.currentMonitor ? 'text-cyan-300' : 'text-slate-100'} hover:bg-white/10`}
        >
          {m.index + 1}. {m.name}
        </button>
      ))}
    </div>
  );

  if (hidden) {
    return (
      <button
        onClick={() => setHidden(false)}
        className="car-glass pointer-events-auto absolute z-20 rounded-2xl px-5 text-base font-semibold text-white car-btn"
        style={p.layout === 'rail' ? { top: 12, [p.side]: 12 } : { bottom: 12, left: '50%', transform: 'translateX(-50%)' }}
        aria-label="Show dock"
      >
        ☰ LeeStream
      </button>
    );
  }

  if (p.layout === 'rail') {
    return (
      <div
        className="car-glass pointer-events-auto absolute top-0 bottom-0 z-20 flex w-[92px] flex-col items-center gap-2 overflow-y-auto py-3"
        style={{ [p.side]: 0, paddingTop: 'max(12px, env(safe-area-inset-top))' }}
        data-testid="car-dock"
        data-layout="rail"
      >
        <div className="relative flex flex-col items-center gap-2">
          {buttons}
          {monitorMenu}
        </div>
        <DockBtn icon={p.side === 'left' ? '◀' : '▶'} label="收起" aria="Hide dock" onClick={() => setHidden(true)} />
      </div>
    );
  }

  return (
    <>
      <div className="car-glass pointer-events-auto absolute inset-x-0 top-0 z-20 flex h-16 items-center px-3" style={{ paddingTop: 'env(safe-area-inset-top)' }} data-testid="car-topbar">
        {status}
      </div>
      <div className="car-glass pointer-events-auto absolute inset-x-0 bottom-0 z-20 flex h-24 items-center gap-2 overflow-x-auto px-3" data-testid="car-dock" data-layout="stack">
        <div className="relative mx-auto flex gap-2">
          {buttons}
          {monitorMenu}
          <DockBtn icon="▼" label="收起" aria="Hide dock" onClick={() => setHidden(true)} />
        </div>
      </div>
    </>
  );
}

export function CarStatusFloat(p: Pick<CarDockProps, 'preset' | 'pads' | 'netLabel' | 'kbps' | 'speedKmh' | 'side'>) {
  return (
    <div className="pointer-events-none absolute top-3 z-10 flex flex-wrap justify-end gap-1.5 text-sm" style={{ [p.side === 'left' ? 'right' : 'left']: 12 }} data-testid="car-status">
      <Chip color={p.preset.accent}>
        {p.preset.emoji} {p.preset.nameEn}
      </Chip>
      <Chip>
        📶 {p.netLabel} · {(p.kbps / 1000).toFixed(1)}M
      </Chip>
      {p.pads.map((pad) => (
        <Chip key={pad.slot} color="#22c55e">
          🎮 P{pad.slot + 1} {shortPad(pad.id)}
        </Chip>
      ))}
      {p.speedKmh !== null && <Chip>🚗 {p.speedKmh.toFixed(0)} km/h</Chip>}
    </div>
  );
}

function shortPad(id: string): string {
  if (/xbox|xinput|045e/i.test(id)) return 'Xbox';
  if (/dualsense|0ce6|dualshock|054c|playstation/i.test(id)) return 'PS';
  if (/pro controller|057e|switch|joy-?con/i.test(id)) return 'Switch';
  return id.split('(')[0].trim().slice(0, 12) || 'Pad';
}

function Chip({ children, color }: { children: ReactNode; color?: string }) {
  return (
    <span className="car-glass whitespace-nowrap rounded-full px-3 py-1 font-medium text-slate-100" style={color ? { borderColor: `${color}88` } : undefined}>
      {children}
    </span>
  );
}

function DockBtn({ icon, label, aria, onClick, pressed, danger }: { icon: string; label: string; aria: string; onClick: () => void; pressed?: boolean; danger?: boolean }) {
  return (
    <button
      className={`car-dock-btn ${danger ? 'danger' : ''}`}
      aria-label={aria}
      aria-pressed={pressed === undefined ? undefined : pressed}
      onClick={onClick}
      onPointerDown={(e) => e.stopPropagation()}
    >
      <span className="text-xl leading-none">{icon}</span>
      <span className="lbl">{label}</span>
    </button>
  );
}
