/**
 * Auto-reconnect policy for transient WebRTC loss (4G cell handover, TURN blip).
 *
 * A session that was streaming and then goes `failed` (or stays `disconnected` for DISCONNECT_GIVEUP_MS)
 * is rebuilt over the same signaling URL with the pairing secret: the Direct secret the user typed, or the
 * device secret the bridge handed back in `paired.resume` after a one-time 6-digit code pairing.
 * The host keeps the old session for 30 s (SESSION_GRACE), so a quick rebuild takes over cleanly.
 */
export const RECONNECT_DELAYS_MS = [1000, 2000, 4000, 8000, 15000] as const;
/** A session that stayed connected at least this long starts the attempt counter from zero again. */
export const STABLE_MS = 20_000;
/** A reconnect attempt that has not connected within this long is abandoned for the next one. */
export const RECONNECT_ATTEMPT_TIMEOUT_MS = 15_000;
/** `disconnected` for longer than this: stop waiting for ICE to heal and rebuild the session. */
export const DISCONNECT_GIVEUP_MS = 10_000;

/** Delay before reconnect attempt `attempt` (0-based), or null once the attempts are used up. */
export function reconnectDelay(attempt: number): number | null {
  return attempt >= 0 && attempt < RECONNECT_DELAYS_MS.length ? RECONNECT_DELAYS_MS[attempt] : null;
}

/** Attempt index for the next reconnect after a session that was up for `upMs`. */
export function nextAttempt(prevAttempt: number, upMs: number): number {
  return upMs >= STABLE_MS ? 0 : prevAttempt;
}

/** The credential to reconnect with: the typed Direct secret, else the bridge's resume secret. 64 hex only. */
export function resumeCredential(typed?: string, resume?: string): string | undefined {
  for (const s of [typed, resume]) {
    const t = (s ?? '').trim();
    if (/^[0-9a-fA-F]{64}$/.test(t)) return t;
  }
  return undefined;
}

/**
 * A session that was preempted (another native / web client took over the host: binary ctrl::BYE `[0x05]`,
 * ctrl `{"t":"bye"}` or signaling `bye`) must never be auto-rebuilt, or the two clients steal the host from
 * each other forever. The user reconnects explicitly from the connect screen instead.
 */
export function retryBlocked(from: { preempted?: boolean } | null | undefined): boolean {
  return from?.preempted === true;
}
