import { DISCONNECT_GIVEUP_MS } from './reconnect';
import {
  CLIENT_CAPS,
  CLIENT_VERSION,
  encodeReleaseAll,
  isBinaryCtrlBye,
  parseCtrl,
  decodeCursor,
  type CtrlIn,
  type CtrlOut,
  type CursorMsg,
} from './protocol';
import type { Offerer, SigMsg, SignalTransport } from './signaling';
import { codecMismatchMessage, isVideoRejected } from './sdpcodec';

export type SessionState = 'idle' | 'signaling' | 'pairing' | 'connecting' | 'connected' | 'reconnecting' | 'failed' | 'closed';
export type CodecPref = 'auto' | 'h264' | 'hevc' | 'av1';

export interface SessionOptions {
  transport: SignalTransport;
  code?: string;
  secret?: string;
  /** v1.2 cloud rendezvous: permanent Device ID and (first time only) the host's fixed access password. */
  device?: string;
  password?: string;
  offerer: Offerer;
  iceServers: RTCIceServer[];
  codec: CodecPref;
  clientName: string;
  /** Only offer/accept the preferred codec (car presets: H.264 only so a missing HEVC licence never black-screens). */
  strictCodec?: boolean;
  /** Receiver jitter-buffer target in ms (0 = render ASAP; cellular presets use a cushion). */
  jitterTargetMs?: number;
  /** Initial encoder bitrate request sent on ctrl open (kbps). */
  startKbps?: number;
  /** Extra fields merged into `want.client` (e.g. car profile). */
  clientExtra?: Record<string, unknown>;
  /** Car Cockpit profile echoed in ctrl `hello.car`. */
  car?: NonNullable<Extract<CtrlOut, { t: 'hello' }>['car']>;
  /** After media flowed, report a dead link as `lost` (and stay `reconnecting`) instead of `failed`. */
  autoReconnect?: boolean;
}

export interface SessionEvents {
  state: (s: SessionState, detail?: string) => void;
  stream: (s: MediaStream) => void;
  ctrl: (m: CtrlIn) => void;
  cursor: (m: CursorMsg) => void;
  audio: (packet: ArrayBuffer) => void;
  inputRtt: (ms: number) => void;
  /** Streaming session died (ICE failed / stuck disconnected); the app rebuilds it. Only with `autoReconnect`. */
  lost: (detail: string) => void;
}

type Listener<K extends keyof SessionEvents> = SessionEvents[K];

const CHANNELS = ['input', 'cursor', 'ctrl', 'audio'] as const;
type ChannelName = (typeof CHANNELS)[number];

/** Drop mouse-move traffic when the SCTP queue backs up instead of building latency. */
const INPUT_HIGH_WATER = 64 * 1024;

export function supportedVideoCodecs(): string[] {
  const caps = typeof RTCRtpReceiver !== 'undefined' && RTCRtpReceiver.getCapabilities?.('video');
  if (!caps) return [];
  return Array.from(new Set(caps.codecs.map((c) => c.mimeType.replace('video/', '')).filter((m) => !/rtx|red|ulpfec|flexfec/i.test(m))));
}

export class LeeStreamSession {
  readonly pc: RTCPeerConnection;
  private opts: SessionOptions;
  private channels = new Map<ChannelName, RTCDataChannel>();
  private listeners = new Map<keyof SessionEvents, Set<(...a: never[]) => void>>();
  private pendingIce: RTCIceCandidateInit[] = [];
  /** Bridge + host trickle ICE (paired.trickle): send the answer at once, candidates follow as `ice`. */
  private hostTrickle = false;
  private remoteSet = false;
  private stream = new MediaStream();
  private pingTimer = 0;
  private pingId = 0;
  private pings = new Map<number, number>();
  private _state: SessionState = 'idle';
  private disposed = false;
  private connectedAt = 0;
  private discTimer = 0;
  private lostOnce = false;
  /** Another client (native or second web client) took over the host. Never auto-reconnect from here. */
  preempted = false;
  hostName = '';
  /** Device secret from `paired.resume` (6-digit pairing via the bridge). Memory only, never persisted. */
  resumeSecret?: string;

  constructor(opts: SessionOptions) {
    this.opts = opts;
    this.pc = new RTCPeerConnection({
      iceServers: opts.iceServers,
      bundlePolicy: 'max-bundle',
      rtcpMuxPolicy: 'require',
    });
    this.wirePeer();
    opts.transport.onmessage = (m) => void this.onSignal(m);
    opts.transport.onclose = (reason) => {
      if (this.preempted) return; // we closed it ourselves after being taken over
      // Once media is flowing the signaling socket is no longer needed; only fail if we never connected.
      if (this._state !== 'connected' && this._state !== 'closed') this.setState('failed', `Signaling closed: ${reason}`);
    };
  }

  get state(): SessionState {
    return this._state;
  }

  on<K extends keyof SessionEvents>(ev: K, fn: Listener<K>): () => void {
    let set = this.listeners.get(ev);
    if (!set) this.listeners.set(ev, (set = new Set()));
    const f = fn as unknown as (...a: never[]) => void;
    set.add(f);
    return () => set.delete(f);
  }

  private emit<K extends keyof SessionEvents>(ev: K, ...args: Parameters<SessionEvents[K]>): void {
    const set = this.listeners.get(ev) as Set<(...a: Parameters<SessionEvents[K]>) => void> | undefined;
    set?.forEach((fn) => fn(...args));
  }

  private setState(s: SessionState, detail?: string): void {
    if ((this.disposed || this.preempted) && s !== 'closed') return;
    this._state = s;
    this.emit('state', s, detail);
  }

  /** How long this session has been streaming (0 = never connected). */
  get upMs(): number {
    return this.connectedAt ? Date.now() - this.connectedAt : 0;
  }

  private lose(detail: string): void {
    if (this.preempted || this.lostOnce || this.disposed) return;
    this.lostOnce = true;
    this.setState('reconnecting', `Connection dropped (${detail}) — reconnecting…`);
    this.emit('lost', detail);
  }

  /**
   * The host handed the session to another client (binary ctrl::BYE `[0x05]`, ctrl JSON `bye`, or signaling `bye`).
   * Tear down quietly and end in `closed` so the app returns to the connect screen instead of fighting back.
   * Idempotent: the host usually sends more than one of these signals.
   */
  private handlePreempted(reason = 'Connected from another device'): void {
    if (this.preempted) return;
    this.preempted = true;
    this.lostOnce = true;
    clearTimeout(this.discTimer);
    clearInterval(this.pingTimer);
    this.discTimer = 0;
    this.pingTimer = 0;
    try { this.opts.transport.close(); } catch { /* already gone */ }
    this.channels.forEach((c) => {
      try { c.close(); } catch { /* already closed */ }
    });
    try { this.pc.close(); } catch { /* already closed */ }
    this.disposed = true; // close() becomes a no-op: nothing left to tell the host
    this.setState('closed', reason);
  }

  /** App-driven status while a rebuild is pending. */
  markReconnecting(detail: string): void {
    this.setState('reconnecting', detail);
  }

  /** App gave up reconnecting (no credential / attempts used up). */
  fail(detail: string): void {
    this.setState('failed', detail);
  }

  async start(): Promise<void> {
    this.setState('signaling');
    await this.opts.transport.ready;
    this.setState('pairing');
    this.opts.transport.send({
      type: 'want',
      code: this.opts.code,
      secret: this.opts.secret,
      ...(this.opts.device ? { device: this.opts.device } : {}),
      ...(this.opts.password ? { password: this.opts.password } : {}),
      offerer: this.opts.offerer,
      trickle: true,
      client: {
        name: this.opts.clientName,
        ua: navigator.userAgent,
        codecs: this.advertisedCodecs(),
        version: CLIENT_VERSION,
        ...(this.opts.clientExtra ?? {}),
      },
    });
    if (this.opts.offerer === 'client') await this.makeOffer();
  }

  // ── peer wiring ──────────────────────────────────────────────────────────
  private wirePeer(): void {
    const pc = this.pc;
    pc.onicecandidate = (ev) => {
      const c = ev.candidate;
      this.opts.transport.send(
        c
          ? { type: 'ice', candidate: c.candidate, sdpMid: c.sdpMid, sdpMLineIndex: c.sdpMLineIndex, usernameFragment: c.usernameFragment }
          : { type: 'ice', candidate: null },
      );
    };
    pc.onconnectionstatechange = () => {
      // Taken over by another client: the dying peer is expected, never report it as lost/failed.
      if (this.preempted) return;
      switch (pc.connectionState) {
        case 'connecting':
          this.setState('connecting');
          break;
        case 'connected':
          clearTimeout(this.discTimer);
          if (!this.connectedAt) this.connectedAt = Date.now();
          this.setState('connected');
          break;
        case 'disconnected':
          this.setState('reconnecting', 'Network hiccup — trying to recover');
          clearTimeout(this.discTimer);
          if (this.opts.autoReconnect && this.connectedAt) {
            this.discTimer = window.setTimeout(() => {
              if (!this.preempted && this.pc.connectionState === 'disconnected') this.lose(`no packets for ${DISCONNECT_GIVEUP_MS / 1000} s`);
            }, DISCONNECT_GIVEUP_MS);
          }
          break;
        case 'failed':
          clearTimeout(this.discTimer);
          if (this.opts.autoReconnect && this.connectedAt) {
            this.lose('ICE failed (no route to host)');
            break;
          }
          this.setState('failed', 'ICE failed (no route to host). Check TURN / firewall.');
          void this.tryIceRestart();
          break;
        case 'closed':
          this.setState('closed');
          break;
      }
    };
    pc.ontrack = (ev) => {
      this.tuneReceiver(ev.receiver);
      if (!this.stream.getTracks().includes(ev.track)) this.stream.addTrack(ev.track);
      this.emit('stream', this.stream);
    };
    pc.ondatachannel = (ev) => this.adoptChannel(ev.channel);
  }

  /** Ask the browser to render frames the moment they decode. */
  private tuneReceiver(r: RTCRtpReceiver): void {
    const rr = r as RTCRtpReceiver & { jitterBufferTarget?: number | null; playoutDelayHint?: number };
    try {
      if ('jitterBufferTarget' in rr) rr.jitterBufferTarget = this.opts.jitterTargetMs ?? 0; // Chrome 114+/Safari 18 (ms)
    } catch {
      /* not supported */
    }
    try {
      rr.playoutDelayHint = (this.opts.jitterTargetMs ?? 0) / 1000; // legacy Chrome (seconds)
    } catch {
      /* not supported */
    }
  }

  private adoptChannel(ch: RTCDataChannel): void {
    const name = ch.label as ChannelName;
    if (!CHANNELS.includes(name)) return;
    ch.binaryType = 'arraybuffer';
    this.channels.set(name, ch);
    ch.onmessage = (ev) => this.onChannelMessage(name, ev.data);
    const onOpen = () => {
      if (name === 'ctrl') {
        this.sendCtrl({
          t: 'hello',
          client: 'web',
          version: CLIENT_VERSION,
          caps: CLIENT_CAPS,
          viewport: { w: screen.width, h: screen.height, dpr: devicePixelRatio || 1 },
          ...(this.opts.car ? { car: this.opts.car } : {}),
        });
        if (this.opts.startKbps) this.sendCtrl({ t: 'bitrate', kbps: this.opts.startKbps });
        this.startPings();
      }
    };
    if (ch.readyState === 'open') onOpen();
    else ch.addEventListener('open', onOpen, { once: true });
  }

  private onChannelMessage(name: ChannelName, data: unknown): void {
    switch (name) {
      case 'ctrl': {
        if (typeof data !== 'string') {
          // Native host ctrl::BYE: a single binary 0x05 — another client took over.
          if (isBinaryCtrlBye(data)) this.handlePreempted();
          return;
        }
        const m = parseCtrl(data);
        if (!m) return;
        if (m.t === 'bye') {
          this.emit('ctrl', m);
          this.handlePreempted(m.reason ?? 'Connected from another device');
          return;
        }
        if (m.t === 'pong') {
          const sent = this.pings.get(m.id);
          if (sent !== undefined) {
            this.pings.delete(m.id);
            this.emit('inputRtt', performance.now() - sent);
          }
          return;
        }
        if (m.t === 'welcome') this.hostName = m.host;
        this.emit('ctrl', m);
        return;
      }
      case 'cursor': {
        if (!(data instanceof ArrayBuffer)) return;
        const m = decodeCursor(data);
        if (m) this.emit('cursor', m);
        return;
      }
      case 'audio':
        if (data instanceof ArrayBuffer) this.emit('audio', data);
        return;
      case 'input':
        return; // host never sends on input
    }
  }

  private startPings(): void {
    clearInterval(this.pingTimer);
    this.pingTimer = window.setInterval(() => {
      const id = ++this.pingId;
      const ts = performance.now();
      this.pings.set(id, ts);
      if (this.pings.size > 10) this.pings.delete(this.pings.keys().next().value as number);
      this.sendCtrl({ t: 'ping', id, ts });
    }, 1000);
  }

  // ── signaling ────────────────────────────────────────────────────────────
  private async onSignal(m: SigMsg): Promise<void> {
    try {
      switch (m.type) {
        case 'paired':
          this.hostName = m.host;
          this.hostTrickle = m.trickle === true;
          if (typeof m.resume === 'string' && m.resume) this.resumeSecret = m.resume;
          // Host STUN/TURN (host.json turn/turn_user/turn_pass) arrive here, before the offer. ICE gathering only
          // starts at setLocalDescription(answer), so relay candidates are gathered against these servers.
          if (m.iceServers?.length) {
            try {
              this.pc.setConfiguration({ ...this.pc.getConfiguration(), iceServers: [...this.opts.iceServers, ...m.iceServers] });
            } catch (e) {
              console.warn('[leestream] host iceServers rejected:', (e as Error).message);
            }
          }
          this.setState('connecting', `Paired with ${m.host}`);
          break;
        case 'offer':
          await this.pc.setRemoteDescription({ type: 'offer', sdp: m.sdp });
          await this.flushIce();
          this.applyCodecPreferences();
          const answer = await this.pc.createAnswer();
          // Every offered video codec unusable (e.g. H.264 High only on Linux/Tesla Chromium): Chrome would reject
          // m=video and then fail setLocalDescription with "Failed to setup RTCP mux". Name the real problem instead.
          if (isVideoRejected(answer.sdp ?? '')) {
            const caps = RTCRtpReceiver.getCapabilities?.('video')?.codecs ?? [];
            const why = codecMismatchMessage(m.sdp, caps);
            console.error('[leestream]', why);
            try { this.opts.transport.send({ type: 'bye', reason: 'no common video codec' }); } catch { /* signaling already gone */ }
            this.setState('failed', why);
            return;
          }
          await this.pc.setLocalDescription(answer);
          // Old bridge/host: no candidates after the answer, so pack them into the SDP (≤2.2 s).
          // Trickle: answer immediately; onicecandidate streams host/srflx/relay as they appear (4G / strict NAT).
          if (!this.hostTrickle) await this.waitForIceGathering(2200);
          this.opts.transport.send({ type: 'answer', sdp: this.pc.localDescription!.sdp });
          break;
        case 'answer':
          await this.pc.setRemoteDescription({ type: 'answer', sdp: m.sdp });
          await this.flushIce();
          break;
        case 'ice': {
          const init: RTCIceCandidateInit = m.candidate
            ? { candidate: m.candidate, sdpMid: m.sdpMid ?? undefined, sdpMLineIndex: m.sdpMLineIndex ?? undefined, usernameFragment: m.usernameFragment ?? undefined }
            : { candidate: '' }; // end-of-candidates
          if (!this.remoteSet) this.pendingIce.push(init);
          else await this.pc.addIceCandidate(init).catch(() => undefined);
          break;
        }
        case 'error':
          // Media already flows peer-to-peer: a late signaling error (e.g. the cloud tunnel restarting) is not fatal.
          if (this.connectedAt) {
            console.warn('[leestream] signaling error after connect (ignored):', m.code, m.message);
            break;
          }
          this.setState('failed', humanSigError(m.code, m.message));
          break;
        case 'bye':
          this.handlePreempted(m.reason ?? 'Host ended the session');
          break;
        case 'want':
          break;
      }
    } catch (e) {
      this.setState('failed', `Negotiation error: ${(e as Error).message}`);
    }
  }

  /**
   * Older ws-sig-bridge / ls-host builds do not trickle ICE candidates after Offer/Answer, so wait briefly for
   * host/srflx/relay candidates to land inside localDescription.sdp before transmitting it.
   */
  private async waitForIceGathering(timeoutMs: number): Promise<void> {
    if (this.pc.iceGatheringState === 'complete') return;
    await new Promise<void>((resolve) => {
      let done = false;
      let timer = 0;
      const finish = () => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        this.pc.removeEventListener('icegatheringstatechange', onState);
        this.pc.removeEventListener('icecandidate', onCand);
        resolve();
      };
      const onState = () => {
        if (this.pc.iceGatheringState === 'complete') finish();
      };
      const onCand = (ev: RTCPeerConnectionIceEvent) => {
        if (!ev.candidate) {
          finish();
        } else if (ev.candidate.type === 'srflx' || ev.candidate.type === 'relay') {
          // Give parallel STUN/TURN sockets a short window, then proceed without waiting 5s on an unreachable server.
          clearTimeout(timer);
          timer = window.setTimeout(finish, 400);
        }
      };
      timer = window.setTimeout(finish, timeoutMs);
      this.pc.addEventListener('icegatheringstatechange', onState);
      this.pc.addEventListener('icecandidate', onCand);
    });
  }

  private async flushIce(): Promise<void> {
    this.remoteSet = true;
    const q = this.pendingIce.splice(0);
    for (const c of q) await this.pc.addIceCandidate(c).catch(() => undefined);
  }

  /** Client-offers mode: we create the channels and recv-only media sections. */
  private async makeOffer(): Promise<void> {
    const pc = this.pc;
    // input: reliable + ordered so key-ups are never lost; moves are tiny and dropped client-side under backpressure.
    this.adoptChannel(pc.createDataChannel('input', { ordered: true }));
    this.adoptChannel(pc.createDataChannel('ctrl', { ordered: true }));
    this.adoptChannel(pc.createDataChannel('cursor', { ordered: false, maxRetransmits: 2 }));
    this.adoptChannel(pc.createDataChannel('audio', { ordered: false, maxRetransmits: 0 }));
    pc.addTransceiver('video', { direction: 'recvonly' });
    pc.addTransceiver('audio', { direction: 'recvonly' });
    this.applyCodecPreferences();
    await pc.setLocalDescription(await pc.createOffer());
    await this.waitForIceGathering(2200);
    this.opts.transport.send({ type: 'offer', sdp: pc.localDescription!.sdp });
  }

  private applyCodecPreferences(): void {
    const caps = RTCRtpReceiver.getCapabilities?.('video');
    if (!caps) return;
    const want = this.opts.codec;
    const rank = (mime: string): number => {
      const m = mime.toLowerCase();
      const order: Record<CodecPref, string[]> = {
        auto: ['video/h265', 'video/h264', 'video/av1', 'video/vp9', 'video/vp8'],
        hevc: ['video/h265', 'video/h264'],
        h264: ['video/h264', 'video/h265'],
        av1: ['video/av1', 'video/h265', 'video/h264'],
      };
      const i = order[want].indexOf(m);
      return i === -1 ? 50 : i;
    };
    let sorted = [...caps.codecs].sort((a, b) => rank(a.mimeType) - rank(b.mimeType));
    if (this.opts.strictCodec && want !== 'auto') {
      const only = sorted.filter((c) => rank(c.mimeType) === 0 || /rtx|red|ulpfec|flexfec/i.test(c.mimeType));
      if (only.some((c) => rank(c.mimeType) === 0)) sorted = only;
    }
    for (const t of this.pc.getTransceivers()) {
      if (t.receiver.track?.kind !== 'video' || t.currentDirection === 'stopped') continue;
      try {
        t.setCodecPreferences(sorted);
      } catch {
        /* some browsers reject reordering when the offer lacks a codec */
      }
    }
  }

  /** Codec list sent in `want` — ordered by preference, filtered when strict. */
  private advertisedCodecs(): string[] {
    const all = supportedVideoCodecs();
    const map: Record<CodecPref, string> = { auto: '', h264: 'H264', hevc: 'H265', av1: 'AV1' };
    const want = map[this.opts.codec];
    if (!want || !all.includes(want)) return all;
    return this.opts.strictCodec ? [want] : [want, ...all.filter((c) => c !== want)];
  }

  /** Change the receiver cushion live (network preset switch without renegotiation). */
  setJitterTarget(ms: number): void {
    this.opts.jitterTargetMs = ms;
    for (const r of this.pc.getReceivers()) if (r.track.kind === 'video') this.tuneReceiver(r);
  }

  private async tryIceRestart(): Promise<void> {
    if (this.opts.offerer !== 'client' || this.disposed) return;
    try {
      this.pc.restartIce();
      await this.pc.setLocalDescription(await this.pc.createOffer({ iceRestart: true }));
      this.opts.transport.send({ type: 'offer', sdp: this.pc.localDescription!.sdp });
    } catch {
      /* give up; UI shows failed */
    }
  }

  // ── outbound ─────────────────────────────────────────────────────────────
  /** Returns false when dropped. `droppable` events (moves) are skipped under backpressure. */
  sendInput(bytes: Uint8Array, droppable = false): boolean {
    const ch = this.channels.get('input');
    if (!ch || ch.readyState !== 'open') return false;
    if (droppable && ch.bufferedAmount > INPUT_HIGH_WATER) return false;
    ch.send(bytes as Uint8Array<ArrayBuffer>);
    return true;
  }

  sendCtrl(msg: CtrlOut): void {
    const ch = this.channels.get('ctrl');
    if (ch?.readyState === 'open') ch.send(JSON.stringify(msg));
  }

  inputOpen(): boolean {
    return this.channels.get('input')?.readyState === 'open';
  }

  getStream(): MediaStream {
    return this.stream;
  }

  close(): void {
    if (this.disposed) return;
    this.sendInput(encodeReleaseAll());
    this.sendCtrl({ t: 'bye' });
    this.disposed = true;
    clearInterval(this.pingTimer);
    clearTimeout(this.discTimer);
    this.opts.transport.close();
    this.channels.forEach((c) => c.close());
    this.pc.close();
    this._state = 'closed';
    this.emit('state', 'closed');
  }
}

function humanSigError(code: string, message: string): string {
  switch (code) {
    case 'bad_code':
      return 'That pairing code is wrong or expired. Generate a new one on the host.';
    case 'host_offline':
      return message || 'The host is offline or not registered with the rendezvous server.';
    case 'timeout':
      return 'The host did not answer in time.';
    case 'rate_limited':
      return 'Too many attempts — wait a minute and try again.';
    case 'bad_password':
      return 'Wrong access password for that Device ID.';
    case 'no_password':
      return 'That PC has no access password set. Use a one-time 6-digit code, or set a password on the host.';
    case 'too_many_attempts':
      return 'Too many wrong passwords — the PC is locked for a minute.';
    case 'id_taken':
      return 'That Device ID belongs to another PC.';
    default:
      return message || code;
  }
}
