// Vendored from leestream-touch (2026-11-26 package, src/touch.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// DOM binding: pointer/touch events on the stage → GestureEngine → LeeStream input + zoom viewport.
import { type Action, type GestureConfig, GestureEngine, type Mode } from './gestures';
import { Mapper, Viewport, containRect } from './geometry';
import { ABS_MAX, type InputSink, WHEEL_NOTCH, ev } from './protocol';

export interface TouchOptions {
  mode?: Mode;
  gesture?: Partial<GestureConfig>;
  /** Wheel units (1/120 notch) per CSS pixel of two-finger travel. */
  wheelGain?: number;
  /** Natural (content follows fingers) scrolling. Default true. */
  naturalScroll?: boolean;
  onThreeFingerTap?: () => void;
  /** Called after every click so sticky modifiers can be consumed. */
  onPointerAction?: () => void;
  onModeChange?: (m: Mode) => void;
  onZoom?: (scale: number) => void;
  /** Handle mouse/pen pointers too (default: touch only; desktop mice stay with lsinput.js). */
  allPointers?: boolean;
}

export class TouchController {
  readonly engine: GestureEngine;
  readonly viewport = new Viewport(1, 5);
  readonly mapper: Mapper;
  /** Remote cursor, normalised 0..1. */
  cursor: [number, number] = [0.5, 0.5];
  private cursorEl: HTMLDivElement;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private wheelAcc: [number, number] = [0, 0];
  private L: (() => void)[] = [];
  private ro: ResizeObserver | null = null;
  private o: Required<Pick<TouchOptions, 'wheelGain' | 'naturalScroll'>> & TouchOptions;

  constructor(private stage: HTMLElement, private video: HTMLVideoElement, private sink: InputSink, o: TouchOptions = {}) {
    this.o = { wheelGain: 2.4, naturalScroll: true, ...o };
    this.engine = new GestureEngine((a) => this.act(a), o.mode ?? 'direct', o.gesture);
    // The video's own layout box (offset* ignore CSS transforms), so a keyboard that shrinks the video is honoured.
    this.mapper = new Mapper(this.viewport, () => containRect({ x: video.offsetLeft, y: video.offsetTop, w: video.offsetWidth || this.viewport.w, h: video.offsetHeight || this.viewport.h }, video.videoWidth, video.videoHeight));

    stage.classList.add('lst-stage');
    video.classList.add('lst-video');
    this.cursorEl = document.createElement('div');
    this.cursorEl.className = 'lst-cursor';
    this.cursorEl.setAttribute('aria-hidden', 'true');
    stage.appendChild(this.cursorEl);

    const on = <K extends keyof HTMLElementEventMap>(t: EventTarget, n: K | string, f: (e: Event) => void, opt?: AddEventListenerOptions) => {
      t.addEventListener(n, f, opt);
      this.L.push(() => t.removeEventListener(n, f, opt));
    };
    const pt = (e: PointerEvent): [number, number] => {
      const r = stage.getBoundingClientRect();
      return [e.clientX - r.left, e.clientY - r.top];
    };
    // Event timestamps are not reliable across engines (synthetic events, older WebKit epoch
    // stamps); fall back to performance.now() whenever a stamp is not on that clock.
    const ts = (e: Event) => { const n = performance.now(); return e.timeStamp && Math.abs(e.timeStamp - n) < 1000 ? e.timeStamp : n; };
    const mine = (e: PointerEvent) => this.o.allPointers || e.pointerType === 'touch' || e.pointerType === 'pen';

    on(stage, 'pointerdown', (e) => {
      const p = e as PointerEvent;
      if (!mine(p)) return;
      p.preventDefault();
      try { stage.setPointerCapture(p.pointerId); } catch { /* synthetic */ }
      const [x, y] = pt(p);
      this.engine.down(p.pointerId, x, y, ts(p));
      this.schedule();
    }, { passive: false });
    on(stage, 'pointermove', (e) => {
      const p = e as PointerEvent;
      if (!mine(p)) return;
      p.preventDefault();
      // coalesced events give 120 Hz+ precision on iPad/Android
      const list = typeof p.getCoalescedEvents === 'function' ? p.getCoalescedEvents() : [];
      for (const c of list.length ? list : [p]) {
        const [x, y] = pt(c);
        this.engine.move(p.pointerId, x, y, ts(c));
      }
      this.schedule();
    }, { passive: false });
    on(stage, 'pointerup', (e) => {
      const p = e as PointerEvent;
      if (!mine(p)) return;
      const [x, y] = pt(p);
      const t = ts(p);
      this.engine.tick(t);            // a busy main thread may have delayed the long-press timer
      this.engine.up(p.pointerId, x, y, t);
      this.schedule();
    });
    on(stage, 'pointercancel', (e) => { const p = e as PointerEvent; if (mine(p)) { this.engine.cancelPointer(p.pointerId); this.schedule(); } });
    on(stage, 'contextmenu', (e) => e.preventDefault());
    // iOS Safari: stop page pinch / double-tap zoom / callout
    on(stage, 'gesturestart', (e) => e.preventDefault(), { passive: false });
    on(stage, 'touchstart', (e) => { if ((e as TouchEvent).touches.length > 1) e.preventDefault(); }, { passive: false });
    // macOS trackpad pinch (Chrome/Edge/Firefox send ctrl+wheel; Safari sends gesture events)
    on(stage, 'wheel', (e) => {
      const w = e as WheelEvent;
      if (!w.ctrlKey) return;
      w.preventDefault();
      w.stopImmediatePropagation();
      const r = stage.getBoundingClientRect();
      this.zoom(Math.exp(-w.deltaY / 100), w.clientX - r.left, w.clientY - r.top);
    }, { passive: false, capture: true });
    let gs = 1;
    on(stage, 'gesturechange', (e) => {
      const g = e as unknown as { scale: number; clientX: number; clientY: number; preventDefault(): void };
      g.preventDefault();
      const r = stage.getBoundingClientRect();
      this.zoom(g.scale / gs, g.clientX - r.left, g.clientY - r.top);
      gs = g.scale;
    }, { passive: false });
    on(stage, 'gestureend', () => { gs = 1; });

    const resize = () => {
      const r = stage.getBoundingClientRect();
      this.viewport.setSize(r.width, r.height);
      this.apply();
    };
    if (typeof ResizeObserver !== 'undefined') { this.ro = new ResizeObserver(resize); this.ro.observe(stage); this.ro.observe(video); }
    on(video, 'loadedmetadata', resize);
    on(video, 'resize', resize);
    resize();
    this.setMode(this.engine.mode);
  }

  get mode(): Mode { return this.engine.mode; }

  setMode(m: Mode): void {
    this.engine.setMode(m);
    this.stage.dataset.lstMode = m;
    this.cursorEl.style.display = m === 'trackpad' ? 'block' : 'none';
    this.updateCursorEl();
    this.o.onModeChange?.(m);
  }
  toggleMode(): Mode { this.setMode(this.mode === 'direct' ? 'trackpad' : 'direct'); return this.mode; }

  zoom(factor: number, cx: number, cy: number): void {
    this.viewport.zoomAt(factor, cx, cy);
    this.apply();
  }
  resetZoom(): void { this.viewport.reset(); this.apply(); }

  private apply(): void {
    this.video.style.transformOrigin = '0 0';
    this.video.style.transform = this.viewport.zoomed ? this.viewport.css() : '';
    this.stage.dataset.lstZoomed = this.viewport.zoomed ? '1' : '0';
    this.updateCursorEl();
    this.o.onZoom?.(this.viewport.scale);
  }

  private updateCursorEl(): void {
    const [ux, uy] = this.mapper.normToStage(this.cursor[0], this.cursor[1]);
    const [x, y] = this.viewport.project(ux, uy);
    this.cursorEl.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
  }

  private sendCursor(): void {
    this.sink.push(ev.abs(this.cursor[0] * ABS_MAX, this.cursor[1] * ABS_MAX));
  }

  private act(a: Action): void {
    switch (a.t) {
      case 'pointer':
        this.cursor = this.mapper.toNorm(a.x, a.y);
        this.sendCursor();
        this.updateCursorEl();
        break;
      case 'cursor': {
        const [kx, ky] = this.mapper.pxToNorm();
        this.cursor = [Math.min(1, Math.max(0, this.cursor[0] + a.dx * kx)), Math.min(1, Math.max(0, this.cursor[1] + a.dy * ky))];
        this.sendCursor();
        const [ux, uy] = this.mapper.normToStage(this.cursor[0], this.cursor[1]);
        if (this.viewport.zoomed) { this.viewport.ensureVisible(ux, uy); this.apply(); }
        else this.updateCursorEl();
        break;
      }
      case 'button':
        this.sink.push(ev.btn(a.button, a.down));
        if (!a.down) this.o.onPointerAction?.();
        break;
      case 'click':
        this.sink.push(ev.btn(a.button, true));
        this.sink.push(ev.btn(a.button, false));
        this.o.onPointerAction?.();
        break;
      case 'wheel': {
        const s = this.o.naturalScroll ? 1 : -1;
        this.wheelAcc[0] += -a.dx * this.o.wheelGain * s;
        this.wheelAcc[1] += a.dy * this.o.wheelGain * s;
        const wx = Math.trunc(this.wheelAcc[0]), wy = Math.trunc(this.wheelAcc[1]);
        if (wx || wy) {
          this.wheelAcc[0] -= wx; this.wheelAcc[1] -= wy;
          this.sink.push(ev.wheel(Math.max(-WHEEL_NOTCH * 8, Math.min(WHEEL_NOTCH * 8, wy)), Math.max(-WHEEL_NOTCH * 8, Math.min(WHEEL_NOTCH * 8, wx))));
        }
        break;
      }
      case 'zoom':
        this.zoom(a.factor, a.cx, a.cy);
        break;
      case 'pan':
        if (this.viewport.zoomed) { this.viewport.pan(a.dx, a.dy); this.apply(); }
        break;
      case 'haptic':
        try { (navigator as Navigator & { vibrate?: (ms: number) => boolean }).vibrate?.(a.ms); } catch { /* iOS has none */ }
        break;
      case 'threeFingerTap':
        this.o.onThreeFingerTap?.();
        break;
    }
  }

  private schedule(): void {
    if (this.timer) { clearTimeout(this.timer); this.timer = null; }
    const d = this.engine.nextDeadline();
    if (d === null) return;
    const wait = Math.max(0, d - performance.now());
    this.timer = setTimeout(() => { this.timer = null; this.engine.tick(performance.now()); this.schedule(); }, wait);
  }

  detach(): void {
    this.engine.cancel();
    if (this.timer) clearTimeout(this.timer);
    this.ro?.disconnect();
    this.L.forEach((f) => f());
    this.cursorEl.remove();
    this.video.style.transform = '';
    this.stage.classList.remove('lst-stage');
  }
}
