import { useEffect, useState } from 'react';
import { PARKED_LIMIT_KMH } from './car';

export interface ParkedState {
  /** Latest GPS speed in km/h, null when unknown (no fix / no permission / API missing). */
  speedKmh: number | null;
  moving: boolean;
  source: 'gps' | 'unavailable' | 'denied' | 'off';
}

/**
 * Parked-safety watcher: Geolocation `coords.speed` (m/s) > 5 km/h ⇒ moving.
 * Hysteresis: back to parked only after speed stays ≤ 2 km/h for 3 s, so a stop light
 * doesn't flicker the overlay. Unknown speed never blocks (we can't tell), but the launcher
 * asks the user to confirm they are parked.
 */
export function useParkedGuard(enabled: boolean): ParkedState {
  const [st, setSt] = useState<ParkedState>({ speedKmh: null, moving: false, source: enabled ? 'unavailable' : 'off' });
  useEffect(() => {
    if (!enabled) {
      setSt({ speedKmh: null, moving: false, source: 'off' });
      return;
    }
    const geo = typeof navigator !== 'undefined' ? navigator.geolocation : undefined;
    if (!geo?.watchPosition) return;
    let slowSince = 0;
    const id = geo.watchPosition(
      (pos) => {
        const mps = pos.coords.speed;
        if (mps === null || Number.isNaN(mps)) {
          setSt((s) => ({ ...s, speedKmh: null, source: 'gps' }));
          return;
        }
        const kmh = mps * 3.6;
        const now = performance.now();
        setSt((s) => {
          let moving = s.moving;
          if (kmh > PARKED_LIMIT_KMH) {
            moving = true;
            slowSince = 0;
          } else if (moving) {
            if (kmh <= 2) {
              if (!slowSince) slowSince = now;
              if (now - slowSince >= 3000) moving = false;
            } else slowSince = 0;
          }
          return { speedKmh: kmh, moving, source: 'gps' };
        });
      },
      (err) => setSt({ speedKmh: null, moving: false, source: err.code === err.PERMISSION_DENIED ? 'denied' : 'unavailable' }),
      { enableHighAccuracy: true, maximumAge: 1000, timeout: 15000 },
    );
    return () => geo.clearWatch(id);
  }, [enabled]);
  return st;
}
