import { useEffect, useMemo, useRef, useState, type ClipboardEvent, type KeyboardEvent, type ReactNode } from 'react';
import type { Settings } from '../lib/settings';
import { supportedVideoCodecs } from '../lib/session';
import { extractCarLink } from '../lib/car';
import { CLOUD_WSS, forgetDevice, formatDeviceId, loadDevices, normaliseDeviceId, renameDevice, type SavedDevice } from '../lib/devices';

export interface ConnectRequest {
  code?: string;
  secret?: string;
  /** v1.2: permanent Device ID (cloud rendezvous) + fixed access password (first connection only). */
  device?: string;
  password?: string;
  /** Signaling URL for this request (a saved device remembers its own). */
  wss?: string;
  demo?: boolean;
}

interface Props {
  settings: Settings;
  setSettings: (p: Partial<Settings>) => void;
  onConnect: (r: ConnectRequest) => void;
  error: string | null;
  busy: boolean;
}

export function ConnectScreen({ settings, setSettings, onConnect, error, busy }: Props) {
  const [digits, setDigits] = useState<string[]>(() => {
    const c = new URLSearchParams(location.search).get('code') ?? (settings.lastCode || '');
    return /^\d{6}$/.test(c) ? c.split('') : ['', '', '', '', '', ''];
  });
  const [secret, setSecret] = useState('');
  const [advanced, setAdvanced] = useState(false);
  const [devices, setDevices] = useState<SavedDevice[]>(() => loadDevices());
  const [password, setPassword] = useState('');
  const [useCode, setUseCode] = useState(false);
  const deviceId = normaliseDeviceId(settings.deviceId);
  const refs = useRef<Array<HTMLInputElement | null>>([]);
  const codecs = useMemo(() => supportedVideoCodecs(), []);
  const code = digits.join('');
  const codeReady = /^\d{6}$/.test(code);
  const canConnect =
    !busy &&
    settings.signalUrl.trim().length > 0 &&
    (settings.authMode === 'code' ? codeReady : settings.authMode === 'device' ? !!deviceId && (useCode ? codeReady : password.length > 0) : secret.length >= 8);
  const insecureWs = location.protocol === 'https:' && /^ws:\/\//i.test(settings.signalUrl.trim());

  useEffect(() => {
    if (settings.lastCode && /^\d{6}$/.test(settings.lastCode) && settings.lastCode !== code) {
      setDigits(settings.lastCode.split(''));
    }
  }, [settings.lastCode]);

  const handleSignalInput = (raw: string) => {
    const link = extractCarLink(raw);
    if (link?.wss) {
      setSettings({
        signalUrl: link.wss,
        ...(link.code ? { lastCode: link.code, authMode: 'code' as const } : {}),
        ...(link.brand ? { carBrand: link.brand } : {}),
        ...(link.codec ? { codec: link.codec, carCodecLock: true } : {}),
      });
      if (link.code) setDigits(link.code.split(''));
      return;
    }
    setSettings({ signalUrl: raw });
  };

  const setDigit = (i: number, v: string) => {
    const d = v.replace(/\D/g, '');
    if (!d) {
      setDigits((p) => p.map((x, j) => (j === i ? '' : x)));
      return;
    }
    if (d.length > 1) return fillFrom(i, d);
    setDigits((p) => p.map((x, j) => (j === i ? d : x)));
    if (i < 5) refs.current[i + 1]?.focus();
  };
  const fillFrom = (start: number, s: string) => {
    setDigits((p) => {
      const n = [...p];
      for (let k = 0; k < s.length && start + k < 6; k++) n[start + k] = s[k];
      return n;
    });
    refs.current[Math.min(5, start + s.length)]?.focus();
  };
  const onKey = (i: number, e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !digits[i] && i > 0) refs.current[i - 1]?.focus();
    if (e.key === 'ArrowLeft' && i > 0) refs.current[i - 1]?.focus();
    if (e.key === 'ArrowRight' && i < 5) refs.current[i + 1]?.focus();
    if (e.key === 'Enter' && canConnect) submit();
  };
  const onPaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const d = e.clipboardData.getData('text').replace(/\D/g, '');
    if (d) {
      e.preventDefault();
      fillFrom(0, d.slice(0, 6));
    }
  };
  const submit = () => {
    if (!canConnect) return;
    if (settings.authMode === 'device' && deviceId) onConnect(useCode ? { device: deviceId, code } : { device: deviceId, password });
    else onConnect(settings.authMode === 'code' ? { code } : { secret });
  };
  const connectSaved = (d: SavedDevice) => onConnect({ device: d.id, secret: d.secret, wss: d.wss });

  return (
    <div className="min-h-full flex items-center justify-center p-5 bg-[radial-gradient(ellipse_at_top,_#0f1d2b_0%,_#05060a_60%)]">
      <div className="w-full max-w-md">
        <div className="flex items-center gap-3 mb-8">
          <img src="./favicon.svg" alt="" className="w-11 h-11" />
          <div>
            <h1 className="text-2xl font-semibold tracking-tight text-white">LeeStream</h1>
            <p className="text-sm text-slate-400">Zero-install web client · v1.2</p>
          </div>
        </div>

        <button
          onClick={() => setSettings({ carMode: true })}
          className="mb-4 flex min-h-16 w-full items-center justify-center gap-3 rounded-2xl border-2 border-cyan-400/40 bg-cyan-400/10 text-lg font-semibold text-cyan-100 hover:bg-cyan-400/20"
          aria-label="Car Cockpit Mode"
        >
          🚗 车载座舱模式 / Car Cockpit Mode
        </button>
        {devices.length > 0 && (
          <div className="glass mb-4 rounded-2xl p-4" data-testid="my-devices">
            <div className="mb-2 text-xs font-medium uppercase tracking-wider text-slate-400">My Devices</div>
            <ul className="space-y-2">
              {devices.map((d) => (
                <li key={d.id} className="flex items-center gap-2 rounded-xl bg-black/30 px-3 py-2">
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-sm font-medium text-white">{d.name}</div>
                    <div className="font-mono text-xs text-slate-400">{formatDeviceId(d.id)}</div>
                  </div>
                  <button
                    disabled={busy}
                    onClick={() => connectSaved(d)}
                    aria-label={`Connect ${d.name}`}
                    className="min-h-11 rounded-lg bg-gradient-to-r from-cyan-400 to-violet-500 px-4 text-sm font-semibold text-black disabled:opacity-30"
                  >
                    Connect
                  </button>
                  <button
                    onClick={() => {
                      const n = prompt('Nickname', d.name);
                      if (n) setDevices(renameDevice(d.id, n));
                    }}
                    aria-label={`Rename ${d.name}`}
                    className="min-h-11 rounded-lg px-2 text-slate-400 hover:text-white"
                  >
                    ✎
                  </button>
                  <button
                    onClick={() => confirm(`Forget ${d.name}? You'll need the access password again.`) && setDevices(forgetDevice(d.id))}
                    aria-label={`Forget ${d.name}`}
                    className="min-h-11 rounded-lg px-2 text-slate-400 hover:text-red-300"
                  >
                    ✕
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}
        <div className="glass rounded-2xl p-6 shadow-2xl shadow-cyan-500/5">
          <label className="block text-xs font-medium uppercase tracking-wider text-slate-400 mb-2">Signaling URL</label>
          <input
            className="w-full rounded-lg bg-black/40 border border-edge px-3 py-2.5 text-sm text-white placeholder:text-slate-600 focus:outline-none focus:border-accent"
            placeholder="wss://my-pc.example.com:47901/ws"
            value={settings.signalUrl}
            onChange={(e) => handleSignalInput(e.target.value)}
            autoCapitalize="off"
            autoCorrect="off"
            spellCheck={false}
            inputMode="url"
          />
          {insecureWs && <p className="mt-1.5 text-xs text-amber-400">This page is HTTPS, so browsers block ws:// — use wss://.</p>}

          <div className="mt-5 flex rounded-lg bg-black/40 p-1 text-sm">
            {(['device', 'code', 'secret'] as const).map((m) => (
              <button
                key={m}
                onClick={() => setSettings({ authMode: m, ...(m === 'device' && !settings.signalUrl ? { signalUrl: CLOUD_WSS } : {}) })}
                className={`flex-1 rounded-md py-1.5 transition ${settings.authMode === m ? 'bg-white/10 text-white' : 'text-slate-400 hover:text-slate-200'}`}
              >
                {m === 'device' ? 'Device ID' : m === 'code' ? '6-digit code' : 'Direct secret'}
              </button>
            ))}
          </div>

          {settings.authMode === 'device' && (
            <div className="mt-5 space-y-3">
              <input
                className="w-full rounded-lg bg-black/40 border border-edge px-3 py-2.5 text-center font-mono text-2xl tracking-widest text-white focus:outline-none focus:border-accent"
                placeholder="123 456 789"
                value={settings.deviceId}
                onChange={(e) => setSettings({ deviceId: e.target.value.replace(/[^\d\s-]/g, '').slice(0, 11) })}
                inputMode="numeric"
                aria-label="Device ID"
              />
              {useCode ? (
                <p className="text-xs text-slate-500">Enter the 6-digit code shown on the host below.</p>
              ) : (
                <input
                  type="password"
                  className="w-full rounded-lg bg-black/40 border border-edge px-3 py-2.5 text-sm text-white focus:outline-none focus:border-accent"
                  placeholder="Access password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && submit()}
                  autoComplete="current-password"
                  aria-label="Access password"
                />
              )}
              <button onClick={() => setUseCode((u) => !u)} className="text-xs text-slate-400 hover:text-slate-200">
                {useCode ? 'Use the access password instead' : 'No password set? Use a one-time 6-digit code'}
              </button>
              <p className="text-xs text-slate-500">The Device ID never changes. After the first connection this browser remembers the PC under My Devices.</p>
            </div>
          )}

          {settings.authMode === 'device' && !useCode ? null : settings.authMode === 'code' || settings.authMode === 'device' ? (
            <div className="mt-5">
              <div className="flex justify-between gap-2">
                {digits.map((d, i) => (
                  <input
                    key={i}
                    ref={(el) => {
                      refs.current[i] = el;
                    }}
                    value={d}
                    onChange={(e) => setDigit(i, e.target.value)}
                    onKeyDown={(e) => onKey(i, e)}
                    onPaste={onPaste}
                    onFocus={(e) => e.target.select()}
                    inputMode="numeric"
                    autoComplete={i === 0 ? 'one-time-code' : 'off'}
                    maxLength={6}
                    aria-label={`Digit ${i + 1}`}
                    className={`code-cell w-12 h-14 sm:w-14 sm:h-16 text-center text-2xl font-mono rounded-xl bg-black/50 border text-white focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/30 ${i === 2 ? 'mr-2' : ''} ${d ? 'border-accent/40' : 'border-edge'}`}
                  />
                ))}
              </div>
              <p className="mt-2 text-xs text-slate-500">Shown on the host under LeeStream → Pair a device. Codes expire after 5 minutes.</p>
            </div>
          ) : (
            <div className="mt-5">
              <input
                type="password"
                className="w-full rounded-lg bg-black/40 border border-edge px-3 py-2.5 text-sm text-white font-mono focus:outline-none focus:border-accent"
                placeholder="Host secret (from host config)"
                value={secret}
                onChange={(e) => setSecret(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && submit()}
                autoComplete="current-password"
              />
            </div>
          )}

          {error && <div className="mt-4 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

          <button
            disabled={!canConnect}
            onClick={submit}
            className="mt-5 w-full rounded-xl py-3 font-semibold text-black bg-gradient-to-r from-cyan-400 to-violet-500 disabled:opacity-30 disabled:cursor-not-allowed hover:brightness-110 transition"
          >
            {busy ? 'Connecting…' : 'Connect'}
          </button>
          <button
            onClick={() => onConnect({ demo: true })}
            disabled={busy}
            className="mt-3 w-full rounded-xl py-2.5 text-sm font-medium text-slate-200 border border-edge hover:bg-white/5 transition"
          >
            Try Local Demo (loopback test, no host needed)
          </button>

          <button onClick={() => setAdvanced((a) => !a)} className="mt-5 text-xs text-slate-400 hover:text-slate-200">
            {advanced ? '▾' : '▸'} Advanced
          </button>
          {advanced && (
            <div className="mt-3 space-y-3 text-sm">
              <Row label="Who sends the SDP offer">
                <Select value={settings.offerer} onChange={(v) => setSettings({ offerer: v as Settings['offerer'] })} options={[['host', 'Host (default)'], ['client', 'Browser']]} />
              </Row>
              <Row label="Preferred codec">
                <Select
                  value={settings.codec}
                  onChange={(v) => setSettings({ codec: v as Settings['codec'] })}
                  options={[['auto', 'Auto (HEVC → H.264)'], ['h264', 'H.264'], ['hevc', 'HEVC / H.265'], ['av1', 'AV1']]}
                />
              </Row>
              <Row label="Client name">
                <input className="w-40 rounded bg-black/40 border border-edge px-2 py-1" value={settings.clientName} onChange={(e) => setSettings({ clientName: e.target.value })} />
              </Row>
              <div>
                <div className="text-slate-400 mb-1">ICE servers (JSON)</div>
                <textarea
                  className="w-full h-20 rounded bg-black/40 border border-edge px-2 py-1 font-mono text-xs"
                  value={settings.iceServers}
                  onChange={(e) => setSettings({ iceServers: e.target.value })}
                  spellCheck={false}
                />
              </div>
              <p className="text-xs text-slate-500">Browser decodes: {codecs.join(', ') || 'unknown'}</p>
            </div>
          )}
        </div>
        <p className="mt-6 text-center text-xs text-slate-600">Video and input travel peer-to-peer over WebRTC (DTLS-SRTP). Nothing is installed.</p>
      </div>
    </div>
  );
}

function Row({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <span className="text-slate-400">{label}</span>
      {children}
    </div>
  );
}

function Select({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: Array<[string, string]> }) {
  return (
    <select className="rounded bg-black/40 border border-edge px-2 py-1" value={value} onChange={(e) => onChange(e.target.value)}>
      {options.map(([v, l]) => (
        <option key={v} value={v}>
          {l}
        </option>
      ))}
    </select>
  );
}
