/**
 * KeyboardEvent.code  ->  Windows PS/2 "Set 1" make code.
 *
 * Matches the host's `InputEvent::Key { scan: u16, down: bool, extended: bool }`:
 *   - `scan`      is the Set-1 make code WITHOUT the 0xE0 prefix (what SendInput's
 *                 `wScan` expects together with KEYEVENTF_SCANCODE).
 *   - `extended`  is true for keys that carry the 0xE0 prefix on real hardware
 *                 (-> KEYEVENTF_EXTENDEDKEY on the host).
 *
 * Using `code` (physical position) rather than `key` (produced character) means the
 * host's own keyboard layout decides which character is typed — exactly like a
 * native client. The table below is the full US-ANSI 104-key layout plus the ISO
 * extra key, JIS keys, F13–F24 and the common media / browser keys.
 *
 * Notes on the two classic oddballs:
 *   - NumLock  is reported by Windows as scan 0x45 + extended.
 *   - Pause    is scan 0x45 without extended (Windows synthesises the E1 sequence).
 *   - PrintScreen is 0x37 + extended (Windows' Alt+PrtSc -> 0x54 is handled by the OS).
 */
export interface ScanCode {
  scan: number;
  extended: boolean;
}

const k = (scan: number, extended = false): ScanCode => ({ scan, extended });

export const SCANCODES: Readonly<Record<string, ScanCode>> = Object.freeze({
  // ── Row 0: Esc + function keys ───────────────────────────────────────────
  Escape: k(0x01),
  F1: k(0x3b), F2: k(0x3c), F3: k(0x3d), F4: k(0x3e), F5: k(0x3f), F6: k(0x40),
  F7: k(0x41), F8: k(0x42), F9: k(0x43), F10: k(0x44), F11: k(0x57), F12: k(0x58),
  F13: k(0x64), F14: k(0x65), F15: k(0x66), F16: k(0x67), F17: k(0x68), F18: k(0x69),
  F19: k(0x6a), F20: k(0x6b), F21: k(0x6c), F22: k(0x6d), F23: k(0x6e), F24: k(0x76),

  // ── Row 1: number row ────────────────────────────────────────────────────
  Backquote: k(0x29),
  Digit1: k(0x02), Digit2: k(0x03), Digit3: k(0x04), Digit4: k(0x05), Digit5: k(0x06),
  Digit6: k(0x07), Digit7: k(0x08), Digit8: k(0x09), Digit9: k(0x0a), Digit0: k(0x0b),
  Minus: k(0x0c), Equal: k(0x0d), Backspace: k(0x0e),

  // ── Row 2 ────────────────────────────────────────────────────────────────
  Tab: k(0x0f),
  KeyQ: k(0x10), KeyW: k(0x11), KeyE: k(0x12), KeyR: k(0x13), KeyT: k(0x14),
  KeyY: k(0x15), KeyU: k(0x16), KeyI: k(0x17), KeyO: k(0x18), KeyP: k(0x19),
  BracketLeft: k(0x1a), BracketRight: k(0x1b), Backslash: k(0x2b),

  // ── Row 3 ────────────────────────────────────────────────────────────────
  CapsLock: k(0x3a),
  KeyA: k(0x1e), KeyS: k(0x1f), KeyD: k(0x20), KeyF: k(0x21), KeyG: k(0x22),
  KeyH: k(0x23), KeyJ: k(0x24), KeyK: k(0x25), KeyL: k(0x26),
  Semicolon: k(0x27), Quote: k(0x28), Enter: k(0x1c),

  // ── Row 4 ────────────────────────────────────────────────────────────────
  ShiftLeft: k(0x2a),
  IntlBackslash: k(0x56), // ISO key between LShift and Z
  KeyZ: k(0x2c), KeyX: k(0x2d), KeyC: k(0x2e), KeyV: k(0x2f), KeyB: k(0x30),
  KeyN: k(0x31), KeyM: k(0x32),
  Comma: k(0x33), Period: k(0x34), Slash: k(0x35), ShiftRight: k(0x36),

  // ── Row 5: modifiers + space ─────────────────────────────────────────────
  ControlLeft: k(0x1d), MetaLeft: k(0x5b, true), AltLeft: k(0x38),
  Space: k(0x39),
  AltRight: k(0x38, true), MetaRight: k(0x5c, true), ContextMenu: k(0x5d, true),
  ControlRight: k(0x1d, true),
  // Legacy names some browsers (old Firefox/Safari) still emit:
  OSLeft: k(0x5b, true), OSRight: k(0x5c, true),

  // ── Navigation cluster (all extended) ────────────────────────────────────
  PrintScreen: k(0x37, true), ScrollLock: k(0x46), Pause: k(0x45),
  Insert: k(0x52, true), Home: k(0x47, true), PageUp: k(0x49, true),
  Delete: k(0x53, true), End: k(0x4f, true), PageDown: k(0x51, true),
  ArrowUp: k(0x48, true), ArrowLeft: k(0x4b, true), ArrowDown: k(0x50, true), ArrowRight: k(0x4d, true),

  // ── Numpad ───────────────────────────────────────────────────────────────
  NumLock: k(0x45, true),
  NumpadDivide: k(0x35, true), NumpadMultiply: k(0x37), NumpadSubtract: k(0x4a), NumpadAdd: k(0x4e),
  NumpadEnter: k(0x1c, true), NumpadDecimal: k(0x53),
  Numpad0: k(0x52), Numpad1: k(0x4f), Numpad2: k(0x50), Numpad3: k(0x51), Numpad4: k(0x4b),
  Numpad5: k(0x4c), Numpad6: k(0x4d), Numpad7: k(0x47), Numpad8: k(0x48), Numpad9: k(0x49),
  NumpadEqual: k(0x59), NumpadComma: k(0x7e),

  // ── International / JIS ──────────────────────────────────────────────────
  IntlRo: k(0x73), IntlYen: k(0x7d), KanaMode: k(0x70), Convert: k(0x79), NonConvert: k(0x7b),
  Lang1: k(0x72), Lang2: k(0x71),

  // ── Media / browser / power (extended) ───────────────────────────────────
  MediaTrackPrevious: k(0x10, true), MediaTrackNext: k(0x19, true),
  MediaPlayPause: k(0x22, true), MediaStop: k(0x24, true),
  AudioVolumeMute: k(0x20, true), AudioVolumeDown: k(0x2e, true), AudioVolumeUp: k(0x30, true),
  VolumeMute: k(0x20, true), VolumeDown: k(0x2e, true), VolumeUp: k(0x30, true),
  LaunchApp2: k(0x21, true), LaunchApp1: k(0x6b, true), LaunchMail: k(0x6c, true), MediaSelect: k(0x6d, true),
  BrowserHome: k(0x32, true), BrowserSearch: k(0x65, true), BrowserFavorites: k(0x66, true),
  BrowserRefresh: k(0x67, true), BrowserStop: k(0x68, true), BrowserForward: k(0x69, true), BrowserBack: k(0x6a, true),
  Power: k(0x5e, true), Sleep: k(0x5f, true), WakeUp: k(0x63, true),
});

export function codeToScan(code: string): ScanCode | undefined {
  return SCANCODES[code];
}

/** Human label for HUD / debug overlays. */
export function scanLabel(sc: ScanCode): string {
  return `${sc.extended ? 'E0 ' : ''}${sc.scan.toString(16).toUpperCase().padStart(2, '0')}`;
}
