/**
 * LeeStream Web wire protocol (DataChannels).
 *
 * Everything here is pure (no DOM), so the same codec is used by the client,
 * the loopback "fake host" and the Node unit test (`npm test`).
 *
 * ┌──────────┬───────────────────────────────────────────────────────────────┐
 * │ channel  │ payload                                                       │
 * ├──────────┼───────────────────────────────────────────────────────────────┤
 * │ input    │ binary, little-endian, 1 event per message (see INPUT_*)      │
 * │ cursor   │ binary, host -> client (see CURSOR_*)                         │
 * │ ctrl     │ UTF-8 JSON text, both directions (see CtrlMsg); the native    │
 * │          │ host may also send binary [0x05] = ctrl::BYE (preempted)      │
 * │ audio    │ binary, host -> client, 1 raw Opus packet (48 kHz) / message  │
 * └──────────┴───────────────────────────────────────────────────────────────┘
 *
 * Byte 0 of every `input` message is the event tag. Exact layouts are mirrored
 * in INTEGRATION.md §4 together with the Rust decoder for the host.
 */

// ── input channel tags ──────────────────────────────────────────────────────
export const INPUT_KEY = 0x01; //       [tag, flags, scan:u16]                 4 B
export const INPUT_MOUSE_REL = 0x02; // [tag, 0, dx:i16, dy:i16]               6 B
export const INPUT_MOUSE_ABS = 0x03; // [tag, 0, x:u16, y:u16]   (0..65535)    6 B
export const INPUT_MOUSE_BTN = 0x04; // [tag, button, down:u8]                 3 B
export const INPUT_WHEEL = 0x05; //     [tag, 0, dx:i16, dy:i16] (120 = 1 notch) 6 B
export const INPUT_UNICODE = 0x06; //   [tag, down:u8, codepoint:u32]          6 B  (optional; IME / emoji)
export const INPUT_RELEASE_ALL = 0x07; // [tag]                                1 B  (focus lost -> host releases all held keys/buttons)
export const INPUT_GAMEPAD = 0x10; //   20-byte report, see encodeGamepad      20 B

export const KEY_FLAG_DOWN = 0x01;
export const KEY_FLAG_EXTENDED = 0x02;

/** Mouse button ids on the wire (same order as Windows' MOUSEEVENTF_* pairs). */
export const MouseButton = {
  Left: 0,
  Right: 1,
  Middle: 2,
  X1: 3,
  X2: 4,
} as const;
export type MouseButtonId = (typeof MouseButton)[keyof typeof MouseButton];

/** DOM `MouseEvent.button` -> wire button id. */
export function domButtonToWire(b: number): MouseButtonId | undefined {
  switch (b) {
    case 0: return MouseButton.Left;
    case 1: return MouseButton.Middle;
    case 2: return MouseButton.Right;
    case 3: return MouseButton.X1;
    case 4: return MouseButton.X2;
    default: return undefined;
  }
}

const clampI16 = (v: number) => Math.max(-32768, Math.min(32767, Math.round(v)));
const clampU16 = (v: number) => Math.max(0, Math.min(65535, Math.round(v)));

export function encodeKey(scan: number, down: boolean, extended: boolean): Uint8Array {
  const b = new Uint8Array(4);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_KEY;
  b[1] = (down ? KEY_FLAG_DOWN : 0) | (extended ? KEY_FLAG_EXTENDED : 0);
  dv.setUint16(2, scan & 0xffff, true);
  return b;
}

export function encodeMouseRel(dx: number, dy: number): Uint8Array {
  const b = new Uint8Array(6);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_MOUSE_REL;
  dv.setInt16(2, clampI16(dx), true);
  dv.setInt16(4, clampI16(dy), true);
  return b;
}

/** x,y normalised 0..1 over the remote desktop (host maps to MOUSEEVENTF_ABSOLUTE|VIRTUALDESK of the streamed monitor). */
export function encodeMouseAbs(nx: number, ny: number): Uint8Array {
  const b = new Uint8Array(6);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_MOUSE_ABS;
  dv.setUint16(2, clampU16(nx * 65535), true);
  dv.setUint16(4, clampU16(ny * 65535), true);
  return b;
}

export function encodeMouseButton(button: MouseButtonId, down: boolean): Uint8Array {
  return Uint8Array.of(INPUT_MOUSE_BTN, button, down ? 1 : 0);
}

/** Values in WHEEL_DELTA units: +120 = one notch away from the user (up) / to the right. */
export function encodeWheel(dx: number, dy: number): Uint8Array {
  const b = new Uint8Array(6);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_WHEEL;
  dv.setInt16(2, clampI16(dx), true);
  dv.setInt16(4, clampI16(dy), true);
  return b;
}

export function encodeUnicode(codepoint: number, down: boolean): Uint8Array {
  const b = new Uint8Array(6);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_UNICODE;
  b[1] = down ? 1 : 0;
  dv.setUint32(2, codepoint >>> 0, true);
  return b;
}

export function encodeReleaseAll(): Uint8Array {
  return Uint8Array.of(INPUT_RELEASE_ALL);
}

// ── 20-byte gamepad report ──────────────────────────────────────────────────
/**
 * Offset  Size  Field
 *   0      1    tag = 0x10
 *   1      1    pad: bits 0-3 = controller index (0..3), bit 4 = connected, bits 5-7 reserved
 *   2      2    buttons: u16 LE, XInput wButtons bitmask (XINPUT_GAMEPAD_*), 0x0400 = Guide
 *   4      1    left trigger  u8 (0..255)
 *   5      1    right trigger u8 (0..255)
 *   6      2    LX i16 LE  (-32768..32767, right = +)
 *   8      2    LY i16 LE  (up = +, XInput convention; browser Y is inverted for you)
 *  10      2    RX i16 LE
 *  12      2    RY i16 LE  (up = +)
 *  14      2    seq u16 LE (per controller, wraps; host drops stale/out-of-order reports)
 *  16      4    timestamp u32 LE, client ms (performance.now(), wraps) — for latency telemetry
 * = 20 bytes. Maps 1:1 onto XINPUT_GAMEPAD / ViGEm XUSB_REPORT.
 */
export const GAMEPAD_REPORT_SIZE = 20;
export const GAMEPAD_FLAG_CONNECTED = 0x10;

export const XI = {
  DPAD_UP: 0x0001,
  DPAD_DOWN: 0x0002,
  DPAD_LEFT: 0x0004,
  DPAD_RIGHT: 0x0008,
  START: 0x0010,
  BACK: 0x0020,
  LEFT_THUMB: 0x0040,
  RIGHT_THUMB: 0x0080,
  LEFT_SHOULDER: 0x0100,
  RIGHT_SHOULDER: 0x0200,
  GUIDE: 0x0400,
  A: 0x1000,
  B: 0x2000,
  X: 0x4000,
  Y: 0x8000,
} as const;

export interface GamepadReport {
  index: number;
  connected: boolean;
  buttons: number;
  lt: number; // 0..255
  rt: number; // 0..255
  lx: number; // i16
  ly: number;
  rx: number;
  ry: number;
  seq: number;
  timestamp: number;
}

export function encodeGamepad(r: GamepadReport): Uint8Array {
  const b = new Uint8Array(GAMEPAD_REPORT_SIZE);
  const dv = new DataView(b.buffer);
  b[0] = INPUT_GAMEPAD;
  b[1] = (r.index & 0x0f) | (r.connected ? GAMEPAD_FLAG_CONNECTED : 0);
  dv.setUint16(2, r.buttons & 0xffff, true);
  b[4] = Math.max(0, Math.min(255, Math.round(r.lt)));
  b[5] = Math.max(0, Math.min(255, Math.round(r.rt)));
  dv.setInt16(6, clampI16(r.lx), true);
  dv.setInt16(8, clampI16(r.ly), true);
  dv.setInt16(10, clampI16(r.rx), true);
  dv.setInt16(12, clampI16(r.ry), true);
  dv.setUint16(14, r.seq & 0xffff, true);
  dv.setUint32(16, Math.floor(r.timestamp) >>> 0, true);
  return b;
}

// ── decoder (used by loopback host + tests; mirrors the Rust host decoder) ──
export type InputEvent =
  | { type: 'key'; scan: number; down: boolean; extended: boolean }
  | { type: 'mouseRel'; dx: number; dy: number }
  | { type: 'mouseAbs'; x: number; y: number }
  | { type: 'mouseButton'; button: number; down: boolean }
  | { type: 'wheel'; dx: number; dy: number }
  | { type: 'unicode'; codepoint: number; down: boolean }
  | { type: 'releaseAll' }
  | ({ type: 'gamepad' } & GamepadReport);

export function decodeInput(buf: ArrayBuffer | Uint8Array): InputEvent | null {
  const b = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  if (b.length < 1) return null;
  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
  switch (b[0]) {
    case INPUT_KEY:
      if (b.length < 4) return null;
      return { type: 'key', down: !!(b[1] & KEY_FLAG_DOWN), extended: !!(b[1] & KEY_FLAG_EXTENDED), scan: dv.getUint16(2, true) };
    case INPUT_MOUSE_REL:
      if (b.length < 6) return null;
      return { type: 'mouseRel', dx: dv.getInt16(2, true), dy: dv.getInt16(4, true) };
    case INPUT_MOUSE_ABS:
      if (b.length < 6) return null;
      return { type: 'mouseAbs', x: dv.getUint16(2, true), y: dv.getUint16(4, true) };
    case INPUT_MOUSE_BTN:
      if (b.length < 3) return null;
      return { type: 'mouseButton', button: b[1], down: b[2] !== 0 };
    case INPUT_WHEEL:
      if (b.length < 6) return null;
      return { type: 'wheel', dx: dv.getInt16(2, true), dy: dv.getInt16(4, true) };
    case INPUT_UNICODE:
      if (b.length < 6) return null;
      return { type: 'unicode', down: b[1] !== 0, codepoint: dv.getUint32(2, true) };
    case INPUT_RELEASE_ALL:
      return { type: 'releaseAll' };
    case INPUT_GAMEPAD:
      if (b.length < GAMEPAD_REPORT_SIZE) return null;
      return {
        type: 'gamepad',
        index: b[1] & 0x0f,
        connected: !!(b[1] & GAMEPAD_FLAG_CONNECTED),
        buttons: dv.getUint16(2, true),
        lt: b[4],
        rt: b[5],
        lx: dv.getInt16(6, true),
        ly: dv.getInt16(8, true),
        rx: dv.getInt16(10, true),
        ry: dv.getInt16(12, true),
        seq: dv.getUint16(14, true),
        timestamp: dv.getUint32(16, true),
      };
    default:
      return null;
  }
}

// ── cursor channel (host -> client) ─────────────────────────────────────────
export const CURSOR_SHAPE = 0x01; //   [tag, 0, hotX:u16, hotY:u16, ...PNG bytes]
export const CURSOR_VISIBLE = 0x02; // [tag, visible:u8]
export const CURSOR_POS = 0x03; //     [tag, 0, x:u16, y:u16] normalised 0..65535 (host-side moves, e.g. games warping)

export type CursorMsg =
  | { type: 'shape'; hotX: number; hotY: number; png: Uint8Array }
  | { type: 'visible'; visible: boolean }
  | { type: 'pos'; x: number; y: number };

export function decodeCursor(buf: ArrayBuffer | Uint8Array): CursorMsg | null {
  const b = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  if (b.length < 2) return null;
  const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
  switch (b[0]) {
    case CURSOR_SHAPE:
      if (b.length < 7) return null;
      return { type: 'shape', hotX: dv.getUint16(2, true), hotY: dv.getUint16(4, true), png: b.subarray(6) };
    case CURSOR_VISIBLE:
      return { type: 'visible', visible: b[1] !== 0 };
    case CURSOR_POS:
      if (b.length < 6) return null;
      return { type: 'pos', x: dv.getUint16(2, true) / 65535, y: dv.getUint16(4, true) / 65535 };
    default:
      return null;
  }
}

export function encodeCursorShape(hotX: number, hotY: number, png: Uint8Array): Uint8Array {
  const b = new Uint8Array(6 + png.length);
  const dv = new DataView(b.buffer);
  b[0] = CURSOR_SHAPE;
  dv.setUint16(2, hotX, true);
  dv.setUint16(4, hotY, true);
  b.set(png, 6);
  return b;
}

export function encodeCursorVisible(visible: boolean): Uint8Array {
  return Uint8Array.of(CURSOR_VISIBLE, visible ? 1 : 0);
}

// ── ctrl channel (JSON) ─────────────────────────────────────────────────────
export interface MonitorInfo {
  index: number;
  name: string;
  width: number;
  height: number;
  primary?: boolean;
}

/** Client -> host */
export type CtrlOut =
  | {
      t: 'hello';
      client: 'web';
      version: string;
      caps: string[];
      viewport: { w: number; h: number; dpr: number };
      /** Car Cockpit Mode only: brand (car_gateway.rs id) + requested media profile. */
      car?: { brand: string; seat: 'center' | 'passenger'; video: { codec: string; width: number; height: number; fps: number }; audio: { codec: string; kbps: number } };
    }
  | { t: 'monitor'; index: number }
  | { t: 'privacy'; on: boolean }
  | { t: 'clipboard'; text: string }
  | { t: 'keyframe' }
  | { t: 'bitrate'; kbps: number }
  | { t: 'ping'; id: number; ts: number }
  | { t: 'bye' };

/** Host -> client */
export type CtrlIn =
  | { t: 'welcome'; host: string; version?: string; monitors?: MonitorInfo[]; monitor?: number }
  | { t: 'monitors'; list: MonitorInfo[]; current: number }
  | { t: 'privacy'; on: boolean }
  | { t: 'clipboard'; text: string }
  | { t: 'pong'; id: number; ts: number }
  | { t: 'notice'; level: 'info' | 'warn' | 'error'; text: string }
  | { t: 'rumble'; index: number; low: number; high: number; ms: number } // low/high 0..1 (XInput motor speeds / 65535)
  | { t: 'bye'; reason?: string };

// ── binary ctrl BYE (native host ctrl::BYE) ─────────────────────────────────
/**
 * When a native or second client takes over, the host sends a single binary byte `[0x05]` on `ctrl`
 * (ctrl::BYE) instead of JSON `{"t":"bye"}`. The web client must treat it as "preempted", not as a drop.
 */
export const CTRL_BYE_BYTE = 0x05;

/** True for an ArrayBuffer / ArrayBufferView (Uint8Array, DataView, …) whose first byte is 0x05. */
export function isBinaryCtrlBye(data: unknown): boolean {
  let b: Uint8Array | null = null;
  if (data instanceof ArrayBuffer) b = new Uint8Array(data);
  else if (ArrayBuffer.isView(data)) b = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  else if (Object.prototype.toString.call(data) === '[object ArrayBuffer]') b = new Uint8Array(data as ArrayBuffer); // cross-realm
  return !!b && b.length >= 1 && b[0] === CTRL_BYE_BYTE;
}

export function parseCtrl(data: string): CtrlIn | null {
  try {
    const m = JSON.parse(data) as CtrlIn;
    return m && typeof m === 'object' && typeof (m as { t?: unknown }).t === 'string' ? m : null;
  } catch {
    return null;
  }
}

export const CLIENT_VERSION = '1.1.0';
export const CLIENT_CAPS = ['input.v1', 'gamepad20', 'cursor.png', 'unicode', 'audio.opus.dc', 'ctrl.json', 'rumble', 'car.cockpit'];
