import { encodeGamepad, XI, type GamepadReport } from './protocol';
import type { InputSink } from './input';

/** W3C "standard" mapping button index -> XInput bit. Triggers (6,7) are analog and handled separately. */
const STD_BUTTONS: Array<[number, number]> = [
  [0, XI.A],
  [1, XI.B],
  [2, XI.X],
  [3, XI.Y],
  [4, XI.LEFT_SHOULDER],
  [5, XI.RIGHT_SHOULDER],
  [8, XI.BACK],
  [9, XI.START],
  [10, XI.LEFT_THUMB],
  [11, XI.RIGHT_THUMB],
  [12, XI.DPAD_UP],
  [13, XI.DPAD_DOWN],
  [14, XI.DPAD_LEFT],
  [15, XI.DPAD_RIGHT],
  [16, XI.GUIDE],
];

const HEARTBEAT_MS = 100; // host treats a pad as idle/unplugged after ~500 ms of silence
const POLL_MS = 4; // ~250 Hz, matches Chrome's internal gamepad sampling

export interface PadInfo {
  slot: number;
  id: string;
  standard: boolean;
}

function axisToI16(v: number, deadzone: number): number {
  return Math.abs(v) < deadzone ? 0 : Math.round(Math.max(-1, Math.min(1, v)) * 32767);
}

/** Radial deadzone on a stick pair (prevents drift chatter flooding the channel). */
function stick(x: number, y: number, dz: number): [number, number] {
  const m = Math.hypot(x, y);
  if (m < dz) return [0, 0];
  const scale = Math.min(1, (m - dz) / (1 - dz)) / m;
  return [x * scale, y * scale];
}

export class GamepadPoller {
  private sink: InputSink;
  private timer = 0;
  private slots = new Map<number, number>(); // browser gamepad.index -> wire slot 0..3
  private last = new Map<number, { bytes: string; sentAt: number }>();
  private seq = [0, 0, 0, 0];
  private deadzone: () => number;
  onPadsChanged: ((pads: PadInfo[]) => void) | null = null;
  private disposers: Array<() => void> = [];

  constructor(sink: InputSink, deadzone: () => number = () => 0.06) {
    this.sink = sink;
    this.deadzone = deadzone;
  }

  static supported(): boolean {
    return typeof navigator !== 'undefined' && typeof navigator.getGamepads === 'function';
  }

  start(): void {
    if (!GamepadPoller.supported() || this.timer) return;
    const onConn = () => this.refreshPads();
    const onDisc = (e: GamepadEvent) => {
      const slot = this.slots.get(e.gamepad.index);
      if (slot !== undefined) {
        this.sendReport({ index: slot, connected: false, buttons: 0, lt: 0, rt: 0, lx: 0, ly: 0, rx: 0, ry: 0, seq: ++this.seq[slot], timestamp: performance.now() });
        this.slots.delete(e.gamepad.index);
        this.last.delete(slot);
      }
      this.refreshPads();
    };
    window.addEventListener('gamepadconnected', onConn);
    window.addEventListener('gamepaddisconnected', onDisc);
    this.disposers.push(
      () => window.removeEventListener('gamepadconnected', onConn),
      () => window.removeEventListener('gamepaddisconnected', onDisc),
    );
    this.timer = window.setInterval(() => this.poll(), POLL_MS);
    this.refreshPads();
  }

  stop(): void {
    clearInterval(this.timer);
    this.timer = 0;
    // Neutral + disconnected so nothing stays held on the virtual pad.
    for (const slot of this.slots.values()) {
      this.sendReport({ index: slot, connected: false, buttons: 0, lt: 0, rt: 0, lx: 0, ly: 0, rx: 0, ry: 0, seq: ++this.seq[slot], timestamp: performance.now() });
    }
    this.slots.clear();
    this.last.clear();
    this.disposers.forEach((d) => d());
    this.disposers = [];
  }

  private slotFor(gpIndex: number): number | undefined {
    const s = this.slots.get(gpIndex);
    if (s !== undefined) return s;
    const used = new Set(this.slots.values());
    for (let i = 0; i < 4; i++) {
      if (!used.has(i)) {
        this.slots.set(gpIndex, i);
        return i;
      }
    }
    return undefined; // XInput max is 4
  }

  private refreshPads(): void {
    const pads: PadInfo[] = [];
    for (const gp of navigator.getGamepads()) {
      if (!gp || !gp.connected) continue;
      const slot = this.slotFor(gp.index);
      if (slot !== undefined) pads.push({ slot, id: gp.id, standard: gp.mapping === 'standard' });
    }
    this.onPadsChanged?.(pads);
  }

  private poll(): void {
    const now = performance.now();
    const dz = this.deadzone();
    for (const gp of navigator.getGamepads()) {
      if (!gp || !gp.connected) continue;
      const slot = this.slotFor(gp.index);
      if (slot === undefined) continue;

      let buttons = 0;
      for (const [i, bit] of STD_BUTTONS) if (gp.buttons[i]?.pressed) buttons |= bit;
      const lt = (gp.buttons[6]?.value ?? 0) * 255;
      const rt = (gp.buttons[7]?.value ?? 0) * 255;
      const [lx, ly] = stick(gp.axes[0] ?? 0, gp.axes[1] ?? 0, dz);
      const [rx, ry] = stick(gp.axes[2] ?? 0, gp.axes[3] ?? 0, dz);

      const r: GamepadReport = {
        index: slot,
        connected: true,
        buttons,
        lt,
        rt,
        lx: axisToI16(lx, 0),
        ly: -axisToI16(ly, 0), // browser: down = +; XInput: up = +
        rx: axisToI16(rx, 0),
        ry: -axisToI16(ry, 0),
        seq: 0,
        timestamp: now,
      };
      const key = `${r.buttons}|${Math.round(r.lt)}|${Math.round(r.rt)}|${r.lx}|${r.ly}|${r.rx}|${r.ry}`;
      const prev = this.last.get(slot);
      if (prev && prev.bytes === key && now - prev.sentAt < HEARTBEAT_MS) continue;
      r.seq = this.seq[slot] = (this.seq[slot] + 1) & 0xffff;
      this.sendReport(r);
      this.last.set(slot, { bytes: key, sentAt: now });
    }
  }

  private sendReport(r: GamepadReport): void {
    this.sink.sendInput(encodeGamepad(r));
  }

  // ── on-screen (virtual) pad: shares the XInput slot pool with physical pads ──
  private static VIRTUAL = -1;

  /** Reserve a wire slot for the on-screen gamepad (lowest free, so P1 when no controller is plugged in). */
  claimVirtual(): number | undefined {
    return this.slotFor(GamepadPoller.VIRTUAL);
  }

  releaseVirtual(): void {
    const slot = this.slots.get(GamepadPoller.VIRTUAL);
    if (slot === undefined) return;
    this.sendReport({ index: slot, connected: false, buttons: 0, lt: 0, rt: 0, lx: 0, ly: 0, rx: 0, ry: 0, seq: ++this.seq[slot], timestamp: performance.now() });
    this.slots.delete(GamepadPoller.VIRTUAL);
    this.last.delete(slot);
  }

  /** Send a report from the on-screen pad (index/seq/timestamp are filled in here). */
  sendVirtual(r: Omit<GamepadReport, 'index' | 'seq' | 'timestamp' | 'connected'>): void {
    const slot = this.slots.get(GamepadPoller.VIRTUAL);
    if (slot === undefined) return;
    this.seq[slot] = (this.seq[slot] + 1) & 0xffff;
    this.sendReport({ ...r, index: slot, connected: true, seq: this.seq[slot], timestamp: performance.now() });
  }

  /** Host-driven rumble (ctrl `{t:"rumble"}`). */
  rumble(slot: number, low: number, high: number, ms: number): void {
    for (const [gpIndex, s] of this.slots) {
      if (s !== slot) continue;
      const gp = navigator.getGamepads()[gpIndex] as (Gamepad & { vibrationActuator?: { playEffect?: (t: string, p: object) => Promise<unknown> } }) | null;
      gp?.vibrationActuator?.playEffect?.('dual-rumble', {
        duration: Math.min(5000, ms),
        strongMagnitude: Math.max(0, Math.min(1, low)),
        weakMagnitude: Math.max(0, Math.min(1, high)),
      }).catch(() => undefined);
    }
  }
}
