// Mobile / tablet touch kit for the React web client: gesture engine (two-finger right click and
// scroll, pinch-to-zoom, touch / trackpad modes), floating shortcut toolbar and the desktop
// keyboard sheet with sticky modifiers ("PC keyboard"; the top bar's Keyboard button keeps the
// system keyboard with IME / Unicode input). Audio stays with DataChannelAudio (src/lib/audio.ts),
// which now uses ./unlock.ts for WebAudio auto-resume.
import { TouchController, type TouchOptions } from './touch';
import { KeyboardModel } from './keyboard';
import { KeyboardSheet } from './keyboard-ui';
import { FloatingToolbar, type ToolItem } from './toolbar';
import type { InputSink } from './protocol';
import { injectStyles } from './styles';

export interface TouchKitOptions {
  stage: HTMLElement;
  video: HTMLVideoElement;
  sink: InputSink;
  touch?: TouchOptions;
  extraTools?: ToolItem[];
  onFullscreen?: () => void;
  /** Sound toggle: returns whether sound is on after the tap. */
  sound?: { toggle: () => void; on: () => boolean };
  onModeChange?: (m: 'direct' | 'trackpad') => void;
  forceToolbar?: boolean;
}

export interface TouchKit {
  touch: TouchController;
  keyboard: KeyboardModel;
  sheet: KeyboardSheet;
  toolbar: FloatingToolbar | null;
  toast(text: string, ms?: number): void;
  refresh(): void;
  detach(): void;
}

export function isTouchDevice(): boolean {
  return (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0) || (typeof matchMedia !== 'undefined' && matchMedia('(pointer: coarse)').matches);
}

export function attachTouchKit(o: TouchKitOptions): TouchKit {
  injectStyles();
  const { stage, video, sink } = o;

  const toastEl = document.createElement('div');
  toastEl.className = 'lst-toast';
  toastEl.hidden = true;
  toastEl.setAttribute('role', 'status');
  stage.appendChild(toastEl);
  let toastT: ReturnType<typeof setTimeout> | null = null;
  const toast = (t: string, ms = 2200) => {
    toastEl.textContent = t;
    toastEl.hidden = false;
    if (toastT) clearTimeout(toastT);
    toastT = setTimeout(() => (toastEl.hidden = true), ms);
  };

  const keyboard = new KeyboardModel(sink);
  const sheet = new KeyboardSheet(stage, keyboard, toast);
  for (const n of ['pointerdown', 'pointermove', 'pointerup', 'pointercancel']) sheet.el.addEventListener(n, (e) => e.stopPropagation());

  let toolbar: FloatingToolbar | null = null;
  const touch = new TouchController(stage, video, sink, {
    ...o.touch,
    onThreeFingerTap: () => { sheet.toggle(); toolbar?.refresh(); },
    onPointerAction: () => keyboard.afterPointerAction(),
    onModeChange: (m) => {
      toolbar?.setLabel('mode', m === 'trackpad' ? 'Trackpad' : 'Touch', m === 'trackpad' ? '▭' : '☝');
      o.onModeChange?.(m);
    },
    onZoom: () => toolbar?.refresh(),
  });

  const items: ToolItem[] = [
    { id: 'keyboard', label: 'PC keyboard', icon: '⌨', onClick: () => sheet.toggle(), active: () => sheet.open },
    {
      id: 'mode', label: touch.mode === 'trackpad' ? 'Trackpad' : 'Touch', icon: touch.mode === 'trackpad' ? '▭' : '☝',
      onClick: () => { const m = touch.toggleMode(); toast(m === 'trackpad' ? 'Trackpad mode: slide to move the pointer, tap to click' : 'Touch mode: tap where you want to click'); },
      active: () => touch.mode === 'trackpad',
    },
    { id: 'rclick', label: 'Right click', icon: '◨', onClick: () => { sink.push([3, 1, 1, 0, 0]); sink.push([3, 0, 1, 0, 0]); keyboard.afterPointerAction(); } },
    { id: 'zoom', label: 'Fit screen', icon: '⤢', onClick: () => touch.resetZoom(), active: () => touch.viewport.zoomed },
    { id: 'taskMgr', label: 'Task Mgr', icon: '▤', onClick: () => keyboard.shortcut('taskMgr') },
    { id: 'altTab', label: 'Alt+Tab', icon: '⇆', onClick: () => keyboard.shortcut('altTab') },
    { id: 'cad', label: 'Ctrl+Alt+Del', icon: '⎋', onClick: () => keyboard.shortcut('cad') },
  ];
  if (o.onFullscreen) items.push({ id: 'full', label: 'Fullscreen', icon: '⛶', onClick: () => o.onFullscreen!() });
  if (o.sound) items.push({ id: 'sound', label: 'Sound', icon: '🔊', onClick: () => o.sound!.toggle(), active: () => o.sound!.on() });
  items.push(...(o.extraTools ?? []));

  if (o.forceToolbar || isTouchDevice()) toolbar = new FloatingToolbar(stage, items);

  sheet.onVisibility = (open, h) => {
    stage.style.setProperty('--lst-kb-h', `${Math.round(h)}px`);
    stage.dataset.lstKb = open ? '1' : '0';
    toolbar?.refresh();
  };

  const onHide = () => { if (document.hidden) keyboard.releaseAll(); };
  document.addEventListener('visibilitychange', onHide);

  return {
    touch, keyboard, sheet, toolbar, toast,
    refresh: () => toolbar?.refresh(),
    detach() {
      document.removeEventListener('visibilitychange', onHide);
      keyboard.releaseAll();
      touch.detach();
      sheet.destroy();
      toolbar?.destroy();
      if (toastT) clearTimeout(toastT);
      toastEl.remove();
      stage.classList.remove('lst-stage');
      video.classList.remove('lst-video');
    },
  };
}
