import { useEffect, useMemo, useState, type ReactNode } from 'react';
import type { Settings } from '../lib/settings';
import type { ConnectRequest } from './ConnectScreen';
import {
  CAR_PRESETS,
  GENERIC_PRESET,
  buildCarLink,
  carCodec,
  detectCar,
  dockLayoutFor,
  extractCarLink,
  netPolicy,
  presetById,
  teslaTheaterUrl,
  type CarControl,
  type CarNet,
  type CarPreset,
} from '../lib/car';
import { useViewport } from '../lib/useViewport';

interface Props {
  settings: Settings;
  setSettings: (p: Partial<Settings>) => void;
  onConnect: (r: ConnectRequest) => void;
  error: string | null;
  busy: boolean;
}

const CONTROL_LABEL: Record<CarControl, [string, string, string]> = {
  direct: ['👆', '平板直触', 'Direct Touch'],
  trackpad: ['🖐️', '巨幅触控板', 'Giant Trackpad'],
  gamepad: ['🎮', '虚拟手柄 + 双蓝牙手柄', 'Gamepad · 2P'],
};
const NET_LABEL: Record<CarNet, [string, string]> = {
  auto: ['自动', 'Auto'],
  lan: ['Wi-Fi 低延迟', 'Wi-Fi / Hotspot'],
  cellular: ['5G/LTE 驻车缓冲', '8–20 Mbps H.264'],
};

export function CarLauncher({ settings, setSettings, onConnect, error, busy }: Props) {
  const [code, setCode] = useState<string>(() => settings.lastCode || '');
  const [copied, setCopied] = useState(false);
  const vp = useViewport();
  const layout = dockLayoutFor(vp.w, vp.h);
  const preset = presetById(settings.carBrand);
  const detected = useMemo(() => detectCar(), []);
  const codec = carCodec(preset, settings.carNet, settings.codec, settings.carCodecLock);
  const net = netPolicy(settings.carNet);
  const canConnect = !busy && /^\d{6}$/.test(code) && settings.signalUrl.trim().length > 0;
  const insecureWs = location.protocol === 'https:' && /^ws:\/\//i.test(settings.signalUrl.trim());

  useEffect(() => {
    if (settings.lastCode && /^\d{6}$/.test(settings.lastCode) && settings.lastCode !== code) {
      setCode(settings.lastCode);
    }
  }, [settings.lastCode]);

  useEffect(() => {
    if (settings.lastCode !== code) setSettings({ lastCode: code });
  }, [code, settings.lastCode, setSettings]);

  const handleSignalInput = (raw: string) => {
    const link = extractCarLink(raw);
    if (link?.wss) {
      setSettings({
        signalUrl: link.wss,
        ...(link.code ? { lastCode: link.code, authMode: 'code' as const } : {}),
        ...(link.brand ? { carBrand: link.brand } : {}),
        ...(link.codec ? { codec: link.codec, carCodecLock: true } : {}),
      });
      if (link.code) setCode(link.code);
      return;
    }
    setSettings({ signalUrl: raw });
  };

  const press = (k: string) => {
    if (k === '⌫') setCode((c) => c.slice(0, -1));
    else if (k === '清空') setCode('');
    else setCode((c) => (c.length < 6 ? c + k : c));
  };

  // Physical keyboards (some cars have BT keyboards / steering-wheel digit input).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement)?.tagName === 'INPUT') return;
      if (/^\d$/.test(e.key)) press(e.key);
      else if (e.key === 'Backspace') press('⌫');
      else if (e.key === 'Enter' && canConnect) onConnect({ code });
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  const theaterLink = () => {
    const target = settings.signalUrl && /^\d{6}$/.test(code) ? buildCarLink(location.href, settings.signalUrl, code, 'tesla') : `${location.href.split('#')[0]}#car=1&brand=tesla`;
    return teslaTheaterUrl(target);
  };

  const brands = (
    <section aria-label="Car brand presets">
      <SectionTitle zh="选择车型 · 一键预设" en="Pick your car" />
      <div className={`grid gap-3 ${layout === 'rail' ? 'grid-cols-3' : vp.w < 700 ? 'grid-cols-2' : 'grid-cols-3'}`}>
        {CAR_PRESETS.map((p) => (
          <BrandCard key={p.id} p={p} selected={settings.carBrand === p.id} detected={detected.brand === p.id} onClick={() => setSettings({ carBrand: p.id })} />
        ))}
        <BrandCard p={GENERIC_PRESET} selected={settings.carBrand === 'generic'} detected={detected.brand === 'generic'} onClick={() => setSettings({ carBrand: 'generic' })} />
      </div>
    </section>
  );

  const pairing = (
    <section aria-label="Pairing" className="car-glass rounded-3xl p-5">
      <SectionTitle zh="连接电脑" en="Pair with your PC" />
      <label className="mb-1 block text-sm text-slate-400">信令地址 Signaling URL</label>
      <input
        className="car-input w-full rounded-2xl border border-white/10 bg-black/50 px-4 text-lg text-white placeholder:text-slate-600 focus:border-cyan-400 focus:outline-none"
        placeholder="wss://my-pc.example.com:47901/ws"
        value={settings.signalUrl}
        onChange={(e) => handleSignalInput(e.target.value)}
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck={false}
        inputMode="url"
      />
      {insecureWs && <p className="mt-1 text-sm text-amber-400">HTTPS 页面必须使用 wss://</p>}

      <div className="mt-4 flex justify-between gap-2" aria-label="Pairing code" data-testid="code-display">
        {Array.from({ length: 6 }, (_, i) => (
          <div
            key={i}
            className={`flex h-16 flex-1 items-center justify-center rounded-2xl border-2 font-mono text-4xl font-semibold ${i === code.length ? 'border-cyan-400' : code[i] ? 'border-cyan-400/40' : 'border-white/10'} bg-black/50 text-white ${i === 2 ? 'mr-2' : ''}`}
          >
            {code[i] ?? ''}
          </div>
        ))}
      </div>

      <div className="mt-3 grid grid-cols-3 gap-2" role="group" aria-label="Numpad">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9', '清空', '0', '⌫'].map((k) => (
          <button
            key={k}
            onClick={() => press(k)}
            aria-label={k === '⌫' ? 'Backspace' : k === '清空' ? 'Clear' : `Digit ${k}`}
            className={`car-btn rounded-2xl text-3xl font-semibold active:scale-95 transition ${/\d/.test(k) ? 'bg-white/10 text-white hover:bg-white/15' : 'bg-white/5 text-lg text-slate-300'}`}
          >
            {k}
          </button>
        ))}
      </div>

      {error && <div className="mt-3 rounded-2xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-base text-red-300">{error}</div>}

      <button
        disabled={!canConnect}
        onClick={() => onConnect({ code })}
        className="car-btn-xl mt-4 w-full rounded-2xl bg-gradient-to-r from-cyan-400 to-violet-500 text-xl font-bold text-black disabled:opacity-30"
      >
        {busy ? '连接中… Connecting' : '连接 Connect'}
      </button>
      <button
        onClick={() => onConnect({ demo: true })}
        disabled={busy}
        className="car-btn-xl mt-3 w-full rounded-2xl border-2 border-violet-400/50 bg-violet-500/10 text-lg font-semibold text-violet-100"
      >
        🚗 车机大屏实机演示 (Car Cockpit Demo)
      </button>
    </section>
  );

  const options = (
    <section aria-label="Car options" className="space-y-4">
      <div>
        <SectionTitle zh="操控模式" en="Control mode" />
        <div className="grid grid-cols-3 gap-2">
          {(Object.keys(CONTROL_LABEL) as CarControl[]).map((m) => (
            <Seg key={m} on={settings.carControl === m} onClick={() => setSettings({ carControl: m })}>
              <span className="text-2xl">{CONTROL_LABEL[m][0]}</span>
              <span className="text-base font-semibold">{CONTROL_LABEL[m][1]}</span>
              <span className="text-xs text-slate-400">{CONTROL_LABEL[m][2]}</span>
            </Seg>
          ))}
        </div>
      </div>
      <div>
        <SectionTitle zh="网络预设" en="Network" />
        <div className="grid grid-cols-3 gap-2">
          {(Object.keys(NET_LABEL) as CarNet[]).map((n) => (
            <Seg key={n} on={settings.carNet === n} onClick={() => setSettings({ carNet: n })}>
              <span className="text-base font-semibold">{NET_LABEL[n][0]}</span>
              <span className="text-xs text-slate-400">{NET_LABEL[n][1]}</span>
            </Seg>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <Seg on={settings.carSeat === 'center'} onClick={() => setSettings({ carSeat: 'center' })}>
          <span className="text-base font-semibold">中控屏</span>
          <span className="text-xs text-slate-400">Center display</span>
        </Seg>
        <Seg on={settings.carSeat === 'passenger'} onClick={() => setSettings({ carSeat: 'passenger' })}>
          <span className="text-base font-semibold">副驾 / 后排屏</span>
          <span className="text-xs text-slate-400">Passenger / rear</span>
        </Seg>
      </div>

      <div className="car-glass rounded-2xl p-4 text-sm text-slate-300" data-testid="preset-summary">
        <div className="mb-1 text-base font-semibold text-white">
          {preset.emoji} {preset.name} {preset.nameEn}
        </div>
        <div>{preset.screen}</div>
        <div className="mt-1">
          编码 Codec <b className="text-cyan-300">{codec === 'auto' ? 'Auto' : codec.toUpperCase()}</b>
          {(preset.lockCodec || settings.carCodecLock) && <span className="text-amber-300"> · 已锁定 locked</span>} · {net.label} {net.minKbps / 1000}–{net.maxKbps / 1000} Mbps · 1080p60 · Opus 96k
        </div>
      </div>

      {preset.teslaTheater && (
        <div className="car-glass rounded-2xl border border-red-500/30 p-4" data-testid="tesla-theater">
          <div className="text-base font-semibold text-white">Tesla 全屏剧场模式跳转</div>
          <p className="mt-1 text-sm text-slate-400">
            驻车时打开 剧场 Theater → YouTube,再访问下方链接:特斯拉浏览器将以全屏打开 LeeStream(去掉地址栏)。
          </p>
          <div className="mt-3 grid grid-cols-2 gap-2">
            <a className="car-btn flex items-center justify-center rounded-2xl bg-red-600 text-base font-semibold text-white" href={theaterLink()}>
              ▶ 全屏跳转 Go fullscreen
            </a>
            <button
              className="car-btn rounded-2xl bg-white/10 text-base font-semibold text-white"
              onClick={() =>
                void navigator.clipboard?.writeText(theaterLink()).then(
                  () => setCopied(true),
                  () => setCopied(false),
                )
              }
            >
              {copied ? '✓ 已复制' : '复制链接 Copy'}
            </button>
          </div>
        </div>
      )}
    </section>
  );

  return (
    <div className="car-root min-h-full bg-[radial-gradient(ellipse_at_top,_#0b2233_0%,_#03040a_65%)] p-5 text-slate-100" data-testid="car-launcher" data-layout={layout}>
      <header className="mb-5 flex flex-wrap items-center gap-3">
        <img src="./favicon.svg" alt="" className="h-12 w-12" />
        <div className="mr-auto">
          <h1 className="text-3xl font-bold tracking-tight text-white">LeeStream 🚗 车载座舱模式</h1>
          <p className="text-base text-slate-400">Car Cockpit Mode · zero-install · {preset.emoji} {preset.nameEn}</p>
        </div>
        {detected.brand && (
          <span className="rounded-full border border-emerald-400/40 bg-emerald-400/10 px-4 py-2 text-sm text-emerald-200">
            已识别车机 Detected: {presetById(detected.brand).nameEn}
          </span>
        )}
        <button onClick={() => setSettings({ carMode: false })} className="car-btn rounded-2xl border border-white/15 px-5 text-base text-slate-200" aria-label="Exit car mode">
          🖥️ 标准模式
        </button>
      </header>

      {!settings.carParkedAck && (
        <div className="mb-5 flex flex-wrap items-center gap-4 rounded-2xl border border-amber-400/40 bg-amber-400/10 p-4" role="note" data-testid="parked-ack">
          <span className="text-3xl">🅿️</span>
          <p className="mr-auto max-w-3xl text-base text-amber-100">
            <b>P 档驻车安全提示:</b>串流仅供驻车(P 档)或副驾/后排乘客使用。中控屏在车速超过 5 km/h 时会自动暂停画面。
            <span className="block text-sm text-amber-200/70">Parked use only on the center display — video pauses automatically above 5 km/h.</span>
          </p>
          <button onClick={() => setSettings({ carParkedAck: true })} className="car-btn rounded-2xl bg-amber-400 px-6 text-base font-bold text-black">
            我已驻车 · I'm parked
          </button>
        </div>
      )}

      {layout === 'rail' ? (
        <div className="grid grid-cols-[1.35fr_1fr] gap-5">
          <div className="space-y-5">
            {brands}
            {options}
          </div>
          <div>{pairing}</div>
        </div>
      ) : (
        <div className="space-y-5">
          {pairing}
          {brands}
          {options}
        </div>
      )}
    </div>
  );
}

function BrandCard({ p, selected, detected, onClick }: { p: CarPreset; selected: boolean; detected: boolean; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      aria-pressed={selected}
      aria-label={`Preset ${p.nameEn}`}
      className={`relative min-h-[112px] rounded-2xl border-2 p-3 text-left transition active:scale-[0.98] ${selected ? 'bg-white/10' : 'border-white/10 bg-white/[0.03] hover:bg-white/[0.06]'}`}
      style={selected ? { borderColor: p.accent, boxShadow: `0 0 0 3px ${p.accent}33` } : undefined}
    >
      <div className="flex items-center gap-2">
        <span className="text-2xl">{p.emoji}</span>
        <span className="text-lg font-bold text-white">{p.name}</span>
        <span className="text-sm text-slate-400">{p.nameEn}</span>
      </div>
      <div className="mt-1 text-xs text-slate-400">{p.models}</div>
      <div className="mt-0.5 text-xs text-slate-300">{p.screen}</div>
      <div className="mt-2 flex flex-wrap gap-1">
        {p.features.slice(0, 2).map((f) => (
          <span key={f} className="rounded-full bg-black/40 px-2 py-0.5 text-[11px] text-slate-300">
            {f}
          </span>
        ))}
      </div>
      {detected && <span className="absolute right-2 top-2 rounded-full bg-emerald-400 px-2 py-0.5 text-[10px] font-bold text-black">AUTO</span>}
    </button>
  );
}

function Seg({ on, onClick, children }: { on: boolean; onClick: () => void; children: ReactNode }) {
  return (
    <button
      onClick={onClick}
      aria-pressed={on}
      className={`car-btn flex flex-col items-center justify-center gap-0.5 rounded-2xl border-2 px-2 py-2 transition ${on ? 'border-cyan-400 bg-cyan-400/15 text-white' : 'border-white/10 bg-white/[0.04] text-slate-300'}`}
    >
      {children}
    </button>
  );
}

function SectionTitle({ zh, en }: { zh: string; en: string }) {
  return (
    <h2 className="mb-2 flex items-baseline gap-2">
      <span className="text-xl font-bold text-white">{zh}</span>
      <span className="text-sm uppercase tracking-wider text-slate-500">{en}</span>
    </h2>
  );
}
