/**
 * In-Car Big-Screen Cockpit mode (车载大屏座舱专享模式).
 *
 * - Brand presets (screen geometry, codec policy, layout hints, special helpers)
 * - User-Agent + screen-shape auto-detection
 * - URL hash deep links: #car=1&wss=wss://pc:47901/ws&code=482915&brand=tesla&ctl=trackpad&net=5g&seat=passenger&go=1
 *
 * NOTE: car UA tokens below are heuristics collected from public reports; they are not
 * verified on every head unit. Detection only *suggests* a preset — the user can always pick one.
 */
import type { CodecPref } from './session';

export type CarBrand = 'tesla' | 'liauto' | 'xiaomi' | 'harmony' | 'nio' | 'byd' | 'xpeng' | 'zeekr' | 'generic';
export type CarControl = 'direct' | 'trackpad' | 'gamepad';
export type CarNet = 'auto' | 'lan' | 'cellular';
export type CarSeat = 'center' | 'passenger';
export type DockLayout = 'rail' | 'stack'; // rail: landscape side rail · stack: top bar + bottom dock (square / portrait)

export interface CarPreset {
  id: CarBrand;
  name: string; // zh
  nameEn: string;
  models: string;
  screen: string; // human description
  /** Native panel resolution (landscape orientation unless portraitNative). */
  px: [number, number];
  aspect: string;
  /** Codec policy. `lockCodec` means the user cannot override it in car mode. */
  codec: CodecPref;
  lockCodec?: boolean;
  /** Feature flags rendered as chips + enabling helpers. */
  features: string[];
  accent: string; // tailwind-safe hex
  rotatable?: boolean;
  teslaTheater?: boolean;
  passengerLock?: boolean;
  emoji: string;
}

