// ── detection ───────────────────────────────────────────────────────────────
const UA_RULES: Array<[RegExp, CarBrand]> = [
  [/QtCarBrowser|\bTesla\b/i, 'tesla'],
  [/LiAuto|LiXiang|\bLi_?OS\b/i, 'liauto'],
  [/XiaomiEV|Xiaomi.?Car|\bSU7\b/i, 'xiaomi'],
  [/ArkWeb|OpenHarmony|HarmonyOS|AITO|HIMA/i, 'harmony'],
  [/\bNIO\b|Banyan|SkyOS/i, 'nio'],
  [/DiLink|\bBYD\b/i, 'byd'],
  [/XPeng|Xmart|XOS/i, 'xpeng'],
  [/ZEEKR/i, 'zeekr'],
];
const GENERIC_CAR_UA = /Android Automotive|\bAAOS\b|Automotive|SA8155|SA8295|\b8155\b|\b8295\b|CarBrowser|Infotainment|\bIVI\b/i;

export interface CarDetection {
  isCar: boolean;
  brand: CarBrand | null;
  reason: string;
}

/** UA first (strong signal), then screen shape (weak, only suggests). */
export function detectCar(ua: string = navigator.userAgent, w: number = screen.width, h: number = screen.height): CarDetection {
  for (const [re, brand] of UA_RULES) if (re.test(ua)) return { isCar: true, brand, reason: `UA ${re.source.split('|')[0]}` };
  if (GENERIC_CAR_UA.test(ua)) return { isCar: true, brand: 'generic', reason: 'UA automotive' };
  // Shape heuristic: exact car panel resolutions that are uncommon on laptops/tablets.
  const key = `${Math.max(w, h)}x${Math.min(w, h)}`;
  const shapes: Record<string, CarBrand> = { '1888x1728': 'nio', '944x864': 'nio' };
  if (shapes[key]) return { isCar: false, brand: shapes[key], reason: `screen ${key}` };
  return { isCar: false, brand: null, reason: 'none' };
}

// ── hash deep link ──────────────────────────────────────────────────────────
/**
 * Host `car_gateway.rs` QR contract brand ids → client preset ids.
 * (Client ids are accepted too, so older links keep working.)
 */
export const GATEWAY_BRAND: Record<string, CarBrand> = {
  tesla: 'tesla',
  li_auto: 'liauto',
  xiaomi_su7: 'xiaomi',
  aito: 'harmony',
  nio: 'nio',
  xpeng: 'xpeng',
  byd: 'byd',
  zeekr: 'zeekr',
  // aliases
  liauto: 'liauto',
  xiaomi: 'xiaomi',
  harmony: 'harmony',
  generic: 'generic',
};
export const CLIENT_TO_GATEWAY: Record<CarBrand, string> = {
  tesla: 'tesla',
  liauto: 'li_auto',
  xiaomi: 'xiaomi_su7',
  harmony: 'aito',
  nio: 'nio',
  xpeng: 'xpeng',
  byd: 'byd',
  zeekr: 'zeekr',
  generic: 'generic',
};

