export interface CarLink {
  car: boolean;
  codec?: CodecPref;
  demo: boolean;
  wss?: string;
  code?: string;
  brand?: CarBrand;
  control?: CarControl;
  net?: CarNet;
  seat?: CarSeat;
  go: boolean;
}

/**
 * Host QR contract (car_gateway.rs):
 *   #car=1&wss=wss%3A%2F%2F…&code=482913&codec=h264[&brand=tesla|li_auto|xiaomi_su7|aito|nio|xpeng|byd|zeekr]
 * Parsed exactly as `new URLSearchParams(location.hash.slice(1))` (values are percent-decoded by URLSearchParams).
 * Client extensions (optional): ctl=direct|trackpad|gamepad, net=5g|lan, seat=passenger, demo=1, go=1; `sig=` is accepted for `wss=`.
 */
export function parseCarHash(hash: string = location.hash): CarLink {
  const q = new URLSearchParams(hash.startsWith('#') ? hash.slice(1) : hash);
  const brandRaw = (q.get('brand') ?? '').toLowerCase();
  const codecRaw = (q.get('codec') ?? '').toLowerCase();
  const ctl = q.get('ctl') ?? q.get('mode');
  const net = q.get('net');
  const seat = q.get('seat');
  const code = (q.get('code') ?? '').replace(/\D/g, '');
  const wss = q.get('wss') ?? q.get('sig') ?? undefined;
  return {
    car: q.has('car') && q.get('car') !== '0',
    codec: codecRaw === 'h264' || codecRaw === 'hevc' || codecRaw === 'av1' ? (codecRaw as CodecPref) : undefined,
    demo: q.get('demo') === '1',
    wss: wss && /^wss?:\/\//i.test(wss) ? wss : undefined,
    code: /^\d{6}$/.test(code) ? code : undefined,
    brand: GATEWAY_BRAND[brandRaw],
    control: ctl === 'direct' || ctl === 'trackpad' || ctl === 'gamepad' ? ctl : undefined,
    net: net === '5g' || net === 'lte' || net === 'cellular' ? 'cellular' : net === 'lan' || net === 'wifi' ? 'lan' : undefined,
    seat: seat === 'passenger' || seat === 'rear' ? 'passenger' : seat === 'center' || seat === 'driver' ? 'center' : undefined,
    go: q.get('go') === '1',
  };
}

/** Build the short link a host can show as a QR code. */
export function buildCarLink(base: string, wss: string, code: string, brand?: CarBrand): string {
  const q = new URLSearchParams({ car: '1', wss });
  if (code) q.set('code', code);
  q.set('codec', 'h264');
  if (brand && brand !== 'generic') q.set('brand', CLIENT_TO_GATEWAY[brand]);
  return `${base.split('#')[0]}#${q.toString()}`;
}

/**
 * Unwrap an accidentally pasted full LeeStream share URL
 * (e.g. `https://meilihulee.github.io/leestream/web/#car=1&wss=...&code=715082`)
 * so pasting the whole link into the Signaling URL box "just works".
 */
export function extractCarLink(raw: string): CarLink | null {
  const s = raw.trim();
  if (!s) return null;
  const hashIdx = s.indexOf('#');
  if (hashIdx >= 0) {
    const parsed = parseCarHash(s.slice(hashIdx));
    if (parsed.wss || parsed.car || parsed.code) return parsed;
  }
  const qIdx = s.indexOf('?');
  if (qIdx >= 0) {
    const qPart = s.slice(qIdx + 1).split('#')[0];
    const parsed = parseCarHash(qPart);
    if (parsed.wss || parsed.code) return parsed;
  }
  if (/^(?:car|wss|sig)=/i.test(s)) {
    const parsed = parseCarHash(s);
    if (parsed.wss || parsed.code) return parsed;
  }
  return null;
}

// ── layout ──────────────────────────────────────────────────────────────────
export function dockLayoutFor(w: number, h: number): DockLayout {
  return w / h >= 1.3 ? 'rail' : 'stack';
}

// ── network presets ─────────────────────────────────────────────────────────
export interface NetPolicy {
  label: string;
  minKbps: number;
  maxKbps: number;
  startKbps: number;
  jitterTargetMs: number; // receiver jitter-buffer target (0 = render ASAP)
  forceH264: boolean;
}

export function netPolicy(net: CarNet): NetPolicy {
  switch (net) {
    case 'cellular':
      return { label: '5G/LTE 驻车缓冲', minKbps: 8000, maxKbps: 20000, startKbps: 12000, jitterTargetMs: 120, forceH264: true };
    case 'lan':
      return { label: 'Wi-Fi 低延迟', minKbps: 10000, maxKbps: 50000, startKbps: 25000, jitterTargetMs: 0, forceH264: false };
    default:
      return { label: '自动', minKbps: 8000, maxKbps: 30000, startKbps: 15000, jitterTargetMs: 40, forceH264: false };
  }
}

/** Simple AIMD on loss: called every stats tick with the current target. */
export function adaptBitrate(cur: number, lossPct: number | null, rttMs: number | null, p: NetPolicy): number {
  if (lossPct === null) return cur;
  if (lossPct > 2 || (rttMs !== null && rttMs > 250)) return Math.max(p.minKbps, Math.round(cur * 0.85));
  if (lossPct < 0.3 && (rttMs === null || rttMs < 120)) return Math.min(p.maxKbps, Math.round(cur * 1.05));
  return cur;
}

/** Effective codec for a car session. */
export function carCodec(preset: CarPreset, net: CarNet, user: CodecPref, linkLock = false): CodecPref {
  if (linkLock) return user === 'auto' ? 'h264' : user;
  if (preset.lockCodec) return preset.codec;
  if (netPolicy(net).forceH264) return 'h264';
  return user === 'auto' ? preset.codec : user;
}

/** Tesla "Theater" escape: opening a URL via YouTube's redirector from the Theater YouTube app keeps the full-screen browser. */
export function teslaTheaterUrl(target: string): string {
  return `https://www.youtube.com/redirect?q=${encodeURIComponent(target)}`;
}

