import { useEffect, useRef, type PointerEvent as RPointerEvent, type ReactNode } from 'react';
import { XI } from '../lib/protocol';
import type { GamepadPoller } from '../lib/gamepad';

/**
 * Giant on-screen Xbox-layout gamepad for car touchscreens. Emits the same 20-byte
 * GAMEPAD reports as physical pads, on its own XInput slot (claimed from the shared pool),
 * so it coexists with up to 3 Bluetooth/USB controllers for 2-player play.
 */
export function VirtualGamepad({ poller, layout }: { poller: GamepadPoller; layout: 'rail' | 'stack' }) {
  const st = useRef({ buttons: 0, lx: 0, ly: 0, rx: 0, ry: 0, lt: 0, rt: 0 });
  const slot = useRef<number | undefined>(undefined);

  const send = () => poller.sendVirtual({ ...st.current });

  useEffect(() => {
    slot.current = poller.claimVirtual();
    send();
    const hb = window.setInterval(send, 100); // host idles a pad after ~500 ms of silence
    return () => {
      clearInterval(hb);
      poller.releaseVirtual();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [poller]);

  const btn = (bit: number, down: boolean) => {
    const s = st.current;
    s.buttons = down ? s.buttons | bit : s.buttons & ~bit;
    send();
  };
  const trig = (which: 'lt' | 'rt', down: boolean) => {
    st.current[which] = down ? 255 : 0;
    send();
  };

  const compact = layout === 'stack';
  return (
    <div className="vpad pointer-events-none absolute inset-0 flex items-end justify-between p-4 select-none" data-testid="virtual-gamepad">
      {/* left cluster */}
      <div className="pointer-events-auto flex flex-col items-center gap-3">
        <div className="flex gap-2">
          <PadBtn label="LT" onChange={(d) => trig('lt', d)} small />
          <PadBtn label="LB" onChange={(d) => btn(XI.LEFT_SHOULDER, d)} small />
        </div>
        <Stick size={compact ? 150 : 180} onMove={(x, y) => ((st.current.lx = x), (st.current.ly = y), send())} label="L" />
        <div className="grid grid-cols-3 gap-1">
          <span />
          <PadBtn label="▲" onChange={(d) => btn(XI.DPAD_UP, d)} small />
          <span />
          <PadBtn label="◀" onChange={(d) => btn(XI.DPAD_LEFT, d)} small />
          <span />
          <PadBtn label="▶" onChange={(d) => btn(XI.DPAD_RIGHT, d)} small />
          <span />
          <PadBtn label="▼" onChange={(d) => btn(XI.DPAD_DOWN, d)} small />
          <span />
        </div>
      </div>

      {/* center */}
      <div className="pointer-events-auto mb-2 flex flex-col items-center gap-2">
        <span className="rounded-full bg-black/60 px-3 py-1 text-xs text-slate-300">
          虚拟手柄 · P{(slot.current ?? 0) + 1}
        </span>
        <div className="flex gap-3">
          <PadBtn label="⧉ Back" onChange={(d) => btn(XI.BACK, d)} small />
          <PadBtn label="☰ Start" onChange={(d) => btn(XI.START, d)} small />
        </div>
      </div>

      {/* right cluster */}
      <div className="pointer-events-auto flex flex-col items-center gap-3">
        <div className="flex gap-2">
          <PadBtn label="RB" onChange={(d) => btn(XI.RIGHT_SHOULDER, d)} small />
          <PadBtn label="RT" onChange={(d) => trig('rt', d)} small />
        </div>
        <div className="grid grid-cols-3 gap-2">
          <span />
          <PadBtn label="Y" color="#facc15" onChange={(d) => btn(XI.Y, d)} />
          <span />
          <PadBtn label="X" color="#3b82f6" onChange={(d) => btn(XI.X, d)} />
          <span />
          <PadBtn label="B" color="#ef4444" onChange={(d) => btn(XI.B, d)} />
          <span />
          <PadBtn label="A" color="#22c55e" onChange={(d) => btn(XI.A, d)} />
          <span />
        </div>
        <Stick size={compact ? 120 : 140} onMove={(x, y) => ((st.current.rx = x), (st.current.ry = y), send())} label="R" />
      </div>
    </div>
  );
}

function PadBtn({ label, onChange, color, small }: { label: ReactNode; onChange: (down: boolean) => void; color?: string; small?: boolean }) {
  const down = (e: RPointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* ignore */
    }
    e.currentTarget.dataset.down = '1';
    onChange(true);
  };
  const up = (e: RPointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.currentTarget.dataset.down !== '1') return;
    e.currentTarget.dataset.down = '';
    onChange(false);
  };
  return (
    <button
      aria-label={`Pad ${typeof label === 'string' ? label : ''}`}
      onPointerDown={down}
      onPointerUp={up}
      onPointerCancel={up}
      onContextMenu={(e) => e.preventDefault()}
      className={`vpad-btn flex items-center justify-center rounded-full border-2 font-bold text-white shadow-lg ${small ? 'h-14 min-w-14 px-3 text-sm' : 'h-[68px] w-[68px] text-2xl'}`}
      style={{ borderColor: color ?? 'rgba(255,255,255,0.25)', background: color ? `${color}33` : 'rgba(10,12,18,0.7)', touchAction: 'none' }}
    >
      {label}
    </button>
  );
}

/** Analog stick: drag within the ring; returns XInput i16 with up = +. */
function Stick({ size, onMove, label }: { size: number; onMove: (x: number, y: number) => void; label: string }) {
  const ring = useRef<HTMLDivElement>(null);
  const knob = useRef<HTMLDivElement>(null);
  const active = useRef<number | null>(null);

  const update = (cx: number, cy: number) => {
    const r = ring.current!.getBoundingClientRect();
    const R = r.width / 2;
    let dx = cx - (r.left + R);
    let dy = cy - (r.top + R);
    const m = Math.hypot(dx, dy);
    if (m > R) {
      dx = (dx / m) * R;
      dy = (dy / m) * R;
    }
    knob.current!.style.transform = `translate(${dx}px, ${dy}px)`;
    onMove(Math.round((dx / R) * 32767), Math.round((-dy / R) * 32767));
  };
  const reset = () => {
    active.current = null;
    knob.current!.style.transform = 'translate(0px, 0px)';
    onMove(0, 0);
  };

  return (
    <div
      ref={ring}
      aria-label={`Stick ${label}`}
      className="relative flex items-center justify-center rounded-full border-2 border-white/20 bg-black/55"
      style={{ width: size, height: size, touchAction: 'none' }}
      onPointerDown={(e) => {
        e.preventDefault();
        e.stopPropagation();
        active.current = e.pointerId;
        try {
          e.currentTarget.setPointerCapture(e.pointerId);
        } catch {
          /* ignore */
        }
        update(e.clientX, e.clientY);
      }}
      onPointerMove={(e) => {
        if (active.current !== e.pointerId) return;
        e.preventDefault();
        update(e.clientX, e.clientY);
      }}
      onPointerUp={(e) => active.current === e.pointerId && reset()}
      onPointerCancel={(e) => active.current === e.pointerId && reset()}
    >
      <div ref={knob} className="h-1/2 w-1/2 rounded-full border-2 border-cyan-300/70 bg-cyan-400/25 transition-none" />
      <span className="pointer-events-none absolute text-xs font-semibold text-white/40">{label}</span>
    </div>
  );
}
