// Vendored from leestream-touch (2026-11-26 package, src/keyboard-ui.ts). Wire events are translated to the
// v1.1.1 one-event-per-message input format by ./wire.ts.
// Virtual keyboard bottom sheet: sticky modifier strip, shortcut chips, full desktop layout
// (letters + Fn/nav page), and a bridge to the device's native keyboard for fast typing.
import { KeyboardModel, LAYOUT, type Mod, SHORTCUTS, type KeyDef } from './keyboard';

const MOD_LABEL: Record<Mod, string> = { ctrl: 'Ctrl', shift: 'Shift', alt: 'Alt', win: 'Win' };
const REPEATABLE = new Set(['Backspace', 'Delete', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space', 'Enter', 'Tab', 'PageUp', 'PageDown']);
const SENTINEL = '\u200b\u200b';

export class KeyboardSheet {
  readonly el: HTMLDivElement;
  private page: 'main' | 'fn' | 'off' = 'off';
  private grid: HTMLDivElement;
  private modBtns = new Map<Mod, HTMLButtonElement>();
  private native: HTMLTextAreaElement;
  private unsub: () => void;
  private held = new Map<number, string>();
  onVisibility?: (open: boolean, heightPx: number) => void;

  constructor(parent: HTMLElement, private kb: KeyboardModel, private toast?: (t: string) => void) {
    const el = (this.el = document.createElement('div'));
    el.className = 'lst-kb';
    el.setAttribute('role', 'group');
    el.setAttribute('aria-label', 'Remote keyboard');
    el.hidden = true;

    // modifier + controls strip
    const strip = document.createElement('div');
    strip.className = 'lst-kb-strip';
    (['ctrl', 'shift', 'alt', 'win'] as Mod[]).forEach((m) => {
      const b = this.btn(MOD_LABEL[m], 'lst-mod');
      b.dataset.mod = m;
      b.addEventListener('pointerdown', (e) => { e.preventDefault(); this.kb.tapModifier(m); });
      this.modBtns.set(m, b);
      strip.appendChild(b);
    });
    const sp = document.createElement('span'); sp.style.flex = '1'; strip.appendChild(sp);
    const abc = this.btn('ABC', 'lst-kb-ctl'); abc.dataset.act = 'native'; abc.title = 'Type with the device keyboard';
    abc.addEventListener('click', () => this.focusNative());
    const fn = this.btn('Fn', 'lst-kb-ctl'); fn.dataset.act = 'page';
    fn.addEventListener('click', () => { this.show(this.page === 'fn' ? 'main' : 'fn'); fn.textContent = this.page === 'fn' ? 'Keys' : 'Fn'; });
    const close = this.btn('✕', 'lst-kb-ctl'); close.dataset.act = 'close'; close.setAttribute('aria-label', 'Close keyboard');
    close.addEventListener('click', () => this.hide());
    strip.append(abc, fn, close);

    // shortcut chips
    const chips = document.createElement('div');
    chips.className = 'lst-kb-chips';
    for (const s of SHORTCUTS) {
      const c = this.btn(s.label, 'lst-chip');
      c.dataset.shortcut = s.id;
      if (s.hint) c.title = s.hint;
      c.addEventListener('click', () => this.kb.shortcut(s.id));
      chips.appendChild(c);
    }

    this.grid = document.createElement('div');
    this.grid.className = 'lst-kb-grid';

    // native keyboard bridge
    const ta = (this.native = document.createElement('textarea'));
    ta.className = 'lst-native';
    ta.setAttribute('autocapitalize', 'off');
    ta.setAttribute('autocomplete', 'off');
    ta.setAttribute('autocorrect', 'off');
    ta.spellcheck = false;
    ta.setAttribute('aria-label', 'Type to the remote computer');
    ta.value = SENTINEL;
    ta.addEventListener('input', () => this.nativeInput());
    ta.addEventListener('keydown', (e) => {
      // soft keyboards: Enter/Backspace sometimes arrive only as keydown with an empty field
      if (e.key === 'Enter') { e.preventDefault(); this.kb.press('Enter'); }
      else if (e.key === 'Backspace' && ta.value.length <= SENTINEL.length) { e.preventDefault(); this.kb.press('Backspace'); }
    });

    el.append(strip, chips, this.grid, ta);
    parent.appendChild(el);
    this.unsub = kb.onChange((s) => this.renderMods(s));
    this.renderMods(kb.state);
  }

  get open(): boolean { return this.page !== 'off'; }

  toggle(): void { if (this.open) this.hide(); else this.show('main'); }

  show(page: 'main' | 'fn' = 'main'): void {
    this.page = page;
    this.el.hidden = false;
    this.renderGrid();
    this.onVisibility?.(true, this.el.getBoundingClientRect().height);
  }

  hide(): void {
    this.page = 'off';
    this.el.hidden = true;
    this.native.blur();
    for (const code of this.held.values()) this.kb.keyUp(code);
    this.held.clear();
    this.onVisibility?.(false, 0);
  }

  focusNative(): void {
    this.native.value = SENTINEL;
    this.native.focus({ preventScroll: true });
  }

  private nativeInput(): void {
    const v = this.native.value;
    if (v.length < SENTINEL.length) {
      for (let i = v.length; i < SENTINEL.length; i++) this.kb.press('Backspace');
    } else {
      const text = v.slice(SENTINEL.length);
      if (text) {
        this.kb.typeText(text);
        if (this.kb.skipped) this.toast?.(`${this.kb.skipped} character(s) have no key on a US layout and were skipped`);
      }
    }
    this.native.value = SENTINEL;
    try { this.native.setSelectionRange(SENTINEL.length, SENTINEL.length); } catch { /* ignore */ }
  }

  private btn(label: string, cls: string): HTMLButtonElement {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = cls;
    b.textContent = label;
    return b;
  }

  private renderMods(s: Readonly<Record<Mod, string>>): void {
    for (const [m, b] of this.modBtns) {
      b.dataset.state = s[m];
      b.setAttribute('aria-pressed', s[m] === 'off' ? 'false' : 'true');
    }
    const shift = s.shift !== 'off';
    this.grid.querySelectorAll<HTMLButtonElement>('button[data-code]').forEach((b) => {
      const sh = b.dataset.shift;
      if (sh) b.textContent = shift ? sh : (b.dataset.label ?? '');
      const mod = b.dataset.mod as Mod | undefined;
      if (mod) b.dataset.state = s[mod];
    });
  }

  private renderGrid(): void {
    this.grid.textContent = '';
    if (this.page === 'off') return;
    for (const row of LAYOUT[this.page]) {
      const r = document.createElement('div');
      r.className = 'lst-kb-row';
      for (const k of row) r.appendChild(this.keyBtn(k));
      this.grid.appendChild(r);
    }
    this.renderMods(this.kb.state);
  }

  private keyBtn(k: KeyDef): HTMLButtonElement {
    const b = this.btn(k.label, 'lst-key');
    b.dataset.code = k.code;
    b.dataset.label = k.label;
    if (k.shift) b.dataset.shift = k.shift;
    if (k.mod) b.dataset.mod = k.mod;
    if (k.code === 'Space') b.setAttribute('aria-label', 'Space');
    b.style.flexGrow = String(k.w ?? 1);
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      if (k.mod) { this.kb.tapModifier(k.mod); return; }
      b.classList.add('lst-down');
      try { b.setPointerCapture(e.pointerId); } catch { /* synthetic */ }
      if (REPEATABLE.has(k.code)) { this.kb.keyDown(k.code); this.held.set(e.pointerId, k.code); }
    });
    const release = (e: PointerEvent, fire: boolean) => {
      b.classList.remove('lst-down');
      if (k.mod) return;
      const held = this.held.get(e.pointerId);
      if (held) { this.held.delete(e.pointerId); this.kb.keyUp(held); }
      else if (fire) this.kb.press(k.code);
    };
    b.addEventListener('pointerup', (e) => release(e, true));
    b.addEventListener('pointercancel', (e) => release(e, false));
    return b;
  }

  destroy(): void {
    this.hide();
    this.unsub();
    this.el.remove();
  }
}
